    return []

def _check_list_filter(self, obj):
    if not isinstance(obj.list_filter, (list, tuple)):
        return must_be('a list or tuple', option='list_filter', obj=obj, id='admin.E112')
    else:
        return list(chain.from_iterable(
            self._check_list_filter_item(obj, item, "list_filter[%d]" % index)
            for index, item in enumerate(obj.list_filter)
        ))

def _check_list_editable(self, obj):
    """ Check that list_editable is a sequence of editable fields from
    list_display without first element. """

    if not isinstance(obj.list_editable, (list, tuple)):
        return must_be('a list or tuple', option='list_editable', obj=obj, id='admin.E120')
    else:
        return list(chain.from_iterable(
            self._check_list_editable_item(obj, item, "list_editable[%d]" % index)
            for index, item in enumerate(obj.list_editable)
        ))

def _create_formsets(self, request, obj, change):
    "Helper function to generate formsets for add/change_view."
    formsets = []
    inline_instances = []
    prefixes = {}
    get_formsets_args = [request]
    if change:
        get_formsets_args.append(obj)
    for FormSet, inline in self.get_formsets_with_inlines(*get_formsets_args):
        prefix = FormSet.get_default_prefix()
        prefixes[prefix] = prefixes.get(prefix, 0) + 1
        if prefixes[prefix] != 1 or not prefix:
            prefix = "%s-%s" % (prefix, prefixes[prefix])
        formset_params = {
            'instance': obj,
            'prefix': prefix,
            'queryset': inline.get_queryset(request),
        }
        if request.method == 'POST':
            formset_params.update({
                'data': request.POST.copy(),
                'files': request.FILES,
                'save_as_new': '_saveasnew' in request.POST
            })
        formset = FormSet(**formset_params)

        def user_deleted_form(request, obj, formset, index):
            """Return whether or not the user deleted the form."""
            return (
                inline.has_delete_permission(request, obj) and
                '{}-{}-DELETE'.format(formset.prefix, index) in request.POST
            )

        # Bypass validation of each view-only inline form (since the form's
        # data won't be in request.POST), unless the form was deleted.
        if not inline.has_change_permission(request, obj if change else None):
            for index, form in enumerate(formset.initial_forms):
                if user_deleted_form(request, obj, formset, index):
                    continue
                form._errors = {}
                form.cleaned_data = form.initial
        formsets.append(formset)
        inline_instances.append(inline)
    return formsets, inline_instances

def prepopulated_fields_js(context):
    """
    Create a list of prepopulated_fields that should render Javascript for
    the prepopulated fields for both the admin form and inlines.
    """
    prepopulated_fields = []
    if 'adminform' in context:
        prepopulated_fields.extend(context['adminform'].prepopulated_fields)
    if 'inline_admin_formsets' in context:
        for inline_admin_formset in context['inline_admin_formsets']:
            for inline_admin_form in inline_admin_formset:
                if inline_admin_form.original is None:
                    prepopulated_fields.extend(inline_admin_form.prepopulated_fields)

    prepopulated_fields_json = []
    for field in prepopulated_fields:
        prepopulated_fields_json.append({
            "id": "#%s" % field["field"].auto_id,
            "name": field["field"].name,
            "dependency_ids": ["#%s" % dependency.auto_id for dependency in field["dependencies"]],
            "dependency_list": [dependency.name for dependency in field["dependencies"]],
            "maxLength": field["field"].field.max_length or 50,
            "allowUnicode": getattr(field["field"].field, "allow_unicode", False)
        })

    context.update({
        'prepopulated_fields': prepopulated_fields,
        'prepopulated_fields_json': json.dumps(prepopulated_fields_json),
    })
    return context

def check_model_name_lengths(app_configs=None, **kwargs):
    if app_configs is None:
        models = apps.get_models()
    else:
        models = chain.from_iterable(app_config.get_models() for app_config in app_configs)
    errors = []
    for model in models:
        if len(model._meta.model_name) > 100:
            errors.append(
                Error(
                    'Model names must be at most 100 characters (got %d).' % (
                        len(model._meta.model_name),
                    ),
                    obj=model,
                    id='contenttypes.E005',
                )
            )
    return errors

def _get_sitemap_full_url(sitemap_url, sitemap_uses_https=True):
    if not django_apps.is_installed('django.contrib.sites'):
        raise ImproperlyConfigured("ping_google requires django.contrib.sites, which isn't installed.")

    if sitemap_url is None:
        try:
            # First, try to get the "index" sitemap URL.
            sitemap_url = reverse('django.contrib.sitemaps.views.index')
        except NoReverseMatch:
            try:
                # Next, try for the "global" sitemap URL.
                sitemap_url = reverse('django.contrib.sitemaps.views.sitemap')
            except NoReverseMatch:
                pass

    if sitemap_url is None:
        raise SitemapNotFound("You didn't provide a sitemap_url, and the sitemap URL couldn't be auto-detected.")

    Site = django_apps.get_model('sites.Site')
    current_site = Site.objects.get_current()
    scheme = 'https' if sitemap_uses_https else 'http'
    return '%s://%s%s' % (scheme, current_site.domain, sitemap_url)

def handle(self, **options):
    locale = options['locale']
    exclude = options['exclude']
    ignore_patterns = set(options['ignore_patterns'])
    self.verbosity = options['verbosity']
    if options['fuzzy']:
        self.program_options = self.program_options + ['-f']

    if find_command(self.program) is None:
        raise CommandError("Can't find %s. Make sure you have GNU gettext "
                           "tools 0.15 or newer installed." % self.program)

    basedirs = [os.path.join('conf', 'locale'), 'locale']
    if os.environ.get('DJANGO_SETTINGS_MODULE'):
        from django.conf import settings
        basedirs.extend(settings.LOCALE_PATHS)

    # Walk entire tree, looking for locale directories
    for dirpath, dirnames, filenames in os.walk('.', topdown=True):
        for dirname in dirnames:
            if is_ignored_path(os.path.normpath(os.path.join(dirpath, dirname)), ignore_patterns):
                dirnames.remove(dirname)
            elif dirname == 'locale':
                basedirs.append(os.path.join(dirpath, dirname))

    # Gather existing directories.
    basedirs = set(map(os.path.abspath, filter(os.path.isdir, basedirs)))

    if not basedirs:
        raise CommandError("This script should be run from the Django Git "
                           "checkout or your project or app tree, or with "
                           "the settings module specified.")

    # Build locale list
    all_locales = []
    for basedir in basedirs:
        locale_dirs = filter(os.path.isdir, glob.glob('%s/*' % basedir))
        all_locales.extend(map(os.path.basename, locale_dirs))

    # Account for excluded locales
    locales = locale or all_locales
    locales = set(locales).difference(exclude)

    self.has_errors = False
    for basedir in basedirs:
        if locales:
            dirs = [os.path.join(basedir, locale, 'LC_MESSAGES') for locale in locales]
        else:
            dirs = [basedir]
        locations = []
        for ldir in dirs:
            for dirpath, dirnames, filenames in os.walk(ldir):
                locations.extend((dirpath, f) for f in filenames if f.endswith('.po'))
        if locations:
            self.compile_messages(locations)

    if self.has_errors:
        raise CommandError('compilemessages generated one or more errors.')

def create_table(self, database, tablename, dry_run):
    cache = BaseDatabaseCache(tablename, {})
    if not router.allow_migrate_model(database, cache.cache_model_class):
        return
    connection = connections[database]

    if tablename in connection.introspection.table_names():
        if self.verbosity > 0:
            self.stdout.write("Cache table '%s' already exists." % tablename)
        return

    fields = (
        # "key" is a reserved word in MySQL, so use "cache_key" instead.
        models.CharField(name='cache_key', max_length=255, unique=True, primary_key=True),
        models.TextField(name='value'),
        models.DateTimeField(name='expires', db_index=True),
    )
    table_output = []
    index_output = []
    qn = connection.ops.quote_name
    for f in fields:
        field_output = [
            qn(f.name),
            f.db_type(connection=connection),
            '%sNULL' % ('NOT ' if not f.null else ''),
        ]
        if f.primary_key:
            field_output.append("PRIMARY KEY")
        elif f.unique:
            field_output.append("UNIQUE")
        if f.db_index:
            unique = "UNIQUE " if f.unique else ""
            index_output.append(
                "CREATE %sINDEX %s ON %s (%s);" %
                (unique, qn('%s_%s' % (tablename, f.name)), qn(tablename), qn(f.name))
            )
        table_output.append(" ".join(field_output))
    full_statement = ["CREATE TABLE %s (" % qn(tablename)]
    for i, line in enumerate(table_output):
        full_statement.append('    %s%s' % (line, ',' if i < len(table_output) - 1 else ''))
    full_statement.append(');')

    full_statement = "\n".join(full_statement)

    if dry_run:
        self.stdout.write(full_statement)
        for statement in index_output:
            self.stdout.write(statement)
        return

    with transaction.atomic(using=database, savepoint=connection.features.can_rollback_ddl):
        with connection.cursor() as curs:
            try:
                curs.execute(full_statement)
            except DatabaseError as e:
                raise CommandError(
                    "Cache table '%s' could not be created.\nThe error was: %s." %
                    (tablename, e))
            for statement in index_output:
                curs.execute(statement)

    if self.verbosity > 1:
        self.stdout.write("Cache table '%s' created." % tablename)

def find_fixtures(self, fixture_label):
    """Find fixture files for a given label."""
    if fixture_label == READ_STDIN:
        return [(READ_STDIN, None, READ_STDIN)]

    fixture_name, ser_fmt, cmp_fmt = self.parse_name(fixture_label)
    databases = [self.using, None]
    cmp_fmts = list(self.compression_formats) if cmp_fmt is None else [cmp_fmt]
    ser_fmts = self.serialization_formats if ser_fmt is None else [ser_fmt]

    if self.verbosity >= 2:
        self.stdout.write("Loading '%s' fixtures..." % fixture_name)

    if os.path.isabs(fixture_name):
        fixture_dirs = [os.path.dirname(fixture_name)]
        fixture_name = os.path.basename(fixture_name)
    else:
        fixture_dirs = self.fixture_dirs
        if os.path.sep in os.path.normpath(fixture_name):
            fixture_dirs = [os.path.join(dir_, os.path.dirname(fixture_name))
                            for dir_ in fixture_dirs]
            fixture_name = os.path.basename(fixture_name)

    suffixes = (
        '.'.join(ext for ext in combo if ext)
        for combo in product(databases, ser_fmts, cmp_fmts)
    )
    targets = {'.'.join((fixture_name, suffix)) for suffix in suffixes}

    fixture_files = []
    for fixture_dir in fixture_dirs:
        if self.verbosity >= 2:
            self.stdout.write("Checking %s for fixtures..." % humanize(fixture_dir))
        fixture_files_in_dir = []
        path = os.path.join(fixture_dir, fixture_name)
        for candidate in glob.iglob(glob.escape(path) + '*'):
            if os.path.basename(candidate) in targets:
                # Save the fixture_dir and fixture_name for future error messages.
                fixture_files_in_dir.append((candidate, fixture_dir, fixture_name))

        if self.verbosity >= 2 and not fixture_files_in_dir:
            self.stdout.write("No fixture '%s' in %s." %
                              (fixture_name, humanize(fixture_dir)))

        # Check kept for backwards-compatibility; it isn't clear why
        # duplicates are only allowed in different directories.
        if len(fixture_files_in_dir) > 1:
            raise CommandError(
                "Multiple fixtures named '%s' in %s. Aborting." %
                (fixture_name, humanize(fixture_dir)))
        fixture_files.extend(fixture_files_in_dir)

    if not fixture_files:
        raise CommandError("No fixture named '%s' found." % fixture_name)

    return fixture_files

def show_plan(self, connection, app_names=None):
    """
    Show all known migrations (or only those of the specified app_names)
    in the order they will be applied.
    """
    # Load migrations from disk/DB
    loader = MigrationLoader(connection)
    graph = loader.graph
    if app_names:
        self._validate_app_names(loader, app_names)
        targets = [key for key in graph.leaf_nodes() if key[0] in app_names]
    else:
        targets = graph.leaf_nodes()
    plan = []
    seen = set()

    # Generate the plan
    for target in targets:
        for migration in graph.forwards_plan(target):
            if migration not in seen:
                node = graph.node_map[migration]
                plan.append(node)
                seen.add(migration)

    # Output
    def print_deps(node):
        out = []
        for parent in sorted(node.parents):
            out.append("%s.%s" % parent.key)
        if out:
            return " ... (%s)" % ", ".join(out)
        return ""

    for node in plan:
        deps = ""
        if self.verbosity >= 2:
            deps = print_deps(node)
        if node.key in loader.applied_migrations:
            self.stdout.write("[X]  %s.%s%s" % (node.key[0], node.key[1], deps))
        else:
            self.stdout.write("[ ]  %s.%s%s" % (node.key[0], node.key[1], deps))
    if not plan:
        self.stdout.write('(no migrations)', self.style.ERROR)

def window_frame_start(self, start):
    if isinstance(start, int):
        if start < 0:
            return '%d %s' % (abs(start), self.PRECEDING)
        elif start == 0:
            return self.CURRENT_ROW
    elif start is None:
        return self.UNBOUNDED_PRECEDING
    raise ValueError("start argument must be a negative integer, zero, or None, but got '%s'." % start)

def window_frame_end(self, end):
    if isinstance(end, int):
        if end == 0:
            return self.CURRENT_ROW
        elif end > 0:
            return '%d %s' % (end, self.FOLLOWING)
    elif end is None:
        return self.UNBOUNDED_FOLLOWING
    raise ValueError("end argument must be a positive integer, zero, or None, but got '%s'." % end)

def _sqlite_date_trunc(lookup_type, dt, tzname, conn_tzname):
    dt = _sqlite_datetime_parse(dt, tzname, conn_tzname)
    if dt is None:
        return None
    if lookup_type == 'year':
        return "%i-01-01" % dt.year
    elif lookup_type == 'quarter':
        month_in_quarter = dt.month - (dt.month - 1) % 3
        return '%i-%02i-01' % (dt.year, month_in_quarter)
    elif lookup_type == 'month':
        return "%i-%02i-01" % (dt.year, dt.month)
    elif lookup_type == 'week':
        dt = dt - datetime.timedelta(days=dt.weekday())
        return "%i-%02i-%02i" % (dt.year, dt.month, dt.day)
    elif lookup_type == 'day':
        return "%i-%02i-%02i" % (dt.year, dt.month, dt.day)

def _sqlite_time_trunc(lookup_type, dt, tzname, conn_tzname):
    if dt is None:
        return None
    dt_parsed = _sqlite_datetime_parse(dt, tzname, conn_tzname)
    if dt_parsed is None:
        try:
            dt = backend_utils.typecast_time(dt)
        except (ValueError, TypeError):
            return None
    else:
        dt = dt_parsed
    if lookup_type == 'hour':
        return "%02i:00:00" % dt.hour
    elif lookup_type == 'minute':
        return "%02i:%02i:00" % (dt.hour, dt.minute)
    elif lookup_type == 'second':
        return "%02i:%02i:%02i" % (dt.hour, dt.minute, dt.second)

def _sqlite_datetime_trunc(lookup_type, dt, tzname, conn_tzname):
    dt = _sqlite_datetime_parse(dt, tzname, conn_tzname)
    if dt is None:
        return None
    if lookup_type == 'year':
        return "%i-01-01 00:00:00" % dt.year
    elif lookup_type == 'quarter':
        month_in_quarter = dt.month - (dt.month - 1) % 3
        return '%i-%02i-01 00:00:00' % (dt.year, month_in_quarter)
    elif lookup_type == 'month':
        return "%i-%02i-01 00:00:00" % (dt.year, dt.month)
    elif lookup_type == 'week':
        dt = dt - datetime.timedelta(days=dt.weekday())
        return "%i-%02i-%02i 00:00:00" % (dt.year, dt.month, dt.day)
    elif lookup_type == 'day':
        return "%i-%02i-%02i 00:00:00" % (dt.year, dt.month, dt.day)
    elif lookup_type == 'hour':
        return "%i-%02i-%02i %02i:00:00" % (dt.year, dt.month, dt.day, dt.hour)
    elif lookup_type == 'minute':
        return "%i-%02i-%02i %02i:%02i:00" % (dt.year, dt.month, dt.day, dt.hour, dt.minute)
    elif lookup_type == 'second':
        return "%i-%02i-%02i %02i:%02i:%02i" % (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)

def generate_renamed_models(self):
    """
    Find any renamed models, generate the operations for them, and remove
    the old entry from the model lists. Must be run before other
    model-level generation.
    """
    self.renamed_models = {}
    self.renamed_models_rel = {}
    added_models = self.new_model_keys - self.old_model_keys
    for app_label, model_name in sorted(added_models):
        model_state = self.to_state.models[app_label, model_name]
        model_fields_def = self.only_relation_agnostic_fields(model_state.fields)

        removed_models = self.old_model_keys - self.new_model_keys
        for rem_app_label, rem_model_name in removed_models:
            if rem_app_label == app_label:
                rem_model_state = self.from_state.models[rem_app_label, rem_model_name]
                rem_model_fields_def = self.only_relation_agnostic_fields(rem_model_state.fields)
                if model_fields_def == rem_model_fields_def:
                    if self.questioner.ask_rename_model(rem_model_state, model_state):
                        model_opts = self.new_apps.get_model(app_label, model_name)._meta
                        dependencies = []
                        for field in model_opts.get_fields():
                            if field.is_relation:
                                dependencies.extend(self._get_dependencies_for_foreign_key(field))
                        self.add_operation(
                            app_label,
                            operations.RenameModel(
                                old_name=rem_model_state.name,
                                new_name=model_state.name,
                            ),
                            dependencies=dependencies,
                        )
                        self.renamed_models[app_label, model_name] = rem_model_name
                        renamed_models_rel_key = '%s.%s' % (
                            rem_model_state.app_label,
                            rem_model_state.name_lower,
                        )
                        self.renamed_models_rel[renamed_models_rel_key] = '%s.%s' % (
                            model_state.app_label,
                            model_state.name_lower,
                        )
                        self.old_model_keys.remove((rem_app_label, rem_model_name))
                        self.old_model_keys.add((app_label, model_name))
                        break

def check_consistent_history(self, connection):
    """
    Raise InconsistentMigrationHistory if any applied migrations have
    unapplied dependencies.
    """
    recorder = MigrationRecorder(connection)
    applied = recorder.applied_migrations()
    for migration in applied:
        # If the migration is unknown, skip it.
        if migration not in self.graph.nodes:
            continue
        for parent in self.graph.node_map[migration].parents:
            if parent not in applied:
                # Skip unapplied squashed migrations that have all of their
                # `replaces` applied.
                if parent in self.replacements:
                    if all(m in applied for m in self.replacements[parent].replaces):
                        continue
                raise InconsistentMigrationHistory(
                    "Migration {}.{} is applied before its dependency "
                    "{}.{} on database '{}'.".format(
                        migration[0], migration[1], parent[0], parent[1],
                        connection.alias,
                    )
                )

def _check_model(cls):
    errors = []
    if cls._meta.proxy:
        if cls._meta.local_fields or cls._meta.local_many_to_many:
            errors.append(
                checks.Error(
                    "Proxy model '%s' contains model fields." % cls.__name__,
                    id='models.E017',
                )
            )
    return errors

def _check_property_name_related_field_accessor_clashes(cls):
    errors = []
    property_names = cls._meta._property_names
    related_field_accessors = (
        f.get_attname() for f in cls._meta._get_fields(reverse=False)
        if f.is_relation and f.related_model is not None
    )
    for accessor in related_field_accessors:
        if accessor in property_names:
            errors.append(
                checks.Error(
                    "The property '%s' clashes with a related field "
                    "accessor." % accessor,
                    obj=cls,
                    id='models.E025',
                )
            )
    return errors

def _check_choices(self):
    if not self.choices:
        return []

    if not is_iterable(self.choices) or isinstance(self.choices, str):
        return [
            checks.Error(
                "'choices' must be an iterable (e.g., a list or tuple).",
                obj=self,
                id='fields.E004',
            )
        ]

    choice_max_length = 0
    # Expect [group_name, [value, display]]
    for choices_group in self.choices:
        try:
            group_name, group_choices = choices_group
        except (TypeError, ValueError):
            # Containing non-pairs
            break
        try:
            if not all(
                self._choices_is_value(value) and self._choices_is_value(human_name)
                for value, human_name in group_choices
            ):
                break
            if self.max_length is not None and group_choices:
                choice_max_length = max([
                    choice_max_length,
                    *(len(value) for value, _ in group_choices if isinstance(value, str)),
                ])
        except (TypeError, ValueError):
            # No groups, choices in the form [value, display]
            value, human_name = group_name, group_choices
            if not self._choices_is_value(value) or not self._choices_is_value(human_name):
                break
            if self.max_length is not None and isinstance(value, str):
                choice_max_length = max(choice_max_length, len(value))

        # Special case: choices=['ab']
        if isinstance(choices_group, str):
            break
    else:
        if self.max_length is not None and choice_max_length > self.max_length:
            return [
                checks.Error(
                    "'max_length' is too small to fit the longest value "
                    "in 'choices' (%d characters)." % choice_max_length,
                    obj=self,
                    id='fields.E009',
                ),
            ]
        return []

    return [
        checks.Error(
            "'choices' must be an iterable containing "
            "(actual value, human readable name) tuples.",
            obj=self,
            id='fields.E005',
        )
    ]

def _check_unique_target(self):
    rel_is_string = isinstance(self.remote_field.model, str)
    if rel_is_string or not self.requires_unique_target:
        return []

    try:
        self.foreign_related_fields
    except exceptions.FieldDoesNotExist:
        return []

    if not self.foreign_related_fields:
        return []

    unique_foreign_fields = {
        frozenset([f.name])
        for f in self.remote_field.model._meta.get_fields()
        if getattr(f, 'unique', False)
    }
    unique_foreign_fields.update({
        frozenset(ut)
        for ut in self.remote_field.model._meta.unique_together
    })
    unique_foreign_fields.update({
        frozenset(uc.fields)
        for uc in self.remote_field.model._meta.total_unique_constraints
    })
    foreign_fields = {f.name for f in self.foreign_related_fields}
    has_unique_constraint = any(u <= foreign_fields for u in unique_foreign_fields)

    if not has_unique_constraint and len(self.foreign_related_fields) > 1:
        field_combination = ', '.join(
            "'%s'" % rel_field.name for rel_field in self.foreign_related_fields
        )
        model_name = self.remote_field.model.__name__
        return [
            checks.Error(
                "No subset of the fields %s on model '%s' is unique."
                % (field_combination, model_name),
                hint=(
                    'Mark a single field as unique=True or add a set of '
                    'fields to a unique constraint (via unique_together '
                    'or a UniqueConstraint (without condition) in the '
                    'model Meta.constraints).'
                ),
                obj=self,
                id='fields.E310',
            )
        ]
    elif not has_unique_constraint:
        field_name = self.foreign_related_fields[0].name
        model_name = self.remote_field.model.__name__
        return [
            checks.Error(
                "'%s.%s' must be unique because it is referenced by "
                "a foreign key." % (model_name, field_name),
                hint=(
                    'Add unique=True to this field or add a '
                    'UniqueConstraint (without condition) in the model '
                    'Meta.constraints.'
                ),
                obj=self,
                id='fields.E311',
            )
        ]
    else:
        return []

def deconstruct(self):
    name, path, args, kwargs = super().deconstruct()
    kwargs['on_delete'] = self.remote_field.on_delete
    kwargs['from_fields'] = self.from_fields
    kwargs['to_fields'] = self.to_fields

    if self.remote_field.parent_link:
        kwargs['parent_link'] = self.remote_field.parent_link
    if isinstance(self.remote_field.model, str):
        if '.' in self.remote_field.model:
            app_label, model_name = self.remote_field.model.split('.')
            kwargs['to'] = '%s.%s' % (app_label, model_name.lower())
        else:
            kwargs['to'] = self.remote_field.model.lower()
    else:
        kwargs['to'] = self.remote_field.model._meta.label_lower
    # If swappable is True, then see if we're actually pointing to the target
    # of a swap.
    swappable_setting = self.swappable_setting
    if swappable_setting is not None:
        # If it's already a settings reference, error
        if hasattr(kwargs['to'], "setting_name"):
            if kwargs['to'].setting_name != swappable_setting:
                raise ValueError(
                    "Cannot deconstruct a ForeignKey pointing to a model "
                    "that is swapped in place of more than one model (%s and %s)"
                    % (kwargs['to'].setting_name, swappable_setting)
                )
        # Set it
        kwargs['to'] = SettingsReference(
            kwargs['to'],
            swappable_setting,
        )
    return name, path, args, kwargs

def deconstruct(self):
    name, path, args, kwargs = super().deconstruct()
    # Handle the simpler arguments.
    if self.db_table is not None:
        kwargs['db_table'] = self.db_table
    if self.remote_field.db_constraint is not True:
        kwargs['db_constraint'] = self.remote_field.db_constraint
    # Rel needs more work.
    if isinstance(self.remote_field.model, str):
        kwargs['to'] = self.remote_field.model
    else:
        kwargs['to'] = "%s.%s" % (
            self.remote_field.model._meta.app_label,
            self.remote_field.model._meta.object_name,
        )
    if getattr(self.remote_field, 'through', None) is not None:
        if isinstance(self.remote_field.through, str):
            kwargs['through'] = self.remote_field.through
        elif not self.remote_field.through._meta.auto_created:
            kwargs['through'] = "%s.%s" % (
                self.remote_field.through._meta.app_label,
                self.remote_field.through._meta.object_name,
            )
    # If swappable is True, then see if we're actually pointing to the target
    # of a swap.
    swappable_setting = self.swappable_setting
    if swappable_setting is not None:
        # If it's already a settings reference, error.
        if hasattr(kwargs['to'], "setting_name"):
            if kwargs['to'].setting_name != swappable_setting:
                raise ValueError(
                    "Cannot deconstruct a ManyToManyField pointing to a "
                    "model that is swapped in place of more than one model "
                    "(%s and %s)" % (kwargs['to'].setting_name, swappable_setting)
                )

        kwargs['to'] = SettingsReference(
            kwargs['to'],
            swappable_setting,
        )
    return name, path, args, kwargs

def aggregate(self, *args, **kwargs):
    """
    Return a dictionary containing the calculations (aggregation)
    over the current queryset.

    If args is present the expression is passed as a kwarg using
    the Aggregate object's default alias.
    """
    if self.query.distinct_fields:
        raise NotImplementedError("aggregate() + distinct(fields) not implemented.")
    self._validate_values_are_expressions((*args, *kwargs.values()), method_name='aggregate')
    for arg in args:
        # The default_alias property raises TypeError if default_alias
        # can't be set automatically or AttributeError if it isn't an
        # attribute.
        try:
            arg.default_alias
        except (AttributeError, TypeError):
            raise TypeError("Complex aggregates require an alias")
        kwargs[arg.default_alias] = arg

    query = self.query.chain()
    for (alias, aggregate_expr) in kwargs.items():
        query.add_annotation(aggregate_expr, alias, is_summary=True)
        annotation = query.annotations[alias]
        if not annotation.contains_aggregate:
            raise TypeError("%s is not an aggregate expression" % alias)
        for expr in annotation.get_source_expressions():
            if expr.contains_aggregate and isinstance(expr, Ref) and expr.refs in kwargs:
                name = expr.refs
                raise exceptions.FieldError(
                    "Cannot compute %s('%s'): '%s' is an aggregate"
                    % (annotation.name, name, name)
                )
    return query.get_aggregation(self.db, kwargs)

def ordered(self):
    """
    Return True if the QuerySet is ordered -- i.e. has an order_by()
    clause or a default ordering on the model (or is empty).
    """
    if isinstance(self, EmptyQuerySet):
        return True
    if self.query.extra_order_by or self.query.order_by:
        return True
    elif (
        self.query.default_ordering and
        self.query.get_meta().ordering and
        # A default ordering doesn't affect GROUP BY queries.
        not self.query.group_by
    ):
        return True
    else:
        return False

def select_related_descend(field, restricted, requested, load_fields, reverse=False):
    """
    Return True if this field should be used to descend deeper for
    select_related() purposes. Used by both the query construction code
    (sql.query.fill_related_selections()) and the model instance creation code
    (query.get_klass_info()).

    Arguments:
     * field - the field to be checked
     * restricted - a boolean field, indicating if the field list has been
       manually restricted using a requested clause)
     * requested - The select_related() dictionary.
     * load_fields - the set of fields to be loaded on this model
     * reverse - boolean, True if we are checking a reverse select related
    """
    if not field.remote_field:
        return False
    if field.remote_field.parent_link and not reverse:
        return False
    if restricted:
        if reverse and field.related_query_name() not in requested:
            return False
        if not reverse and field.name not in requested:
            return False
    if not restricted and field.null:
        return False
    if load_fields:
        if field.attname not in load_fields:
            if restricted and field.name in requested:
                msg = (
                    'Field %s.%s cannot be both deferred and traversed using '
                    'select_related at the same time.'
                ) % (field.model._meta.object_name, field.name)
                raise FieldError(msg)
    return True

def check_query_object_type(self, value, opts, field):
    """
    Check whether the object passed while querying is of the correct type.
    If not, raise a ValueError specifying the wrong object.
    """
    if hasattr(value, '_meta'):
        if not check_rel_lookup_compatibility(value._meta.model, opts, field):
            raise ValueError(
                'Cannot query "%s": Must be "%s" instance.' %
                (value, opts.object_name))

def add_fields(self, field_names, allow_m2m=True):
    """
    Add the given (model) fields to the select set. Add the field names in
    the order specified.
    """
    alias = self.get_initial_alias()
    opts = self.get_meta()

    try:
        cols = []
        for name in field_names:
            # Join promotion note - we must not remove any rows here, so
            # if there is no existing joins, use outer join.
            join_info = self.setup_joins(name.split(LOOKUP_SEP), opts, alias, allow_many=allow_m2m)
            targets, final_alias, joins = self.trim_joins(
                join_info.targets,
                join_info.joins,
                join_info.path,
            )
            for target in targets:
                cols.append(join_info.transform_function(target, final_alias))
        if cols:
            self.set_select(cols)
    except MultiJoin:
        raise FieldError("Invalid field name: '%s'" % name)
    except FieldError:
        if LOOKUP_SEP in name:
            # For lookups spanning over relationships, show the error
            # from the model on which the lookup failed.
            raise
        elif name in self.annotations:
            raise FieldError(
                "Cannot select the '%s' alias. Use annotate() to promote "
                "it." % name
            )
        else:
            names = sorted([
                *get_field_names_from_opts(opts), *self.extra,
                *self.annotation_select, *self._filtered_relations
            ])
            raise FieldError("Cannot resolve keyword %r into field. "
                             "Choices are: %s" % (name, ", ".join(names)))

def is_valid(self):
    """Return True if every form in self.forms is valid."""
    if not self.is_bound:
        return False
    # Accessing errors triggers a full clean the first time only.
    self.errors
    # List comprehension ensures is_valid() is called for all forms.
    # Forms due to be deleted shouldn't cause the formset to be invalid.
    forms_valid = all([
        form.is_valid() for form in self.forms
        if not (self.can_delete and self._should_delete_form(form))
    ])
    return forms_valid and not self.non_form_errors()

def render(self, context):
    if 'forloop' in context:
        parentloop = context['forloop']
    else:
        parentloop = {}
    with context.push():
        values = self.sequence.resolve(context, ignore_failures=True)
        if values is None:
            values = []
        if not hasattr(values, '__len__'):
            values = list(values)
        len_values = len(values)
        if len_values < 1:
            return self.nodelist_empty.render(context)
        nodelist = []
        if self.is_reversed:
            values = reversed(values)
        num_loopvars = len(self.loopvars)
        unpack = num_loopvars > 1
        # Create a forloop value in the context.  We'll update counters on each
        # iteration just below.
        loop_dict = context['forloop'] = {'parentloop': parentloop}
        for i, item in enumerate(values):
            # Shortcuts for current loop iteration number.
            loop_dict['counter0'] = i
            loop_dict['counter'] = i + 1
            # Reverse counter iteration numbers.
            loop_dict['revcounter'] = len_values - i
            loop_dict['revcounter0'] = len_values - i - 1
            # Boolean values designating first and last times through loop.
            loop_dict['first'] = (i == 0)
            loop_dict['last'] = (i == len_values - 1)

            pop_context = False
            if unpack:
                # If there are multiple loop variables, unpack the item into
                # them.
                try:
                    len_item = len(item)
                except TypeError:  # not an iterable
                    len_item = 1
                # Check loop variable count before unpacking
                if num_loopvars != len_item:
                    raise ValueError(
                        "Need {} values to unpack in for loop; got {}. "
                        .format(num_loopvars, len_item),
                    )
                unpacked_vars = dict(zip(self.loopvars, item))
                pop_context = True
                context.update(unpacked_vars)
            else:
                context[self.loopvars[0]] = item

            for node in self.nodelist_loop:
                nodelist.append(node.render_annotated(context))

            if pop_context:
                # Pop the loop variables pushed on to the context to avoid
                # the context ending up in an inconsistent state when other
                # tags (e.g., include and with) push data to context.
                context.pop()
    return mark_safe(''.join(nodelist))

def iter_format_modules(lang, format_module_path=None):
    """Find format modules."""
    if not check_for_language(lang):
        return

    if format_module_path is None:
        format_module_path = settings.FORMAT_MODULE_PATH

    format_locations = []
    if format_module_path:
        if isinstance(format_module_path, str):
            format_module_path = [format_module_path]
        for path in format_module_path:
            format_locations.append(path + '.%s')
    format_locations.append('django.conf.locale.%s')
    locale = to_locale(lang)
    locales = [locale]
    if '_' in locale:
        locales.append(locale.split('_')[0])
    for location in format_locations:
        for loc in locales:
            try:
                yield import_module('%s.formats' % (location % loc))
            except ImportError:
                pass

def clean_ipv6_address(ip_str, unpack_ipv4=False,
                       error_message=_("This is not a valid IPv6 address.")):
    """
    Clean an IPv6 address string.

    Raise ValidationError if the address is invalid.

    Replace the longest continuous zero-sequence with "::", remove leading
    zeroes, and make sure all hextets are lowercase.

    Args:
        ip_str: A valid IPv6 address.
        unpack_ipv4: if an IPv4-mapped address is found,
        return the plain IPv4 address (default=False).
        error_message: An error message used in the ValidationError.

    Return a compressed IPv6 address or the same value.
    """
    try:
        addr = ipaddress.IPv6Address(int(ipaddress.IPv6Address(ip_str)))
    except ValueError:
        raise ValidationError(error_message, code='invalid')

    if unpack_ipv4 and addr.ipv4_mapped:
        return str(addr.ipv4_mapped)
    elif addr.ipv4_mapped:
        return '::ffff:%s' % str(addr.ipv4_mapped)

    return str(addr)

def lazy_number(func, resultclass, number=None, **kwargs):
    if isinstance(number, int):
        kwargs['number'] = number
        proxy = lazy(func, resultclass)(**kwargs)
    else:
        original_kwargs = kwargs.copy()

        class NumberAwareString(resultclass):
            def __bool__(self):
                return bool(kwargs['singular'])

            def _get_number_value(self, values):
                try:
                    return values[number]
                except KeyError:
                    raise KeyError(
                        "Your dictionary lacks key '%s\'. Please provide "
                        "it, because it is required to determine whether "
                        "string is singular or plural." % number
                    )

            def _translate(self, number_value):
                kwargs['number'] = number_value
                return func(**kwargs)

            def format(self, *args, **kwargs):
                number_value = self._get_number_value(kwargs) if kwargs and number else args[0]
                return self._translate(number_value).format(*args, **kwargs)

            def __mod__(self, rhs):
                if isinstance(rhs, dict) and number:
                    number_value = self._get_number_value(rhs)
                else:
                    number_value = rhs
                translated = self._translate(number_value)
                try:
                    translated = translated % rhs
                except TypeError:
                    # String doesn't contain a placeholder for the number.
                    pass
                return translated

        proxy = lazy(lambda **kwargs: NumberAwareString(), NumberAwareString)(**kwargs)
        proxy.__reduce__ = lambda: (_lazy_number_unpickle, (func, resultclass, number, original_kwargs))
    return proxy

def get_docs_version(version=None):
    version = get_complete_version(version)
    if version[3] != 'final':
        return 'dev'
    else:
        return '%d.%d' % version[:2]

def _plot_layer(self, p: Plot, layer: Layer) -> None:

    data = layer["data"]
    mark = layer["mark"]
    move = layer["move"]

    default_grouping_vars = ["col", "row", "group"]  # TODO where best to define?
    grouping_properties = [v for v in PROPERTIES if v[0] not in "xy"]

    pair_variables = p._pair_spec.get("structure", {})

    for subplots, df, scales in self._generate_pairings(data, pair_variables):

        orient = layer["orient"] or mark._infer_orient(scales)

        def get_order(var):
            # Ignore order for x/y: they have been scaled to numeric indices,
            # so any original order is no longer valid. Default ordering rules
            # sorted unique numbers will correctly reconstruct intended order
            # TODO This is tricky, make sure we add some tests for this
            if var not in "xy" and var in scales:
                return getattr(scales[var], "order", None)

        if orient in df:
            width = pd.Series(index=df.index, dtype=float)
            for view in subplots:
                view_idx = self._get_subplot_data(
                    df, orient, view, p._shares.get(orient)
                ).index
                view_df = df.loc[view_idx]
                if "width" in mark._mappable_props:
                    view_width = mark._resolve(view_df, "width", None)
                elif "width" in df:
                    view_width = view_df["width"]
                else:
                    view_width = 0.8  # TODO what default?
                spacing = scales[orient]._spacing(view_df.loc[view_idx, orient])
                width.loc[view_idx] = view_width * spacing
            df["width"] = width

        if "baseline" in mark._mappable_props:
            # TODO what marks should have this?
            # If we can set baseline with, e.g., Bar(), then the
            # "other" (e.g. y for x oriented bars) parameterization
            # is somewhat ambiguous.
            baseline = mark._resolve(df, "baseline", None)
        else:
            # TODO unlike width, we might not want to add baseline to data
            # if the mark doesn't use it. Practically, there is a concern about
            # Mark abstraction like Area / Ribbon
            baseline = 0 if "baseline" not in df else df["baseline"]
        df["baseline"] = baseline

        if move is not None:
            moves = move if isinstance(move, list) else [move]
            for move_step in moves:
                move_by = getattr(move_step, "by", None)
                if move_by is None:
                    move_by = grouping_properties
                move_groupers = [*move_by, *default_grouping_vars]
                if move_step.group_by_orient:
                    move_groupers.insert(0, orient)
                order = {var: get_order(var) for var in move_groupers}
                groupby = GroupBy(order)
                df = move_step(df, groupby, orient, scales)

        df = self._unscale_coords(subplots, df, orient)

        grouping_vars = mark._grouping_props + default_grouping_vars
        split_generator = self._setup_split_generator(grouping_vars, df, subplots)

        mark._plot(split_generator, scales, orient)

    # TODO is this the right place for this?
    for view in self._subplots:
        view["ax"].autoscale_view()

    if layer["legend"]:
        self._update_legend_contents(p, mark, data, scales)

def default_scale(self, data: Series) -> ScaleSpec:
    """Given data, initialize appropriate scale class."""
    # TODO allow variable_type to be "boolean" if that's a scale?
    # TODO how will this handle data with units that can be treated as numeric
    # if passed through a registered matplotlib converter?
    var_type = variable_type(data, boolean_type="numeric")
    if var_type == "numeric":
        return Continuous()
    elif var_type == "datetime":
        return Temporal()
    # TODO others
    # time-based (TimeStamp, TimeDelta, Period)
    # boolean scale?
    else:
        return Nominal()

def __call__(self, data: Series) -> ArrayLike:

    trans_data: Series | NDArray | list

    # TODO sometimes we need to handle scalars (e.g. for Line)
    # but what is the best way to do that?
    scalar_data = np.isscalar(data)
    if scalar_data:
        trans_data = np.array([data])
    else:
        trans_data = data

    for func in self._pipeline:
        if func is not None:
            trans_data = func(trans_data)

    if scalar_data:
        return trans_data[0]
    else:
        return trans_data

def _setup(
    self, data: Series, prop: Property, axis: Axis | None = None,
) -> Scale:

    new = copy(self)
    if new._tick_params is None:
        new = new.tick()
    if new._label_params is None:
        new = new.label()

    def na_safe_cast(x):
        # TODO this doesn't actually need to be a closure
        if np.isscalar(x):
            return float(bool(x))
        else:
            if hasattr(x, "notna"):
                # Handle pd.NA; np<>pd interop with NA is tricky
                use = x.notna().to_numpy()
            else:
                use = np.isfinite(x)
            out = np.full(len(x), np.nan, dtype=float)
            out[use] = x[use].astype(bool).astype(float)
            return out

    new._pipeline = [na_safe_cast, prop.get_mapping(new, data)]
    new._spacer = _default_spacer
    if prop.legend:
        new._legend = [True, False], ["True", "False"]

    forward, inverse = _make_identity_transforms()
    mpl_scale = new._get_scale(str(data.name), forward, inverse)

    axis = PseudoAxis(mpl_scale) if axis is None else axis
    mpl_scale.set_default_locators_and_formatters(axis)
    new._matplotlib_scale = mpl_scale

    return new

def add_legend_data(self, ax, func=None, common_kws=None, semantic_kws=None):
    """Add labeled artists to represent the different plot semantics."""
    verbosity = self.legend
    if isinstance(verbosity, str) and verbosity not in ["auto", "brief", "full"]:
        err = "`legend` must be 'auto', 'brief', 'full', or a boolean."
        raise ValueError(err)
    elif verbosity is True:
        verbosity = "auto"

    keys = []
    legend_kws = {}
    common_kws = {} if common_kws is None else common_kws
    semantic_kws = {} if semantic_kws is None else semantic_kws

    # Assign a legend title if there is only going to be one sub-legend,
    # otherwise, subtitles will be inserted into the texts list with an
    # invisible handle (which is a hack)
    titles = {
        title for title in
        (self.variables.get(v, None) for v in ["hue", "size", "style"])
        if title is not None
    }
    title = "" if len(titles) != 1 else titles.pop()
    title_kws = dict(
        visible=False, color="w", s=0, linewidth=0, marker="", dashes=""
    )

    def update(var_name, val_name, **kws):

        key = var_name, val_name
        if key in legend_kws:
            legend_kws[key].update(**kws)
        else:
            keys.append(key)
            legend_kws[key] = dict(**kws)

    legend_attrs = {"hue": "color", "size": ["linewidth", "s"], "style": None}
    for var, names in legend_attrs.items():
        self._update_legend_data(
            update, var, verbosity, title, title_kws, names, semantic_kws.get(var),
        )

    if func is None:
        func = getattr(ax, self._legend_func)

    legend_data = {}
    legend_order = []

    for key in keys:

        _, label = key
        kws = legend_kws[key]
        kws.setdefault("color", ".2")
        level_kws = {}
        use_attrs = [
            *self._legend_attributes,
            *common_kws,
            *[attr for var_attrs in semantic_kws.values() for attr in var_attrs],
        ]
        for attr in use_attrs:
            if attr in kws:
                level_kws[attr] = kws[attr]
        artist = func([], [], label=label, **{**common_kws, **level_kws})
        if func.__name__ == "plot":
            artist = artist[0]
        legend_data[key] = artist
        legend_order.append(key)

    self.legend_title = title
    self.legend_data = legend_data
    self.legend_order = legend_order

def dispatch_hook(key, hooks, hook_data, **kwargs):
    """Dispatches a hook dictionary on a given piece of data."""
    hooks = hooks or dict()
    hooks = hooks.get(key)
    if hooks:
        if hasattr(hooks, '__call__'):
            hooks = [hooks]
        for hook in hooks:
            _hook_data = hook(hook_data, **kwargs)
            if _hook_data is not None:
                hook_data = _hook_data
    return hook_data

def _check_consider_using_min_max_builtin(self, node: nodes.If):
    """Check if the given if node can be refactored as a min/max python builtin."""
    if self._is_actual_elif(node) or node.orelse:
        # Not interested in if statements with multiple branches.
        return

    if len(node.body) != 1:
        return

    body = node.body[0]
    # Check if condition can be reduced.
    if not hasattr(body, "targets") or len(body.targets) != 1:
        return

    target = body.targets[0]
    if not (
        isinstance(node.test, nodes.Compare)
        and not isinstance(target, nodes.Subscript)
        and not isinstance(node.test.left, nodes.Subscript)
        and isinstance(body, nodes.Assign)
    ):
        return

    # Check that the assignation is on the same variable.
    if hasattr(node.test.left, "name"):
        left_operand = node.test.left.name
    elif hasattr(node.test.left, "attrname"):
        left_operand = node.test.left.attrname
    else:
        return

    if hasattr(target, "name"):
        target_assignation = target.name
    elif hasattr(target, "attrname"):
        target_assignation = target.attrname
    else:
        return

    if not (left_operand == target_assignation):
        return

    if len(node.test.ops) > 1:
        return

    if not isinstance(body.value, (nodes.Name, nodes.Const)):
        return

    operator, right_statement = node.test.ops[0]
    if isinstance(body.value, nodes.Name):
        body_value = body.value.name
    else:
        body_value = body.value.value

    if isinstance(right_statement, nodes.Name):
        right_statement_value = right_statement.name
    elif isinstance(right_statement, nodes.Const):
        right_statement_value = right_statement.value
    else:
        return

    # Verify the right part of the statement is the same.
    if right_statement_value != body_value:
        return

    if operator in {"<", "<="}:
        reduced_to = "{target} = max({target}, {item})".format(
            target=target_assignation, item=body_value
        )
        self.add_message(
            "consider-using-max-builtin", node=node, args=(reduced_to,)
        )
    elif operator in {">", ">="}:
        reduced_to = "{target} = min({target}, {item})".format(
            target=target_assignation, item=body_value
        )
        self.add_message(
            "consider-using-min-builtin", node=node, args=(reduced_to,)
        )

def repr_locals(self, locals):
    if self.showlocals:
        lines = []
        keys = [loc for loc in locals if loc[0] != "@"]
        keys.sort()
        for name in keys:
            value = locals[name]
            if name == "__builtins__":
                lines.append("__builtins__ = <builtins>")
            else:
                # This formatting could all be handled by the
                # _repr() function, which is only reprlib.Repr in
                # disguise, so is very configurable.
                if self.truncate_locals:
                    str_repr = saferepr(value)
                else:
                    str_repr = safeformat(value)
                # if len(str_repr) < 70 or not isinstance(value,
                #                            (list, tuple, dict)):
                lines.append("%-10s = %s" % (name, str_repr))
                # else:
                #    self._line("%-10s =\\" % (name,))
                #    # XXX
                #    pprint.pprint(value, stream=self.excinfowriter)
        return ReprLocals(lines)

def repr_traceback_entry(
    self,
    entry: Optional[TracebackEntry],
    excinfo: Optional[ExceptionInfo[BaseException]] = None,
) -> "ReprEntry":
    lines: List[str] = []
    style = (
        entry._repr_style
        if entry is not None and entry._repr_style is not None
        else self.style
    )
    if style in ("short", "long") and entry is not None:
        source = self._getentrysource(entry)
        if source is None:
            source = Source("???")
            line_index = 0
        else:
            line_index = entry.lineno - entry.getfirstlinesource()
        short = style == "short"
        reprargs = self.repr_args(entry) if not short else None
        s = self.get_source(source, line_index, excinfo, short=short)
        lines.extend(s)
        if short:
            message = "in %s" % (entry.name)
        else:
            message = excinfo and excinfo.typename or ""
        entry_path = entry.path
        path = self._makepath(entry_path)
        reprfileloc = ReprFileLocation(path, entry.lineno + 1, message)
        localsrepr = self.repr_locals(entry.locals)
        return ReprEntry(lines, reprargs, localsrepr, reprfileloc, style)
    elif style == "value":
        if excinfo:
            lines.extend(str(excinfo.value).split("\n"))
        return ReprEntry(lines, None, None, None, style)
    else:
        if excinfo:
            lines.extend(self.get_exconly(excinfo, indent=4))
        return ReprEntry(lines, None, None, None, style)

def repr_unicode(self, x, level):
    # Strictly speaking wrong on narrow builds
    def repr(u):
        if "'" not in u:
            return u"'%s'" % u
        elif '"' not in u:
            return u'"%s"' % u
        else:
            return u"'%s'" % u.replace("'", r"\'")

    s = repr(x[: self.maxstring])
    if len(s) > self.maxstring:
        i = max(0, (self.maxstring - 3) // 2)
        j = max(0, self.maxstring - 3 - i)
        s = repr(x[:i] + x[len(x) - j :])
        s = s[:i] + "..." + s[len(s) - j :]
    return s

def _getcapture(self, method):
    if method == "fd":
        return MultiCapture(out=True, err=True, Capture=FDCapture)
    elif method == "sys":
        return MultiCapture(out=True, err=True, Capture=SysCapture)
    elif method == "no":
        return MultiCapture(out=False, err=False, in_=False)
    raise ValueError("unknown capturing method: %r" % method)  # pragma: no cover

def __init__(self, targetfd, tmpfile=None):
    self.targetfd = targetfd
    try:
        self.targetfd_save = os.dup(self.targetfd)
    except OSError:
        self.start = lambda: None
        self.done = lambda: None
    else:
        if targetfd == 0:
            assert not tmpfile, "cannot set tmpfile with stdin"
            tmpfile = open(os.devnull, "r")
            self.syscapture = SysCapture(targetfd)
        else:
            if tmpfile is None:
                f = TemporaryFile()
                with f:
                    tmpfile = safe_text_dupfile(f, mode="wb+")
            if targetfd in patchsysdict:
                self.syscapture = SysCapture(targetfd, tmpfile)
            else:
                self.syscapture = NoCapture()
        self.tmpfile = tmpfile
        self.tmpfile_fd = tmpfile.fileno()

def _attempt_to_close_capture_file(f):
    """Suppress IOError when closing the temporary file used for capturing streams in py27 (#2370)"""
    if six.PY2:
        try:
            f.close()
        except IOError:
            pass
    else:
        f.close()

def get_real_func(obj):
    """ gets the real function object of the (possibly) wrapped object by
    functools.wraps or functools.partial.
    """
    start_obj = obj
    for i in range(100):
        # __pytest_wrapped__ is set by @pytest.fixture when wrapping the fixture function
        # to trigger a warning if it gets called directly instead of by pytest: we don't
        # want to unwrap further than this otherwise we lose useful wrappings like @mock.patch (#3774)
        new_obj = getattr(obj, "__pytest_wrapped__", None)
        if isinstance(new_obj, _PytestWrapper):
            obj = new_obj.obj
            break
        new_obj = getattr(obj, "__wrapped__", None)
        if new_obj is None:
            break
        obj = new_obj
    else:
        raise ValueError(
            ("could not find real function of {start}\nstopped at {current}").format(
                start=saferepr(start_obj), current=saferepr(obj)
            )
        )
    if isinstance(obj, functools.partial):
        obj = obj.func
    return obj

def register(self, plugin, name=None):
    if name in ["pytest_catchlog", "pytest_capturelog"]:
        warnings.warn(
            PytestConfigWarning(
                "{} plugin has been merged into the core, "
                "please remove it from your requirements.".format(
                    name.replace("_", "-")
                )
            )
        )
        return
    ret = super(PytestPluginManager, self).register(plugin, name)
    if ret:
        self.hook.pytest_plugin_registered.call_historic(
            kwargs=dict(plugin=plugin, manager=self)
        )

        if isinstance(plugin, types.ModuleType):
            self.consider_module(plugin)
    return ret

def consider_pluginarg(self, arg):
    if arg.startswith("no:"):
        name = arg[3:]
        if name in essential_plugins:
            raise UsageError("plugin %s cannot be disabled" % name)

        # PR #4304 : remove stepwise if cacheprovider is blocked
        if name == "cacheprovider":
            self.set_blocked("stepwise")
            self.set_blocked("pytest_stepwise")

        self.set_blocked(name)
        if not name.startswith("pytest_"):
            self.set_blocked("pytest_" + name)
    else:
        name = arg
        # Unblock the plugin.  None indicates that it has been blocked.
        # There is no interface with pluggy for this.
        if self._name2plugin.get(name, -1) is None:
            del self._name2plugin[name]
        if not name.startswith("pytest_"):
            if self._name2plugin.get("pytest_" + name, -1) is None:
                del self._name2plugin["pytest_" + name]
        self.import_plugin(arg, consider_entry_points=True)

def notify_exception(self, excinfo, option=None):
    if option and getattr(option, "fulltrace", False):
        style = "long"
    else:
        style = "native"
    excrepr = excinfo.getrepr(
        funcargs=True, showlocals=getattr(option, "showlocals", False), style=style
    )
    res = self.hook.pytest_internalerror(excrepr=excrepr, excinfo=excinfo)
    if not any(res):
        for line in str(excrepr).split("\n"):
            sys.stderr.write("INTERNALERROR> %s\n" % line)
            sys.stderr.flush()

def _checkversion(self):
    import pytest
    from pkg_resources import parse_version

    minver = self.inicfg.get("minversion", None)
    if minver:
        if parse_version(minver) > parse_version(pytest.__version__):
            raise pytest.UsageError(
                "%s:%d: requires pytest-%s, actual pytest-%s'"
                % (
                    self.inicfg.config.path,
                    self.inicfg.lineof("minversion"),
                    minver,
                    pytest.__version__,
                )
            )

def _getini(self, name):
    try:
        description, type, default = self._parser._inidict[name]
    except KeyError:
        raise ValueError("unknown configuration value: %r" % (name,))
    value = self._get_override_ini_value(name)
    if value is None:
        try:
            value = self.inicfg[name]
        except KeyError:
            if default is not None:
                return default
            if type is None:
                return ""
            return []
    if type == "pathlist":
        dp = py.path.local(self.inicfg.config.path).dirpath()
        values = []
        for relpath in shlex.split(value):
            values.append(dp.join(relpath, abs=True))
        return values
    elif type == "args":
        return shlex.split(value)
    elif type == "linelist":
        return [t for t in map(lambda x: x.strip(), value.split("\n")) if t]
    elif type == "bool":
        return bool(_strtobool(value.strip()))
    else:
        assert type is None
        return value

def __str__(self):
    if self.option_id:
        return "option %s: %s" % (self.option_id, self.msg)
    else:
        return self.msg

def __init__(self, *names, **attrs):
    """store parms in private vars for use in add_argument"""
    self._attrs = attrs
    self._short_opts = []
    self._long_opts = []
    self.dest = attrs.get("dest")
    if "%default" in (attrs.get("help") or ""):
        warnings.warn(
            'pytest now uses argparse. "%default" should be'
            ' changed to "%(default)s" ',
            DeprecationWarning,
            stacklevel=3,
        )
    try:
        typ = attrs["type"]
    except KeyError:
        pass
    else:
        # this might raise a keyerror as well, don't want to catch that
        if isinstance(typ, six.string_types):
            if typ == "choice":
                warnings.warn(
                    "`type` argument to addoption() is the string %r."
                    " For choices this is optional and can be omitted, "
                    " but when supplied should be a type (for example `str` or `int`)."
                    " (options: %s)" % (typ, names),
                    DeprecationWarning,
                    stacklevel=4,
                )
                # argparse expects a type here take it from
                # the type of the first element
                attrs["type"] = type(attrs["choices"][0])
            else:
                warnings.warn(
                    "`type` argument to addoption() is the string %r, "
                    " but when supplied should be a type (for example `str` or `int`)."
                    " (options: %s)" % (typ, names),
                    DeprecationWarning,
                    stacklevel=4,
                )
                attrs["type"] = Argument._typ_map[typ]
            # used in test_parseopt -> test_parse_defaultgetter
            self.type = attrs["type"]
        else:
            self.type = typ
    try:
        # attribute existence is tested in Config._processopt
        self.default = attrs["default"]
    except KeyError:
        pass
    self._set_opt_strings(names)
    if not self.dest:
        if self._long_opts:
            self.dest = self._long_opts[0][2:].replace("-", "_")
        else:
            try:
                self.dest = self._short_opts[0][1:]
            except IndexError:
                raise ArgumentError("need a long or short option", self)

def attrs(self):
    # update any attributes set by processopt
    attrs = "default dest help".split()
    if self.dest:
        attrs.append(self.dest)
    for attr in attrs:
        try:
            self._attrs[attr] = getattr(self, attr)
        except AttributeError:
            pass
    if self._attrs.get("help"):
        a = self._attrs["help"]
        a = a.replace("%default", "%(default)s")
        # a = a.replace('%prog', '%(prog)s')
        self._attrs["help"] = a
    return self._attrs

def _set_opt_strings(self, opts):
    """directly from optparse

    might not be necessary as this is passed to argparse later on"""
    for opt in opts:
        if len(opt) < 2:
            raise ArgumentError(
                "invalid option string %r: "
                "must be at least two characters long" % opt,
                self,
            )
        elif len(opt) == 2:
            if not (opt[0] == "-" and opt[1] != "-"):
                raise ArgumentError(
                    "invalid short option string %r: "
                    "must be of the form -x, (x any non-dash char)" % opt,
                    self,
                )
            self._short_opts.append(opt)
        else:
            if not (opt[0:2] == "--" and opt[2] != "-"):
                raise ArgumentError(
                    "invalid long option string %r: "
                    "must start with --, followed by non-dash" % opt,
                    self,
                )
            self._long_opts.append(opt)

def repr_failure(self, excinfo):
    import doctest

    failures = None
    if excinfo.errisinstance((doctest.DocTestFailure, doctest.UnexpectedException)):
        failures = [excinfo.value]
    elif excinfo.errisinstance(MultipleDoctestFailures):
        failures = excinfo.value.failures

    if failures is not None:
        reprlocation_lines = []
        for failure in failures:
            example = failure.example
            test = failure.test
            filename = test.filename
            if test.lineno is None:
                lineno = None
            else:
                lineno = test.lineno + example.lineno + 1
            message = type(failure).__name__
            reprlocation = ReprFileLocation(filename, lineno, message)
            checker = _get_checker()
            report_choice = _get_report_choice(
                self.config.getoption("doctestreport")
            )
            if lineno is not None:
                lines = failure.test.docstring.splitlines(False)
                # add line numbers to the left of the error message
                lines = [
                    "%03d %s" % (i + test.lineno + 1, x)
                    for (i, x) in enumerate(lines)
                ]
                # trim docstring error lines to 10
                lines = lines[max(example.lineno - 9, 0) : example.lineno + 1]
            else:
                lines = [
                    "EXAMPLE LOCATION UNKNOWN, not showing all tests of that example"
                ]
                indent = ">>>"
                for line in example.source.splitlines():
                    lines.append("??? %s %s" % (indent, line))
                    indent = "..."
            if isinstance(failure, doctest.DocTestFailure):
                lines += checker.output_difference(
                    example, failure.got, report_choice
                ).split("\n")
            else:
                inner_excinfo = ExceptionInfo(failure.exc_info)
                lines += ["UNEXPECTED EXCEPTION: %s" % repr(inner_excinfo.value)]
                lines += traceback.format_exception(*failure.exc_info)
            reprlocation_lines.append((reprlocation, lines))
        return ReprFailDoctest(reprlocation_lines)
    else:
        return super(DoctestItem, self).repr_failure(excinfo)

def pytest_report_header(config):
    lines = []
