def bin_xml_escape(arg):
    def repl(matchobj):
        i = ord(matchobj.group())
        if i <= 0xFF:
            return u"#x%02X" % i
        else:
            return u"#x%04X" % i

    return py.xml.raw(illegal_xml_re.sub(repl, py.xml.escape(arg)))

def _collectfile(
    self, fspath: Path, handle_dupes: bool = True
) -> Sequence[nodes.Collector]:
    assert (
        fspath.is_file()
    ), "{!r} is not a file (isdir={!r}, exists={!r}, islink={!r})".format(
        fspath, fspath.is_dir(), fspath.exists(), fspath.is_symlink()
    )
    ihook = self.gethookproxy(fspath)
    if not self.isinitpath(fspath):
        if ihook.pytest_ignore_collect(collection_path=fspath, config=self.config):
            return ()

    if handle_dupes:
        keepduplicates = self.config.getoption("keepduplicates")
        if not keepduplicates:
            duplicate_paths = self.config.pluginmanager._duplicatepaths
            if fspath in duplicate_paths:
                return ()
            else:
                duplicate_paths.add(fspath)

    return ihook.pytest_collect_file(file_path=fspath, parent=self)  # type: ignore[no-any-return]

def create_new_paste(contents):
    """
    Creates a new paste using bpaste.net service.

    :contents: paste contents as utf-8 encoded bytes
    :returns: url to the pasted contents
    """
    import re

    if sys.version_info < (3, 0):
        from urllib import urlopen, urlencode
    else:
        from urllib.request import urlopen
        from urllib.parse import urlencode

    params = {
        "code": contents,
        "lexer": "python3" if sys.version_info[0] == 3 else "python",
        "expiry": "1week",
    }
    url = "https://bpaste.net"
    response = urlopen(url, data=urlencode(params).encode("ascii")).read()
    m = re.search(r'href="/raw/(\w+)"', response.decode("utf-8"))
    if m:
        return "%s/show/%s" % (url, m.group(1))
    else:
        return "bad response: " + response

def on_rm_rf_error(
    func,
    path: str,
    excinfo: Union[
        BaseException,
        Tuple[Type[BaseException], BaseException, Optional[types.TracebackType]],
    ],
    *,
    start_path: Path,
) -> bool:
    """Handle known read-only errors during rmtree.

    The returned value is used only by our own tests.
    """
    if isinstance(excinfo, BaseException):
        exc = excinfo
    else:
        exc = excinfo[1]

    # Another process removed the file in the middle of the "rm_rf" (xdist for example).
    # More context: https://github.com/pytest-dev/pytest/issues/5974#issuecomment-543799018
    if isinstance(exc, FileNotFoundError):
        return False

    if not isinstance(exc, PermissionError):
        warnings.warn(
            PytestWarning(f"(rm_rf) error removing {path}\n{type(exc)}: {exc}")
        )
        return False

    if func not in (os.rmdir, os.remove, os.unlink):
        if func not in (os.open,):
            warnings.warn(
                PytestWarning(
                    "(rm_rf) unknown function {} when removing {}:\n{}: {}".format(
                        func, path, type(exc), exc
                    )
                )
            )
        return False

    # Chmod + retry.
    import stat

    def chmod_rw(p: str) -> None:
        mode = os.stat(p).st_mode
        os.chmod(p, mode | stat.S_IRUSR | stat.S_IWUSR)

    # For files, we need to recursively go upwards in the directories to
    # ensure they all are also writable.
    p = Path(path)
    if p.is_file():
        for parent in p.parents:
            chmod_rw(str(parent))
            # Stop when we reach the original path passed to rm_rf.
            if parent == start_path:
                break
    chmod_rw(str(path))

    func(path)
    return True

def make_numbered_dir(root, prefix):
    """create a directory with an increased number as suffix for the given prefix"""
    for i in range(10):
        # try up to 10 times to create the folder
        max_existing = _max(map(parse_num, find_suffixes(root, prefix)), default=-1)
        new_number = max_existing + 1
        new_path = root.joinpath("{}{}".format(prefix, new_number))
        try:
            new_path.mkdir()
        except Exception:
            pass
        else:
            _force_symlink(root, prefix + "current", new_path)
            return new_path
    else:
        raise EnvironmentError(
            "could not create numbered dir with prefix "
            "{prefix} in {root} after 10 tries".format(prefix=prefix, root=root)
        )

def register_cleanup_lock_removal(lock_path, register=atexit.register):
    """registers a cleanup function for removing a lock, by default on atexit"""
    pid = os.getpid()

    def cleanup_on_exit(lock_path=lock_path, original_pid=pid):
        current_pid = os.getpid()
        if current_pid != original_pid:
            # fork
            return
        try:
            lock_path.unlink()
        except (OSError, IOError):
            pass

    return register(cleanup_on_exit)

def popcall(self, name: str) -> RecordedHookCall:
    __tracebackhide__ = True
    for i, call in enumerate(self.calls):
        if call._name == name:
            del self.calls[i]
            return call
    lines = [f"could not find call {name!r}, in:"]
    lines.extend(["  %s" % x for x in self.calls])
    fail("\n".join(lines))

def __exit__(self, *exc_info):
    super(WarningsChecker, self).__exit__(*exc_info)

    __tracebackhide__ = True

    # only check if we're not currently handling an exception
    if all(a is None for a in exc_info):
        if self.expected_warning is not None:
            if not any(issubclass(r.category, self.expected_warning) for r in self):
                __tracebackhide__ = True
                fail(
                    "DID NOT WARN. No warnings of type {} was emitted. "
                    "The list of emitted warnings is: {}.".format(
                        self.expected_warning, [each.message for each in self]
                    )
                )
            elif self.match_expr is not None:
                for r in self:
                    if issubclass(r.category, self.expected_warning):
                        if re.compile(self.match_expr).search(str(r.message)):
                            break
                else:
                    fail(
                        "DID NOT WARN. No warnings of type {} matching"
                        " ('{}') was emitted. The list of emitted warnings"
                        " is: {}.".format(
                            self.expected_warning,
                            self.match_expr,
                            [each.message for each in self],
                        )
                    )

def pytest_report_collectionfinish(self):
    if self.active and self.config.getoption("verbose") >= 0:
        return "stepwise: %s" % self.report_status

def get_location(self, config):
    """
    Returns the more user-friendly information about the location
    of a warning, or None.
    """
    if self.nodeid:
        return self.nodeid
    if self.fslocation:
        if isinstance(self.fslocation, tuple) and len(self.fslocation) >= 2:
            filename, linenum = self.fslocation[:2]
            relpath = py.path.local(filename).relto(config.invocation_dir)
            if not relpath:
                relpath = str(filename)
            return "%s:%s" % (relpath, linenum)
        else:
            return str(self.fslocation)
    return None

def report_collect(self, final=False):
    if self.config.option.verbose < 0:
        return

    if not final:
        # Only write "collecting" report every 0.5s.
        t = time.time()
        if (
            self._collect_report_last_write is not None
            and self._collect_report_last_write > t - REPORT_COLLECTING_RESOLUTION
        ):
            return
        self._collect_report_last_write = t

    errors = len(self.stats.get("error", []))
    skipped = len(self.stats.get("skipped", []))
    deselected = len(self.stats.get("deselected", []))
    selected = self._numcollected - errors - skipped - deselected
    if final:
        line = "collected "
    else:
        line = "collecting "
    line += (
        str(self._numcollected) + " item" + ("" if self._numcollected == 1 else "s")
    )
    if errors:
        line += " / %d errors" % errors
    if deselected:
        line += " / %d deselected" % deselected
    if skipped:
        line += " / %d skipped" % skipped
    if self._numcollected > selected > 0:
        line += " / %d selected" % selected
    if self.isatty:
        self.rewrite(line, bold=True, erase=True)
        if final:
            self.write("\n")
    else:
        self.write_line(line)

def _printcollecteditems(self, items):
    # to print out items and their parent collectors
    # we take care to leave out Instances aka ()
    # because later versions are going to get rid of them anyway
    if self.config.option.verbose < 0:
        if self.config.option.verbose < -1:
            counts = {}
            for item in items:
                name = item.nodeid.split("::", 1)[0]
                counts[name] = counts.get(name, 0) + 1
            for name, count in sorted(counts.items()):
                self._tw.line("%s: %d" % (name, count))
        else:
            for item in items:
                self._tw.line(item.nodeid)
        return
    stack = []
    indent = ""
    for item in items:
        needed_collectors = item.listchain()[1:]  # strip root node
        while stack:
            if stack == needed_collectors[: len(stack)]:
                break
            stack.pop()
        for col in needed_collectors[len(stack) :]:
            stack.append(col)
            if col.name == "()":  # Skip Instances.
                continue
            indent = (len(stack) - 1) * "  "
            self._tw.line("%s%s" % (indent, col))
            if self.config.option.verbose >= 1:
                if hasattr(col, "_obj") and col._obj.__doc__:
                    for line in col._obj.__doc__.strip().splitlines():
                        self._tw.line("%s%s" % (indent + "  ", line.strip()))

def _plugin_nameversions(plugininfo):
    values = []
    for plugin, dist in plugininfo:
        # gets us name and version!
        name = "{dist.project_name}-{dist.version}".format(dist=dist)
        # questionable convenience, but it keeps things short
        if name.startswith("pytest-"):
            name = name[7:]
        # we decided to print python package names
        # they can have more than one plugin
        if name not in values:
            values.append(name)
    return values

def _addexcinfo(self, rawexcinfo):
    # unwrap potential exception info (see twisted trial support below)
    rawexcinfo = getattr(rawexcinfo, "_rawexcinfo", rawexcinfo)
    try:
        excinfo = _pytest._code.ExceptionInfo(rawexcinfo)
        # invoke the attributes to trigger storing the traceback
        # trial causes some issue there
        excinfo.value
        excinfo.traceback
    except TypeError:
        try:
            try:
                values = traceback.format_exception(*rawexcinfo)
                values.insert(
                    0,
                    "NOTE: Incompatible Exception Representation, "
                    "displaying natively:\n\n",
                )
                fail("".join(values), pytrace=False)
            except (fail.Exception, KeyboardInterrupt):
                raise
            except:  # noqa
                fail(
                    "ERROR: Unknown Incompatible Exception "
                    "representation:\n%r" % (rawexcinfo,),
                    pytrace=False,
                )
        except KeyboardInterrupt:
            raise
        except fail.Exception:
            excinfo = _pytest._code.ExceptionInfo.from_current()
    self.__dict__.setdefault("_excinfo", []).append(excinfo)

def test_no_recursion_index_on_recursion_error():
    """
    Ensure that we don't break in case we can't find the recursion index
    during a recursion error (#2486).
    """

    class RecursionDepthError(object):
        def __getattr__(self, attr):
            return getattr(self, "_" + attr)

    with pytest.raises(RuntimeError) as excinfo:
        RecursionDepthError().trigger
    assert "maximum recursion" in str(excinfo.getrepr())

def _clone_parametrized(estimator, *, safe=True):
    """Default implementation of clone. See :func:`sklearn.base.clone` for details."""

    estimator_type = type(estimator)
    # XXX: not handling dictionaries
    if estimator_type in (list, tuple, set, frozenset):
        return estimator_type([clone(e, safe=safe) for e in estimator])
    elif not hasattr(estimator, "get_params") or isinstance(estimator, type):
        if not safe:
            return copy.deepcopy(estimator)
        else:
            if isinstance(estimator, type):
                raise TypeError(
                    "Cannot clone object. "
                    + "You should provide an instance of "
                    + "scikit-learn estimator instead of a class."
                )
            else:
                raise TypeError(
                    "Cannot clone object '%s' (type %s): "
                    "it does not seem to be a scikit-learn "
                    "estimator as it does not implement a "
                    "'get_params' method." % (repr(estimator), type(estimator))
                )

    klass = estimator.__class__
    new_object_params = estimator.get_params(deep=False)
    for name, param in new_object_params.items():
        new_object_params[name] = clone(param, safe=False)
    new_object = klass(**new_object_params)
    params_set = new_object.get_params(deep=False)

    # quick sanity check of the parameters of the clone
    for name in new_object_params:
        param1 = new_object_params[name]
        param2 = params_set[name]
        if param1 is not param2:
            raise RuntimeError(
                "Cannot clone object %s, as the constructor "
                "either does not set or modifies parameter %s" % (estimator, name)
            )

    # _sklearn_output_config is used by `set_output` to configure the output
    # container of an estimator.
    if hasattr(estimator, "_sklearn_output_config"):
        new_object._sklearn_output_config = copy.deepcopy(
            estimator._sklearn_output_config
        )
    return new_object

def _gen_open(f):
    if isinstance(f, int):  # file descriptor
        return io.open(f, "rb", closefd=False)
    elif not isinstance(f, six.string_types):
        raise TypeError("expected {str, int, file-like}, got %s" % type(f))

    _, ext = os.path.splitext(f)
    if ext == ".gz":
        import gzip
        return gzip.open(f, "rb")
    elif ext == ".bz2":
        from bz2 import BZ2File
        return BZ2File(f, "rb")
    else:
        return open(f, "rb")

def _dump_svmlight(X, y, f, multilabel, one_based, comment, query_id):
    X_is_sp = int(hasattr(X, "tocsr"))
    y_is_sp = int(hasattr(y, "tocsr"))
    if X.dtype.kind == 'i':
        value_pattern = u("%d:%d")
    else:
        value_pattern = u("%d:%.16g")

    if y.dtype.kind == 'i':
        label_pattern = u("%d")
    else:
        label_pattern = u("%.16g")

    line_pattern = u("%s")
    if query_id is not None:
        line_pattern += u(" qid:%d")
    line_pattern += u(" %s\n")

    if comment:
        f.write(b("# Generated by dump_svmlight_file from scikit-learn %s\n"
                % __version__))
        f.write(b("# Column indices are %s-based\n"
                  % ["zero", "one"][one_based]))

        f.write(b("#\n"))
        f.writelines(b("# %s\n" % line) for line in comment.splitlines())

    for i in range(X.shape[0]):
        if X_is_sp:
            span = slice(X.indptr[i], X.indptr[i + 1])
            row = zip(X.indices[span], X.data[span])
        else:
            nz = X[i] != 0
            row = zip(np.where(nz)[0], X[i, nz])

        s = " ".join(value_pattern % (j + one_based, x) for j, x in row)

        if multilabel:
            if y_is_sp:
                nz_labels = y[i].nonzero()[1]
            else:
                nz_labels = np.where(y[i] != 0)[0]
            labels_str = ",".join(label_pattern % j for j in nz_labels)
        else:
            if y_is_sp:
                labels_str = label_pattern % y.data[i]
            else:
                labels_str = label_pattern % y[i]

        if query_id is not None:
            feat = (labels_str, query_id[i], s)
        else:
            feat = (labels_str, s)

        f.write((line_pattern % feat).encode('ascii'))

def __call__(self, y, pred, sample_weight=None):
    """Compute the deviance (= 2 * negative log-likelihood). """
    # logaddexp(0, v) == log(1.0 + exp(v))
    pred = pred.ravel()
    if sample_weight is None:
        return -2.0 * np.mean((y * pred) - np.logaddexp(0.0, pred))
    else:
        return (-2.0 / sample_weight.sum() *
                np.sum(sample_weight * ((y * pred) - np.logaddexp(0.0, pred))))

def transform(self, X):
    """Transform feature->value dicts to array or sparse matrix.

    Named features not encountered during fit or fit_transform will be
    silently ignored.

    Parameters
    ----------
    X : Mapping or iterable over Mappings, length = n_samples
        Dict(s) or Mapping(s) from feature names (arbitrary Python
        objects) to feature values (strings or convertible to dtype).

    Returns
    -------
    Xa : {array, sparse matrix}
        Feature vectors; always 2-d.
    """
    if self.sparse:
        return self._transform(X, fitting=False)

    else:
        dtype = self.dtype
        vocab = self.vocabulary_
        X = _tosequence(X)
        Xa = np.zeros((len(X), len(vocab)), dtype=dtype)

        for i, x in enumerate(X):
            for f, v in six.iteritems(x):
                if isinstance(v, six.string_types):
                    f = "%s%s%s" % (f, self.separator, v)
                    v = 1
                try:
                    Xa[i, vocab[f]] = dtype(v)
                except KeyError:
                    pass

        return Xa

def _mask_edges_weights(mask, edges, weights=None):
    """Apply a mask to edges (weighted or not)"""
    inds = np.arange(mask.size)
    inds = inds[mask.ravel()]
    ind_mask = np.logical_and(np.in1d(edges[0], inds),
                              np.in1d(edges[1], inds))
    edges = edges[:, ind_mask]
    if weights is not None:
        weights = weights[ind_mask]
    if len(edges.ravel()):
        maxval = edges.max()
    else:
        maxval = 0
    order = np.searchsorted(np.unique(edges.ravel()), np.arange(maxval + 1))
    edges = order[edges]
    if weights is None:
        return edges
    else:
        return edges, weights

def _check_stop_list(stop):
    if stop == "english":
        return ENGLISH_STOP_WORDS
    elif isinstance(stop, six.string_types):
        raise ValueError("not a built-in stop list: %s" % stop)
    elif stop is None:
        return None
    else:               # assume it's a collection
        return frozenset(stop)

def build_preprocessor(self):
    """Return a function to preprocess the text before tokenization"""
    if self.preprocessor is not None:
        return self.preprocessor

    # unfortunately python functools package does not have an efficient
    # `compose` function that would have allowed us to chain a dynamic
    # number of functions. However the cost of a lambda call is a few
    # hundreds of nanoseconds which is negligible when compared to the
    # cost of tokenizing a string of 1000 chars for instance.
    noop = lambda x: x

    # accent stripping
    if not self.strip_accents:
        strip_accents = noop
    elif callable(self.strip_accents):
        strip_accents = self.strip_accents
    elif self.strip_accents == 'ascii':
        strip_accents = strip_accents_ascii
    elif self.strip_accents == 'unicode':
        strip_accents = strip_accents_unicode
    else:
        raise ValueError('Invalid value for "strip_accents": %s' %
                         self.strip_accents)

    if self.lowercase:
        return lambda x: strip_accents(x.lower())
    else:
        return strip_accents

def build_analyzer(self):
    """Return a callable that handles preprocessing and tokenization"""
    if callable(self.analyzer):
        return self.analyzer

    preprocess = self.build_preprocessor()

    if self.analyzer == 'char':
        return lambda doc: self._char_ngrams(preprocess(self.decode(doc)))

    elif self.analyzer == 'char_wb':
        return lambda doc: self._char_wb_ngrams(
            preprocess(self.decode(doc)))

    elif self.analyzer == 'word':
        stop_words = self.get_stop_words()
        tokenize = self.build_tokenizer()

        return lambda doc: self._word_ngrams(
            tokenize(preprocess(self.decode(doc))), stop_words)

    else:
        raise ValueError('%s is not a valid tokenization scheme/analyzer' %
                         self.analyzer)

def idf_(self, value):
    if not self.use_idf:
        raise ValueError("`idf_` cannot be set when `user_idf=False`.")
    if not hasattr(self, "_tfidf"):
        # We should support transferring `idf_` from another `TfidfTransformer`
        # and therefore, we need to create the transformer instance it does not
        # exist yet.
        self._tfidf = TfidfTransformer(
            norm=self.norm,
            use_idf=self.use_idf,
            smooth_idf=self.smooth_idf,
            sublinear_tf=self.sublinear_tf,
        )
    self._validate_vocabulary()
    if hasattr(self, "vocabulary_"):
        if len(self.vocabulary_) != len(value):
            raise ValueError(
                "idf length = %d must be equal to vocabulary size = %d"
                % (len(value), len(self.vocabulary))
            )
    self._tfidf.idf_ = value

def theta(self):
    """Returns the (flattened, log-transformed) non-fixed hyperparameters.

    Note that theta are typically the log-transformed values of the
    kernel's hyperparameters as this representation of the search space
    is more amenable for hyperparameter search, as hyperparameters like
    length-scales naturally live on a log-scale.

    Returns
    -------
    theta : array, shape (n_dims,)
        The non-fixed, log-transformed hyperparameters of the kernel
    """
    theta = []
    params = self.get_params()
    for hyperparameter in self.hyperparameters:
        if not hyperparameter.fixed:
            theta.append(params[hyperparameter.name])
    if len(theta) > 0:
        return np.log(np.hstack(theta))
    else:
        return np.array([])

def bounds(self):
    """Returns the log-transformed bounds on the theta.

    Returns
    -------
    bounds : array, shape (n_dims, 2)
        The log-transformed bounds on the kernel's hyperparameters theta
    """
    bounds = []
    for hyperparameter in self.hyperparameters:
        if not hyperparameter.fixed:
            bounds.append(hyperparameter.bounds)
    if len(bounds) > 0:
        return np.log(np.vstack(bounds))
    else:
        return np.array([])

def __repr__(self):
    if self.anisotropic:
        return "{0}(length_scale=[{1}], nu={2:.3g})".format(
            self.__class__.__name__,
            ", ".join(map("{0:.3g}".format, self.length_scale)),
            self.nu)
    else:
        return "{0}(length_scale={1:.3g}, nu={2:.3g})".format(
            self.__class__.__name__, np.ravel(self.length_scale)[0],
            self.nu)

def __iter__(self):
    # check if all distributions are given as lists
    # in this case we want to sample without replacement
    all_lists = np.all([not hasattr(v, "rvs")
                        for v in self.param_distributions.values()])
    rnd = check_random_state(self.random_state)

    if all_lists:
        # look up sampled parameter settings in parameter grid
        param_grid = ParameterGrid(self.param_distributions)
        grid_size = len(param_grid)

        if grid_size < self.n_iter:
            raise ValueError(
                "The total space of parameters %d is smaller "
                "than n_iter=%d." % (grid_size, self.n_iter)
                + " For exhaustive searches, use GridSearchCV.")
        for i in sample_without_replacement(grid_size, self.n_iter,
                                            random_state=rnd):
            yield param_grid[i]

    else:
        # Always sort the keys of a dictionary, for reproducibility
        items = sorted(self.param_distributions.items())
        for _ in six.moves.range(self.n_iter):
            params = dict()
            for k, v in items:
                if hasattr(v, "rvs"):
                    params[k] = v.rvs()
                else:
                    params[k] = v[rnd.randint(len(v))]
            yield params

def _check_subparams(self, n_samples, n_features):
    n_subsamples = self.n_subsamples

    if self.fit_intercept:
        n_dim = n_features + 1
    else:
        n_dim = n_features

    if n_subsamples is not None:
        if n_subsamples > n_samples:
            raise ValueError("Invalid parameter since n_subsamples > "
                             "n_samples ({0} > {1}).".format(n_subsamples,
                                                             n_samples))
        if n_samples >= n_features:
            if n_dim > n_subsamples:
                plus_1 = "+1" if self.fit_intercept else ""
                raise ValueError("Invalid parameter since n_features{0} "
                                 "> n_subsamples ({1} > {2})."
                                 "".format(plus_1, n_dim, n_samples))
        else:  # if n_samples < n_features
            if n_subsamples != n_samples:
                raise ValueError("Invalid parameter since n_subsamples != "
                                 "n_samples ({0} != {1}) while n_samples "
                                 "< n_features.".format(n_subsamples,
                                                        n_samples))
    else:
        n_subsamples = min(n_dim, n_samples)

    if self.max_subpopulation <= 0:
        raise ValueError("Subpopulation must be strictly positive "
                         "({0} <= 0).".format(self.max_subpopulation))

    all_combinations = max(1, np.rint(binom(n_samples, n_subsamples)))
    n_subpopulation = int(min(self.max_subpopulation, all_combinations))

    return n_subsamples, n_subpopulation

def _fit_binary(estimator, X, y, classes=None):
    """Fit a single binary estimator."""
    unique_y = np.unique(y)
    if len(unique_y) == 1:
        if classes is not None:
            if y[0] == -1:
                c = 0
            else:
                c = y[0]
            warnings.warn("Label %s is present in all training examples." %
                          str(classes[c]))
        estimator = _ConstantPredictor().fit(X, unique_y)
    else:
        estimator = clone(estimator)
        estimator.fit(X, y)
    return estimator

def _check_alpha(self):
    if np.min(self.alpha) < 0:
        raise ValueError('Smoothing parameter alpha = %.1e. '
                         'alpha should be > 0.' % np.min(self.alpha))
    if isinstance(self.alpha, np.ndarray):
        if not self.alpha.shape[0] == self.feature_count_.shape[1]:
            raise ValueError("alpha should be a scalar or a numpy array "
                             "with shape [n_features]")
    if np.min(self.alpha) < _ALPHA_MIN:
        warnings.warn('alpha too small will result in numeric errors, '
                      'setting alpha = %.1e' % _ALPHA_MIN)
        return np.maximum(self.alpha, _ALPHA_MIN)
    return self.alpha

def _check_algorithm_metric(self):
    if self.algorithm == "auto":
        if self.metric == "precomputed":
            alg_check = "brute"
        elif callable(self.metric) or self.metric in VALID_METRICS["ball_tree"]:
            alg_check = "ball_tree"
        else:
            alg_check = "brute"
    else:
        alg_check = self.algorithm

    if callable(self.metric):
        if self.algorithm == "kd_tree":
            # callable metric is only valid for brute force and ball_tree
            raise ValueError(
                "kd_tree does not support callable metric '%s'"
                "Function call overhead will result"
                "in very poor performance."
                % self.metric
            )
    elif self.metric not in VALID_METRICS[alg_check]:
        raise ValueError(
            "Metric '%s' not valid. Use "
            "sorted(sklearn.neighbors.VALID_METRICS['%s']) "
            "to get valid options. "
            "Metric can also be a callable function." % (self.metric, alg_check)
        )

    if self.metric_params is not None and "p" in self.metric_params:
        if self.p is not None:
            warnings.warn(
                "Parameter p is found in metric_params. "
                "The corresponding parameter from __init__ "
                "is ignored.",
                SyntaxWarning,
                stacklevel=3,
            )

def _choose_algorithm(self, algorithm, metric):
    # given the algorithm string + metric string, choose the optimal
    # algorithm to compute the result.
    if algorithm == "auto":
        # use KD Tree if possible
        if metric in KDTree.valid_metrics():
            return "kd_tree"
        elif metric in BallTree.valid_metrics():
            return "ball_tree"
    else:  # kd_tree or ball_tree
        if metric not in TREE_DICT[algorithm].valid_metrics():
            raise ValueError(
                "invalid metric for {0}: '{1}'".format(TREE_DICT[algorithm], metric)
            )
        return algorithm

def _get_kernel(self, X, y=None):
    if self.kernel == "rbf":
        if y is None:
            return rbf_kernel(X, X, gamma=self.gamma)
        else:
            return rbf_kernel(X, y, gamma=self.gamma)
    elif self.kernel == "knn":
        if self.nn_fit is None:
            self.nn_fit = NearestNeighbors(self.n_neighbors,
                                           n_jobs=self.n_jobs).fit(X)
        if y is None:
            return self.nn_fit.kneighbors_graph(self.nn_fit._fit_X,
                                                self.n_neighbors,
                                                mode='connectivity')
        else:
            return self.nn_fit.kneighbors(y, return_distance=False)
    elif callable(self.kernel):
        if y is None:
            return self.kernel(X, X)
        else:
            return self.kernel(X, y)
    else:
        raise ValueError("%s is not a valid kernel. Only rbf and knn"
                         " or an explicit function "
                         " are supported at this time." % self.kernel)

def _validate_for_predict(self, X):
    check_is_fitted(self)

    if not callable(self.kernel):
        X = self._validate_data(
            X,
            accept_sparse="csr",
            dtype=np.float64,
            order="C",
            accept_large_sparse=False,
            reset=False,
        )

    if self._sparse and not sp.isspmatrix(X):
        X = sp.csr_matrix(X)
    if self._sparse:
        X.sort_indices()

    if sp.issparse(X) and not self._sparse and not callable(self.kernel):
        raise ValueError(
            "cannot use sparse input in %r trained on dense data"
            % type(self).__name__
        )

    if self.kernel == "precomputed":
        if X.shape[1] != self.shape_fit_[0]:
            raise ValueError(
                "X.shape[1] = %d should be equal to %d, "
                "the number of samples at training time"
                % (X.shape[1], self.shape_fit_[0])
            )
    # Fixes https://nvd.nist.gov/vuln/detail/CVE-2020-28975
    # Check that _n_support is consistent with support_vectors
    sv = self.support_vectors_
    if not self._sparse and sv.size > 0 and self.n_support_.sum() != sv.shape[0]:
        raise ValueError(
            f"The internal representation of {self.__class__.__name__} was altered"
        )
    return X

def export(self, decision_tree):
    # Check length of feature_names before getting into the tree node
    # Raise error if length of feature_names does not match
    # n_features_in_ in the decision_tree
    if self.feature_names is not None:
        if len(self.feature_names) != decision_tree.n_features_in_:
            raise ValueError(
                "Length of feature_names, %d does not match number of features, %d"
                % (len(self.feature_names), decision_tree.n_features_in_)
            )
    # each part writes to out_file
    self.head()
    # Now recurse the tree and add node & edge attributes
    if isinstance(decision_tree, _tree.Tree):
        self.recurse(decision_tree, 0, criterion="impurity")
    else:
        self.recurse(decision_tree.tree_, 0, criterion=decision_tree.criterion)

    self.tail()

def ancestor(vil, v, default_ancestor):
    # the relevant text is at the bottom of page 7 of
    # "Improving Walker's Algorithm to Run in Linear Time" by Buchheim et al,
    # (2002)
    # https://citeseerx.ist.psu.edu/doc_view/pid/1f41c3c2a4880dc49238e46d555f16d28da2940d
    if vil.ancestor in v.parent.children:
        return vil.ancestor
    else:
        return default_ancestor

def _get_column_indices(X, key):
    """Get feature column indices for input data X and key.

    For accepted values of `key`, see the docstring of
    :func:`_safe_indexing_column`.
    """
    n_columns = X.shape[1]

    key_dtype = _determine_key_type(key)

    if isinstance(key, (list, tuple)) and not key:
        # we get an empty list
        return []
    elif key_dtype in ("bool", "int"):
        # Convert key into positive indexes
        try:
            idx = _safe_indexing(np.arange(n_columns), key)
        except IndexError as e:
            raise ValueError(
                "all features must be in [0, {}] or [-{}, 0]".format(
                    n_columns - 1, n_columns
                )
            ) from e
        return np.atleast_1d(idx).tolist()
    elif key_dtype == "str":
        try:
            all_columns = X.columns
        except AttributeError:
            raise ValueError(
                "Specifying the columns using strings is only "
                "supported for pandas DataFrames"
            )
        if isinstance(key, str):
            columns = [key]
        elif isinstance(key, slice):
            start, stop = key.start, key.stop
            if start is not None:
                start = all_columns.get_loc(start)
            if stop is not None:
                # pandas indexing with strings is endpoint included
                stop = all_columns.get_loc(stop) + 1
            else:
                stop = n_columns + 1
            return list(islice(range(n_columns), start, stop))
        else:
            columns = list(key)

        try:
            column_indices = []
            for col in columns:
                col_idx = all_columns.get_loc(col)
                if not isinstance(col_idx, numbers.Integral):
                    raise ValueError(
                        f"Selected columns, {columns}, are not unique in dataframe"
                    )
                column_indices.append(col_idx)

        except KeyError as e:
            raise ValueError("A given column is not a column of the dataframe") from e

        return column_indices
    else:
        raise ValueError(
            "No valid specification of the columns. Only a "
            "scalar, list or slice of all integers or all "
            "strings, or boolean mask is allowed"
        )

def check_set_params(name, estimator_orig):
    # Check that get_params() returns the same thing
    # before and after set_params() with some fuzz
    estimator = clone(estimator_orig)

    orig_params = estimator.get_params(deep=False)
    msg = "get_params result does not match what was passed to set_params"

    estimator.set_params(**orig_params)
    curr_params = estimator.get_params(deep=False)
    assert set(orig_params.keys()) == set(curr_params.keys()), msg
    for k, v in curr_params.items():
        assert orig_params[k] is v, msg

    # some fuzz values
    test_values = [-np.inf, np.inf, None]

    test_params = deepcopy(orig_params)
    for param_name in orig_params.keys():
        default_value = orig_params[param_name]
        for value in test_values:
            test_params[param_name] = value
            try:
                estimator.set_params(**test_params)
            except (TypeError, ValueError) as e:
                e_type = e.__class__.__name__
                # Exception occurred, possibly parameter validation
                warnings.warn(
                    "{0} occurred during set_params of param {1} on "
                    "{2}. It is recommended to delay parameter "
                    "validation until fit.".format(e_type, param_name, name)
                )

                change_warning_msg = (
                    "Estimator's parameters changed after set_params raised {}".format(
                        e_type
                    )
                )
                params_before_exception = curr_params
                curr_params = estimator.get_params(deep=False)
                try:
                    assert set(params_before_exception.keys()) == set(
                        curr_params.keys()
                    )
                    for k, v in curr_params.items():
                        assert params_before_exception[k] is v
                except AssertionError:
                    warnings.warn(change_warning_msg)
            else:
                curr_params = estimator.get_params(deep=False)
                assert set(test_params.keys()) == set(curr_params.keys()), msg
                for k, v in curr_params.items():
                    assert test_params[k] is v, msg
        test_params[param_name] = default_value

def _arg_min_or_max(self, axis, out, op, compare):
    if out is not None:
        raise ValueError("Sparse matrices do not support "
                         "an 'out' parameter.")

    # validateaxis(axis)

    if axis is None:
        if 0 in self.shape:
            raise ValueError("Can't apply the operation to "
                             "an empty matrix.")

        if self.nnz == 0:
            return 0
        else:
            zero = self.dtype.type(0)
            mat = self.tocoo()
            mat.sum_duplicates()
            am = op(mat.data)
            m = mat.data[am]

            if compare(m, zero):
                return mat.row[am] * mat.shape[1] + mat.col[am]
            else:
                size = np.product(mat.shape)
                if size == mat.nnz:
                    return am
                else:
                    ind = mat.row * mat.shape[1] + mat.col
                    zero_ind = _find_missing_index(ind, size)
                    if m == zero:
                        return min(zero_ind, am)
                    else:
                        return zero_ind

    return _arg_min_or_max_axis(self, axis, op, compare)

def _num_samples(x):
    """Return number of samples in array-like x."""
    if hasattr(x, 'fit') and callable(x.fit):
        # Don't get num_samples from an ensembles length!
        raise TypeError('Expected sequence or array-like, got '
                        'estimator %s' % x)
    if not hasattr(x, '__len__') and not hasattr(x, 'shape'):
        if hasattr(x, '__array__'):
            x = np.asarray(x)
        else:
            raise TypeError("Expected sequence or array-like, got %s" %
                            type(x))
    if hasattr(x, 'shape'):
        if len(x.shape) == 0:
            raise TypeError("Singleton array %r cannot be considered"
                            " a valid collection." % x)
        return x.shape[0]
    else:
        return len(x)

def check_non_negative(X, whom):
    """
    Check if there is any negative value in an array.

    Parameters
    ----------
    X : {array-like, sparse matrix}
        Input data.

    whom : str
        Who passed X to this function.
    """
    xp, _ = get_namespace(X)
    # avoid X.min() on sparse matrix since it also sorts the indices
    if sp.issparse(X):
        if X.format in ["lil", "dok"]:
            X = X.tocsr()
        if X.data.size == 0:
            X_min = 0
        else:
            X_min = X.data.min()
    else:
        X_min = xp.min(X)

    if X_min < 0:
        raise ValueError("Negative values in data passed to %s" % whom)

def _parse_arguments(argv: list[str] = sys.argv[1:]) -> argparse.Namespace:
    parser = get_parser()
    args = parser.parse_args(argv)

    if args.noconfig:
        args.confdir = None
    elif not args.confdir:
        args.confdir = args.sourcedir

    if not args.doctreedir:
        args.doctreedir = os.path.join(args.outputdir, '.doctrees')

    if args.force_all and args.filenames:
        parser.error(__('cannot combine -a option and filenames'))

    if args.color == 'no' or (args.color == 'auto' and not color_terminal()):
        nocolor()

    status: TextIO | None = sys.stdout
    warning: TextIO | None = sys.stderr
    error = sys.stderr

    if args.quiet:
        status = None

    if args.really_quiet:
        status = warning = None

    if warning and args.warnfile:
        try:
            warnfile = abspath(args.warnfile)
            ensuredir(path.dirname(warnfile))
            warnfp = open(args.warnfile, 'w', encoding="utf-8")
        except Exception as exc:
            parser.error(__('cannot open warning file %r: %s') % (
                args.warnfile, exc))
        warning = Tee(warning, warnfp)  # type: ignore
        error = warning

    args.status = status
    args.warning = warning
    args.error = error

    confoverrides = {}
    for val in args.define:
        try:
            key, val = val.split('=', 1)
        except ValueError:
            parser.error(__('-D option argument must be in the form name=value'))
        confoverrides[key] = val

    for val in args.htmldefine:
        try:
            key, val = val.split('=')
        except ValueError:
            parser.error(__('-A option argument must be in the form name=value'))
        try:
            val = int(val)
        except ValueError:
            pass
        confoverrides['html_context.%s' % key] = val

    if args.nitpicky:
        confoverrides['nitpicky'] = True

    args.confoverrides = confoverrides

    return args

def __init__(self, config: dict[str, Any] = {}, overrides: dict[str, Any] = {}) -> None:
    self.overrides = dict(overrides)
    self.values = Config.config_values.copy()
    self._raw_config = config
    self.setup: Callable | None = config.get('setup', None)

    if 'extensions' in self.overrides:
        if isinstance(self.overrides['extensions'], str):
            config['extensions'] = self.overrides.pop('extensions').split(',')
        else:
            config['extensions'] = self.overrides.pop('extensions')
    self.extensions: list[str] = config.get('extensions', [])

def check_confval_types(app: "Sphinx", config: Config) -> None:
    """check all values for deviation from the default value's type, since
    that can result in TypeErrors all over the place NB.
    """
    for confval in config:
        default, rebuild, annotations = config.values[confval.name]

        if hasattr(default, '__call__'):
            default = default(config)  # evaluate default value
        if default is None and not annotations:
            continue  # neither inferrable nor expliclitly annotated types

        if annotations is Any:
            # any type of value is accepted
            pass
        elif isinstance(annotations, ENUM):
            if not annotations.match(confval.value):
                msg = __("The config value `{name}` has to be a one of {candidates}, "
                         "but `{current}` is given.")
                logger.warning(msg.format(name=confval.name,
                                          current=confval.value,
                                          candidates=annotations.candidates))
        else:
            if type(confval.value) is type(default):
                continue
            if type(confval.value) in annotations:
                continue

            common_bases = (set(type(confval.value).__bases__ + (type(confval.value),)) &
                            set(type(default).__bases__))
            common_bases.discard(object)
            if common_bases:
                continue  # at least we share a non-trivial base class

            if annotations:
                msg = __("The config value `{name}' has type `{current.__name__}'; "
                         "expected {permitted}.")
                wrapped_annotations = ["`{}'".format(c.__name__) for c in annotations]
                if len(wrapped_annotations) > 2:
                    permitted = "{}, or {}".format(
                        ", ".join(wrapped_annotations[:-1]),
                        wrapped_annotations[-1])
                else:
                    permitted = " or ".join(wrapped_annotations)
                logger.warning(msg.format(name=confval.name,
                                          current=type(confval.value),
                                          permitted=permitted))
            else:
                msg = __("The config value `{name}' has type `{current.__name__}', "
                         "defaults to `{default.__name__}'.")
                logger.warning(msg.format(name=confval.name,
                                          current=type(confval.value),
                                          default=type(default)))

def assign_figure_numbers(self, env: BuildEnvironment) -> List[str]:
    """Assign a figure number to each figure under a numbered toctree."""

    rewrite_needed = []

    assigned = set()  # type: Set[str]
    old_fignumbers = env.toc_fignumbers
    env.toc_fignumbers = {}
    fignum_counter = {}  # type: Dict[str, Dict[Tuple[int, ...], int]]

    def get_figtype(node: Node) -> str:
        for domain in env.domains.values():
            figtype = domain.get_enumerable_node_type(node)
            if figtype:
                return figtype

        return None

    def get_section_number(docname: str, section: nodes.section) -> Tuple[int, ...]:
        anchorname = '#' + section['ids'][0]
        secnumbers = env.toc_secnumbers.get(docname, {})
        if anchorname in secnumbers:
            secnum = secnumbers.get(anchorname)
        else:
            secnum = secnumbers.get('')

        return secnum or tuple()

    def get_next_fignumber(figtype: str, secnum: Tuple[int, ...]) -> Tuple[int, ...]:
        counter = fignum_counter.setdefault(figtype, {})

        secnum = secnum[:env.config.numfig_secnum_depth]
        counter[secnum] = counter.get(secnum, 0) + 1
        return secnum + (counter[secnum],)

    def register_fignumber(docname: str, secnum: Tuple[int, ...],
                           figtype: str, fignode: Element) -> None:
        env.toc_fignumbers.setdefault(docname, {})
        fignumbers = env.toc_fignumbers[docname].setdefault(figtype, {})
        figure_id = fignode['ids'][0]

        fignumbers[figure_id] = get_next_fignumber(figtype, secnum)

    def _walk_doctree(docname: str, doctree: Element, secnum: Tuple[int, ...]) -> None:
        for subnode in doctree.children:
            if isinstance(subnode, nodes.section):
                next_secnum = get_section_number(docname, subnode)
                if next_secnum:
                    _walk_doctree(docname, subnode, next_secnum)
                else:
                    _walk_doctree(docname, subnode, secnum)
            elif isinstance(subnode, addnodes.toctree):
                for title, subdocname in subnode['entries']:
                    if url_re.match(subdocname) or subdocname == 'self':
                        # don't mess with those
                        continue

                    _walk_doc(subdocname, secnum)
            elif isinstance(subnode, nodes.Element):
                figtype = get_figtype(subnode)
                if figtype and subnode['ids']:
                    register_fignumber(docname, secnum, figtype, subnode)

                _walk_doctree(docname, subnode, secnum)

    def _walk_doc(docname: str, secnum: Tuple[int, ...]) -> None:
        if docname not in assigned:
            assigned.add(docname)
            doctree = env.get_doctree(docname)
            _walk_doctree(docname, doctree, secnum)

    if env.config.numfig:
        _walk_doc(env.config.master_doc, tuple())
        for docname, fignums in env.toc_fignumbers.items():
            if fignums != old_fignumbers.get(docname):
                rewrite_needed.append(docname)

    return rewrite_needed

def category(self) -> str:  # type: ignore
    if self.modname:
        return 'Extension error (%s)' % self.modname
    else:
        return 'Extension error'

def shall_skip(module: str, opts: Any, excludes: List[str] = []) -> bool:
    """Check if we want to skip this module."""
    warnings.warn('shall_skip() is deprecated.',
                  RemovedInSphinx40Warning, stacklevel=2)
    # skip if the file doesn't exist and not using implicit namespaces
    if not opts.implicit_namespaces and not path.exists(module):
        return True

    # Are we a package (here defined as __init__.py, not the folder in itself)
    if is_initpy(module):
        # Yes, check if we have any non-excluded modules at all here
        all_skipped = True
        basemodule = path.dirname(module)
        for submodule in glob.glob(path.join(basemodule, '*.py')):
            if not is_excluded(path.join(basemodule, submodule), excludes):
                # There's a non-excluded module here, we won't skip
                all_skipped = False
        if all_skipped:
            return True

    # skip if it has a "private" name and this is selected
    filename = path.basename(module)
    if is_initpy(filename) and filename.startswith('_') and not opts.includeprivate:
        return True
    return False

def make_link_role(name: str, base_url: str, caption: str) -> RoleFunction:
    # Check whether we have base_url and caption strings have an '%s' for
    # expansion.  If not, fall back the the old behaviour and use the string as
    # a prefix.
    # Remark: It is an implementation detail that we use Pythons %-formatting.
    # So far we only expose ``%s`` and require quoting of ``%`` using ``%%``.
    def role(typ: str, rawtext: str, text: str, lineno: int,
             inliner: Inliner, options: dict = {}, content: list[str] = [],
             ) -> tuple[list[Node], list[system_message]]:
        text = utils.unescape(text)
        has_explicit_title, title, part = split_explicit_title(text)
        full_url = base_url % part
        if not has_explicit_title:
            if caption is None:
                title = full_url
            else:
                title = caption % part
        pnode = nodes.reference(title, title, internal=False, refuri=full_url)
        return [pnode], []
    return role

def run(self) -> List[Node]:
    node = graphviz()
    node['code'] = '%s %s {\n%s\n}\n' % \
                   (self.name, self.arguments[0], '\n'.join(self.content))
    node['options'] = {'docname': self.env.docname}
    if 'graphviz_dot' in self.options:
        node['options']['graphviz_dot'] = self.options['graphviz_dot']
    if 'alt' in self.options:
        node['alt'] = self.options['alt']
    if 'align' in self.options:
        node['align'] = self.options['align']
    if 'class' in self.options:
        node['classes'] = self.options['class']

    if 'caption' not in self.options:
        self.add_name(node)
        return [node]
    else:
        figure = figure_wrapper(self, node, self.options['caption'])
        self.add_name(figure)
        return [figure]

def get_lexer(self, source: str, lang: str, opts: Dict = None,
              force: bool = False, location: Any = None) -> Lexer:
    if not opts:
        opts = {}

    # find out which lexer to use
    if lang in ('py', 'python'):
        if source.startswith('>>>'):
            # interactive session
            lang = 'pycon'
        else:
            lang = 'python'
    elif lang in ('py3', 'python3', 'default'):
        if source.startswith('>>>'):
            lang = 'pycon3'
        else:
            lang = 'python3'

    if lang in lexers:
        # just return custom lexers here (without installing raiseonerror filter)
        return lexers[lang]
    elif lang in lexer_classes:
        lexer = lexer_classes[lang](**opts)
    else:
        try:
            if lang == 'guess':
                lexer = guess_lexer(source, **opts)
            else:
                lexer = get_lexer_by_name(lang, **opts)
        except ClassNotFound:
            logger.warning(__('Pygments lexer name %r is not known'), lang,
                           location=location)
            lexer = lexer_classes['none'](**opts)

    if not force:
        lexer.add_filter('raiseonerror')

    return lexer

def visit_arg(self, node: ast.arg) -> str:
    if node.annotation:
        return "%s: %s" % (node.arg, self.visit(node.annotation))
    else:
        return node.arg

def visit_Tuple(self, node: ast.Tuple) -> str:
    if len(node.elts) == 0:
        return "()"
    elif len(node.elts) == 1:
        return "(%s,)" % self.visit(node.elts[0])
    else:
        return "(" + ", ".join(self.visit(e) for e in node.elts) + ")"

def get_lvar_names(node: ast.AST, self: ast.arg = None) -> List[str]:
    """Convert assignment-AST to variable names.

    This raises `TypeError` if the assignment does not create new variable::

        ary[0] = 'foo'
        dic["bar"] = 'baz'
        # => TypeError
    """
    if self:
        self_id = self.arg

    node_name = node.__class__.__name__
    if node_name in ('Index', 'Num', 'Slice', 'Str', 'Subscript'):
        raise TypeError('%r does not create new variable' % node)
    elif node_name == 'Name':
        if self is None or node.id == self_id:  # type: ignore
            return [node.id]  # type: ignore
        else:
            raise TypeError('The assignment %r is not instance variable' % node)
    elif node_name in ('Tuple', 'List'):
        members = []
        for elt in node.elts:  # type: ignore
            try:
                members.extend(get_lvar_names(elt, self))
            except TypeError:
                pass
        return members
    elif node_name == 'Attribute':
        if node.value.__class__.__name__ == 'Name' and self and node.value.id == self_id:  # type: ignore  # NOQA
            # instance variable
            return ["%s" % get_lvar_names(node.attr, self)[0]]  # type: ignore
        else:
            raise TypeError('The assignment %r is not instance variable' % node)
    elif node_name == 'str':
        return [node]  # type: ignore
    elif node_name == 'Starred':
        return get_lvar_names(node.value, self)  # type: ignore
    else:
        raise NotImplementedError('Unexpected node name %r' % node_name)

def __eq__(self, other: Any) -> bool:
    if isinstance(other, int):
        return self.kind == other
    elif isinstance(other, str):
        return self.value == other
    elif isinstance(other, (list, tuple)):
        return [self.kind, self.value] == list(other)
    elif other is None:
        return False
    else:
        raise ValueError('Unknown value: %r' % other)

def run(self) -> Tuple[List[Node], List[system_message]]:
    if ':' not in self.name:
        self.refdomain, self.reftype = '', self.name
        self.classes = ['xref', self.reftype]
    else:
        self.refdomain, self.reftype = self.name.split(':', 1)
        self.classes = ['xref', self.refdomain, '%s-%s' % (self.refdomain, self.reftype)]

    if self.disabled:
        return self.create_non_xref_node()
    else:
        return self.create_xref_node()

def build_uri(self) -> str:
    base_url = self.inliner.document.settings.pep_base_url
    ret = self.target.split('#', 1)
    if len(ret) == 2:
        return base_url + 'pep-%04d#%s' % (int(ret[0]), ret[1])
    else:
        return base_url + 'pep-%04d' % int(ret[0])

def freeze(self) -> dict[str, Any]:
    """Create a usable data structure for serializing."""
    docnames, titles = zip(*sorted(self._titles.items()))
    filenames = [self._filenames.get(docname) for docname in docnames]
    fn2index = {f: i for (i, f) in enumerate(docnames)}
    terms, title_terms = self.get_terms(fn2index)

    objects = self.get_objects(fn2index)  # populates _objtypes
    objtypes = {v: k[0] + ':' + k[1] for (k, v) in self._objtypes.items()}
    objnames = self._objnames

    alltitles: dict[str, list[tuple[int, str]]] = {}
    for docname, titlelist in self._all_titles.items():
        for title, titleid in titlelist:
            alltitles.setdefault(title, []).append((fn2index[docname], titleid))

    index_entries: dict[str, list[tuple[int, str]]] = {}
    for docname, entries in self._index_entries.items():
        for entry, entry_id, main_entry in entries:
            index_entries.setdefault(entry.lower(), []).append((fn2index[docname], entry_id))

    return dict(docnames=docnames, filenames=filenames, titles=titles, terms=terms,
                objects=objects, objtypes=objtypes, objnames=objnames,
                titleterms=title_terms, envversion=self.env.version,
                alltitles=alltitles, indexentries=index_entries)

def _ensure_stringlike(self, option, what, default=None):
    # type: (str, str, Any) -> Any
    val = getattr(self, option)
    if val is None:
        setattr(self, option, default)
        return default
    elif not isinstance(val, str):
        raise DistutilsOptionError("'%s' must be a %s (got `%s`)"
                                   % (option, what, val))
    return val

def run(self):
    # type: () -> None
    if not color_terminal():
        nocolor()
    if not self.verbose:  # type: ignore
        status_stream = StringIO()
    else:
        status_stream = sys.stdout  # type: ignore
    confoverrides = {}  # type: Dict[str, Any]
    if self.project:
        confoverrides['project'] = self.project
    if self.version:
        confoverrides['version'] = self.version
    if self.release:
        confoverrides['release'] = self.release
    if self.today:
        confoverrides['today'] = self.today
    if self.copyright:
        confoverrides['copyright'] = self.copyright
    if self.nitpicky:
        confoverrides['nitpicky'] = self.nitpicky

    for builder, builder_target_dir in self.builder_target_dirs:
        app = None

        try:
            confdir = self.config_dir or self.source_dir
            with patch_docutils(confdir), docutils_namespace():
                app = Sphinx(self.source_dir, self.config_dir,
                             builder_target_dir, self.doctree_dir,
                             builder, confoverrides, status_stream,
                             freshenv=self.fresh_env,
                             warningiserror=self.warning_is_error,
                             keep_going=self.keep_going)
                app.build(force_all=self.all_files)
                if app.statuscode:
                    raise DistutilsExecError(
                        'caused by %s builder.' % app.builder.name)
        except Exception as exc:
            handle_exception(app, self, exc, sys.stderr)
            if not self.pdb:
                raise SystemExit(1)

        if not self.link_index:
            continue

        src = app.config.master_doc + app.builder.out_suffix  # type: ignore
        dst = app.builder.get_outfilename('index')  # type: ignore
        os.symlink(src, dst)

def assert_re_search(regex: Pattern, text: str, flags: int = 0) -> None:
    if not re.search(regex, text, flags):
        assert False, '%r did not match %r' % (regex, text)

def assert_not_re_search(regex: Pattern, text: str, flags: int = 0) -> None:
    if re.search(regex, text, flags):
        assert False, '%r did match %r' % (regex, text)

def assert_startswith(thing: str, prefix: str) -> None:
    if not thing.startswith(prefix):
        assert False, '%r does not start with %r' % (thing, prefix)

def get_options(self, overrides: Dict[str, Any] = {}) -> Dict[str, Any]:
    """Return a dictionary of theme options and their values."""
    if self.base:
        options = self.base.get_options()
    else:
        options = {}

    try:
        options.update(self.config.items('options'))
    except configparser.NoSectionError:
        pass

    for option, value in overrides.items():
        if option not in options:
            logger.warning(__('unsupported theme option %r given') % option)
        else:
            options[option] = value

    return options

def parselinenos(spec: str, total: int) -> List[int]:
    """Parse a line number spec (such as "1,2,4-6") and return a list of
    wanted line numbers.
    """
    items = list()
    parts = spec.split(',')
    for part in parts:
        try:
            begend = part.strip().split('-')
            if ['', ''] == begend:
                raise ValueError
            elif len(begend) == 1:
                items.append(int(begend[0]) - 1)
            elif len(begend) == 2:
                start = int(begend[0] or 1)  # left half open (cf. -10)
                end = int(begend[1] or max(start, total))  # right half open (cf. 10-)
                if start > end:  # invalid range (cf. 10-1)
                    raise ValueError
                items.extend(range(start - 1, end))
            else:
                raise ValueError
        except Exception:
            raise ValueError('invalid line number spec: %r' % spec)

    return items

def split_index_msg(type: str, value: str) -> List[str]:
    # new entry types must be listed in directives/other.py!
    if type == 'single':
        try:
            result = split_into(2, 'single', value)
        except ValueError:
            result = split_into(1, 'single', value)
    elif type == 'pair':
        result = split_into(2, 'pair', value)
    elif type == 'triple':
        result = split_into(3, 'triple', value)
    elif type == 'see':
        result = split_into(2, 'see', value)
    elif type == 'seealso':
        result = split_into(2, 'see', value)
    else:
        raise ValueError('invalid %s index entry %r' % (type, value))

    return result

def import_object(objname: str, source: str = None) -> Any:
    """Import python object by qualname."""
    try:
        objpath = objname.split('.')
        modname = objpath.pop(0)
        obj = import_module(modname)
        for name in objpath:
            modname += '.' + name
            try:
                obj = getattr(obj, name)
            except AttributeError:
                obj = import_module(modname)

        return obj
    except (AttributeError, ImportError) as exc:
        if source:
            raise ExtensionError('Could not import %s (needed for %s)' %
                                 (objname, source), exc)
        else:
            raise ExtensionError('Could not import %s' % objname, exc)

def _parse_balanced_token_seq(self, end: List[str]) -> str:
    # TODO: add handling of string literals and similar
    brackets = {'(': ')', '[': ']', '{': '}'}
    startPos = self.pos
    symbols = []  # type: List[str]
    while not self.eof:
        if len(symbols) == 0 and self.current_char in end:
            break
        if self.current_char in brackets.keys():
            symbols.append(brackets[self.current_char])
        elif len(symbols) > 0 and self.current_char == symbols[-1]:
            symbols.pop()
        elif self.current_char in ")]}":
            self.fail("Unexpected '%s' in balanced-token-seq." % self.current_char)
        self.pos += 1
    if self.eof:
        self.fail("Could not find end of balanced-token-seq starting at %d."
                  % startPos)
    return self.definition[startPos:self.pos]

def _is_single_paragraph(node: nodes.field_body) -> bool:
    """True if the node only contains one paragraph (and system messages)."""
    if len(node) == 0:
        return False
    elif len(node) > 1:
        for subnode in node[1:]:  # type: nodes.Node
            if not isinstance(subnode, nodes.system_message):
                return False
    if isinstance(node[0], nodes.paragraph):
        return True
    return False

def get_image_filename_for_language(filename: str, env: "BuildEnvironment") -> str:
    if not env.config.language:
        return filename

    filename_format = env.config.figure_language_filename
    d = dict()
    d['root'], d['ext'] = path.splitext(filename)
    dirname = path.dirname(d['root'])
    if dirname and not dirname.endswith(path.sep):
        dirname += path.sep
    d['path'] = dirname
    d['basename'] = path.basename(d['root'])
    d['language'] = env.config.language
    try:
        return filename_format.format(**d)
    except KeyError as exc:
        raise SphinxError('Invalid figure_language_filename: %r' % exc)

def isclassmethod(obj: Any) -> bool:
    """Check if the object is classmethod."""
    if isinstance(obj, classmethod):
        return True
    elif inspect.ismethod(obj) and obj.__self__ is not None and isclass(obj.__self__):
        return True

    return False

def isstaticmethod(obj: Any, cls: Any = None, name: str = None) -> bool:
    """Check if the object is staticmethod."""
    if isinstance(obj, staticmethod):
        return True
    elif cls and name:
        # trace __mro__ if the method is defined in parent class
        #
        # .. note:: This only works well with new style classes.
        for basecls in getattr(cls, '__mro__', [cls]):
            meth = basecls.__dict__.get(name)
            if meth:
                if isinstance(meth, staticmethod):
                    return True
                else:
                    return False

    return False

def stringify_signature(sig: inspect.Signature, show_annotation: bool = True,
                        show_return_annotation: bool = True) -> str:
    """Stringify a Signature object.

    :param show_annotation: Show annotation in result
    """
    args = []
    last_kind = None
    for param in sig.parameters.values():
        if param.kind != param.POSITIONAL_ONLY and last_kind == param.POSITIONAL_ONLY:
            # PEP-570: Separator for Positional Only Parameter: /
            args.append('/')
        if param.kind == param.KEYWORD_ONLY and last_kind in (param.POSITIONAL_OR_KEYWORD,
                                                              param.POSITIONAL_ONLY,
                                                              None):
            # PEP-3102: Separator for Keyword Only Parameter: *
            args.append('*')

        arg = StringIO()
        if param.kind == param.VAR_POSITIONAL:
            arg.write('*' + param.name)
        elif param.kind == param.VAR_KEYWORD:
            arg.write('**' + param.name)
        else:
            arg.write(param.name)

        if show_annotation and param.annotation is not param.empty:
            arg.write(': ')
            arg.write(stringify_annotation(param.annotation))
        if param.default is not param.empty:
            if show_annotation and param.annotation is not param.empty:
                arg.write(' = ')
            else:
                arg.write('=')
            arg.write(object_description(param.default))

        args.append(arg.getvalue())
        last_kind = param.kind

    if last_kind == Parameter.POSITIONAL_ONLY:
        # PEP-570: Separator for Positional Only Parameter: /
        args.append('/')

    if (sig.return_annotation is Parameter.empty or
            show_annotation is False or
            show_return_annotation is False):
        return '(%s)' % ', '.join(args)
    else:
        annotation = stringify_annotation(sig.return_annotation)
        return '(%s) -> %s' % (', '.join(args), annotation)

def format_args(self, show_annotation: bool = True) -> str:
    def get_annotation(param: Parameter) -> Any:
        if isinstance(param.annotation, str) and param.name in self.annotations:
            return self.annotations[param.name]
        else:
            return param.annotation

    args = []
    last_kind = None
    for i, param in enumerate(self.parameters.values()):
        # skip first argument if subject is bound method
        if self.skip_first_argument and i == 0:
            continue

        arg = StringIO()

        # insert '*' between POSITIONAL args and KEYWORD_ONLY args::
        #     func(a, b, *, c, d):
        if param.kind == param.KEYWORD_ONLY and last_kind in (param.POSITIONAL_OR_KEYWORD,
                                                              param.POSITIONAL_ONLY,
                                                              None):
            args.append('*')

        if param.kind in (param.POSITIONAL_ONLY,
                          param.POSITIONAL_OR_KEYWORD,
                          param.KEYWORD_ONLY):
            arg.write(param.name)
            if show_annotation and param.annotation is not param.empty:
                arg.write(': ')
                arg.write(stringify_annotation(get_annotation(param)))
            if param.default is not param.empty:
                if param.annotation is param.empty or show_annotation is False:
                    arg.write('=')
                    arg.write(object_description(param.default))
                else:
                    arg.write(' = ')
                    arg.write(object_description(param.default))
        elif param.kind == param.VAR_POSITIONAL:
            arg.write('*')
            arg.write(param.name)
            if show_annotation and param.annotation is not param.empty:
                arg.write(': ')
                arg.write(stringify_annotation(get_annotation(param)))
        elif param.kind == param.VAR_KEYWORD:
            arg.write('**')
            arg.write(param.name)
            if show_annotation and param.annotation is not param.empty:
                arg.write(': ')
                arg.write(stringify_annotation(get_annotation(param)))

        args.append(arg.getvalue())
        last_kind = param.kind

    if self.return_annotation is Parameter.empty or show_annotation is False:
        return '(%s)' % ', '.join(args)
    else:
        if 'return' in self.annotations:
            annotation = stringify_annotation(self.annotations['return'])
        else:
            annotation = stringify_annotation(self.return_annotation)

        return '(%s) -> %s' % (', '.join(args), annotation)

def load(cls, stream: IO, uri: str, joinfunc: Callable) -> Inventory:
    reader = InventoryFileReader(stream)
    line = reader.readline().rstrip()
    if line == '# Sphinx inventory version 1':
        return cls.load_v1(reader, uri, joinfunc)
    elif line == '# Sphinx inventory version 2':
        return cls.load_v2(reader, uri, joinfunc)
    else:
        raise ValueError('invalid inventory header: %s' % line)

def encode_string(s: str) -> str:
    def replace(match: Match) -> str:
        s = match.group(0)
        try:
            return ESCAPE_DICT[s]
        except KeyError:
            n = ord(s)
            if n < 0x10000:
                return '\\u%04x' % (n,)
            else:
                # surrogate pair
                n -= 0x10000
                s1 = 0xd800 | ((n >> 10) & 0x3ff)
                s2 = 0xdc00 | (n & 0x3ff)
                return '\\u%04x\\u%04x' % (s1, s2)
    return '"' + str(ESCAPE_ASCII.sub(replace, s)) + '"'

def dumps(obj: Any, key: bool = False) -> str:
    if key:
        if not isinstance(obj, str):
            obj = str(obj)
        if _nameonly_re.match(obj) and obj not in reswords:
            return obj  # return it as a bare word
        else:
            return encode_string(obj)
    if obj is None:
        return 'null'
    elif obj is True or obj is False:
        return 'true' if obj else 'false'
    elif isinstance(obj, (int, float)):
        return str(obj)
    elif isinstance(obj, dict):
        return '{%s}' % ','.join(sorted('%s:%s' % (
            dumps(key, True),
            dumps(value)
        ) for key, value in obj.items()))
    elif isinstance(obj, set):
        return '[%s]' % ','.join(sorted(dumps(x) for x in obj))
    elif isinstance(obj, (tuple, list)):
        return '[%s]' % ','.join(dumps(x) for x in obj)
    elif isinstance(obj, str):
        return encode_string(obj)
    raise TypeError(type(obj))

def filter(self, record: logging.LogRecord) -> bool:
    if record.levelno < logging.WARNING:
        return True
    else:
        return False

def get_node_location(node: Node) -> str:
    (source, line) = get_source_line(node)
    if source and line:
        return "%s:%s" % (source, line)
    elif source:
        return "%s:" % source
    elif line:
        return "<unknown>:%s" % line
    else:
        return None

def get_node_equation_number(writer: HTMLTranslator, node: nodes.math_block) -> str:
    if writer.builder.config.math_numfig and writer.builder.config.numfig:
        figtype = 'displaymath'
        if writer.builder.name == 'singlehtml':
            key = "%s/%s" % (writer.docnames[-1], figtype)
        else:
            key = figtype

        id = node['ids'][0]
        number = writer.builder.fignumbers.get(key, {}).get(id, ())
        return '.'.join(map(str, number))
    else:
        return node['number']

def is_pending_meta(node: Node) -> bool:
    if (isinstance(node, nodes.pending) and
       isinstance(node.details.get('nodes', [None])[0], addnodes.meta)):
        return True
    else:
        return False

def extract_messages(doctree: Element) -> Iterable[tuple[Element, str]]:
    """Extract translatable messages from a document tree."""
    for node in doctree.findall(is_translatable):  # type: Element
        if isinstance(node, addnodes.translatable):
            for msg in node.extract_original_messages():
                yield node, msg
            continue
        if isinstance(node, LITERAL_TYPE_NODES):
            msg = node.rawsource
            if not msg:
                msg = node.astext()
        elif isinstance(node, nodes.image):
            if node.get('alt'):
                yield node, node['alt']
            if node.get('translatable'):
                msg = '.. image:: %s' % node['uri']
            else:
                msg = ''
        elif isinstance(node, nodes.meta):  # type: ignore
            msg = node["content"]
        else:
            msg = node.rawsource.replace('\n', ' ').strip()

        # XXX nodes rendering empty are likely a bug in sphinx.addnodes
        if msg:
            yield node, msg

def is_smartquotable(node: Node) -> bool:
    """Check the node is smart-quotable or not."""
    if isinstance(node.parent, NON_SMARTQUOTABLE_PARENT_NODES):
        return False
    elif node.parent.get('support_smartquotes', None) is False:
        return False
    elif getattr(node, 'support_smartquotes', None) is False:
        return False
    else:
        return True

def mtimes_of_files(dirnames: List[str], suffix: str) -> Iterator[float]:
    for dirname in dirnames:
        for root, dirs, files in os.walk(dirname):
            for sfile in files:
                if sfile.endswith(suffix):
                    try:
                        yield path.getmtime(path.join(root, sfile))
                    except OSError:
                        pass

def abspath(pathdir: str) -> str:
    if Path is not None and isinstance(pathdir, Path):
        return pathdir.abspath()
    else:
        pathdir = path.abspath(pathdir)
        if isinstance(pathdir, bytes):
            try:
                pathdir = pathdir.decode(fs_encoding)
            except UnicodeDecodeError:
                raise UnicodeDecodeError('multibyte filename not supported on '
                                         'this filesystem encoding '
                                         '(%r)' % fs_encoding)
        return pathdir

def is_ssl_error(exc: Exception) -> bool:
    """Check an exception is SSLError."""
    if isinstance(exc, SSLError):
        return True
    else:
        args = getattr(exc, 'args', [])
        if args and isinstance(args[0], SSLError):
            return True
        else:
            return False

def _get_user_agent(config: Config) -> str:
    if config.user_agent:
        return config.user_agent
    else:
        return ' '.join([
            'Sphinx/%s' % sphinx.__version__,
            'requests/%s' % requests.__version__,
            'python/%s' % '.'.join(map(str, sys.version_info[:3])),
        ])

def _stringify_py37(annotation: Any) -> str:
    """stringify() for py37+."""
    module = getattr(annotation, '__module__', None)
    if module == 'typing':
        if getattr(annotation, '_name', None):
            qualname = annotation._name
        elif getattr(annotation, '__qualname__', None):
            qualname = annotation.__qualname__
        elif getattr(annotation, '__forward_arg__', None):
            qualname = annotation.__forward_arg__
        else:
            qualname = stringify(annotation.__origin__)  # ex. Union
    elif hasattr(annotation, '__qualname__'):
        qualname = '%s.%s' % (module, annotation.__qualname__)
    elif hasattr(annotation, '__origin__'):
        # instantiated generic provided by a user
        qualname = stringify(annotation.__origin__)
    else:
        # we weren't able to extract the base type, appending arguments would
        # only make them appear twice
        return repr(annotation)

    if getattr(annotation, '__args__', None):
        if qualname == 'Union':
            if len(annotation.__args__) > 1 and annotation.__args__[-1] is NoneType:  # type: ignore  # NOQA
                if len(annotation.__args__) > 2:
                    args = ', '.join(stringify(a) for a in annotation.__args__[:-1])
                    return 'Optional[Union[%s]]' % args
                else:
                    return 'Optional[%s]' % stringify(annotation.__args__[0])
            else:
                args = ', '.join(stringify(a) for a in annotation.__args__)
                return 'Union[%s]' % args
        elif qualname == 'Callable':
            args = ', '.join(stringify(a) for a in annotation.__args__[:-1])
            returns = stringify(annotation.__args__[-1])
            return '%s[[%s], %s]' % (qualname, args, returns)
        elif str(annotation).startswith('typing.Annotated'):  # for py39+
            return stringify(annotation.__args__[0])
        elif all(is_system_TypeVar(a) for a in annotation.__args__):
            # Suppress arguments if all system defined TypeVars (ex. Dict[KT, VT])
            return qualname
        else:
            args = ', '.join(stringify(a) for a in annotation.__args__)
            return '%s[%s]' % (qualname, args)

    return qualname

def Pow(expr, assumptions):
    """
    Rational ** Integer      -> Rational
    Irrational ** Rational   -> Irrational
    Rational ** Irrational   -> ?
    """
    if ask(Q.integer(expr.exp), assumptions):
        return ask(Q.rational(expr.base), assumptions)
    elif ask(Q.rational(expr.exp), assumptions):
        if ask(Q.prime(expr.base), assumptions):
            return False

def Pow(expr, assumptions):
    """
    Real**Integer              -> Real
    Positive**Real             -> Real
    Real**(Integer/Even)       -> Real if base is nonnegative
    Real**(Integer/Odd)        -> Real
    Imaginary**(Integer/Even)  -> Real
    Imaginary**(Integer/Odd)   -> not Real
    Imaginary**Real            -> ? since Real could be 0 (giving real) or 1 (giving imaginary)
    b**Imaginary               -> Real if log(b) is imaginary and b != 0 and exponent != integer multiple of I*pi/log(b)
    Real**Real                 -> ? e.g. sqrt(-1) is imaginary and sqrt(2) is not
    """
    if expr.is_number:
        return AskRealHandler._number(expr, assumptions)

    if expr.base.func == exp:
        if ask(Q.imaginary(expr.base.args[0]), assumptions):
            if ask(Q.imaginary(expr.exp), assumptions):
                return True
        # If the i = (exp's arg)/(I*pi) is an integer or half-integer
        # multiple of I*pi then 2*i will be an integer. In addition,
        # exp(i*I*pi) = (-1)**i so the overall realness of the expr
        # can be determined by replacing exp(i*I*pi) with (-1)**i.
        i = expr.base.args[0]/I/pi
        if ask(Q.integer(2*i), assumptions):
            return ask(Q.real(((-1)**i)**expr.exp), assumptions)
        return

    if ask(Q.imaginary(expr.base), assumptions):
        if ask(Q.integer(expr.exp), assumptions):
            odd = ask(Q.odd(expr.exp), assumptions)
            if odd is not None:
                return not odd
            return

    if ask(Q.imaginary(expr.exp), assumptions):
        imlog = ask(Q.imaginary(log(expr.base)), assumptions)
        if imlog is not None:
            # I**i -> real, log(I) is imag;
            # (2*I)**i -> complex, log(2*I) is not imag
            return imlog

    if ask(Q.real(expr.base), assumptions):
        if ask(Q.real(expr.exp), assumptions):
            if expr.exp.is_Rational and \
                    ask(Q.even(expr.exp.q), assumptions):
                return ask(Q.positive(expr.base), assumptions)
            elif ask(Q.integer(expr.exp), assumptions):
                return True
            elif ask(Q.positive(expr.base), assumptions):
                return True
            elif ask(Q.negative(expr.base), assumptions):
                return False

def Pow(expr, assumptions):
    """
    Imaginary**Odd        -> Imaginary
    Imaginary**Even       -> Real
    b**Imaginary          -> !Imaginary if exponent is an integer multiple of I*pi/log(b)
    Imaginary**Real       -> ?
    Positive**Real        -> Real
    Negative**Integer     -> Real
    Negative**(Integer/2) -> Imaginary
    Negative**Real        -> not Imaginary if exponent is not Rational
    """
    if expr.is_number:
        return AskImaginaryHandler._number(expr, assumptions)

    if expr.base.func == exp:
        if ask(Q.imaginary(expr.base.args[0]), assumptions):
            if ask(Q.imaginary(expr.exp), assumptions):
                return False
            i = expr.base.args[0]/I/pi
            if ask(Q.integer(2*i), assumptions):
                return ask(Q.imaginary(((-1)**i)**expr.exp), assumptions)

    if ask(Q.imaginary(expr.base), assumptions):
        if ask(Q.integer(expr.exp), assumptions):
            odd = ask(Q.odd(expr.exp), assumptions)
            if odd is not None:
                return odd
            return

    if ask(Q.imaginary(expr.exp), assumptions):
        imlog = ask(Q.imaginary(log(expr.base)), assumptions)
        if imlog is not None:
            return False  # I**i -> real; (2*I)**i -> complex ==> not imaginary

    if ask(Q.real(expr.base) & Q.real(expr.exp), assumptions):
        if ask(Q.positive(expr.base), assumptions):
            return False
        else:
            rat = ask(Q.rational(expr.exp), assumptions)
            if not rat:
                return rat
            if ask(Q.integer(expr.exp), assumptions):
                return False
            else:
                half = ask(Q.integer(2*expr.exp), assumptions)
                if half:
                    return ask(Q.negative(expr.base), assumptions)
                return half

def __pow__(self, other):
    from sympy.functions.elementary.miscellaneous import real_root
    if isinstance(other, Expr):
        if other is S.Infinity:
            if self.min.is_nonnegative:
                if self.max < 1:
                    return S.Zero
                if self.min > 1:
                    return S.Infinity
                return AccumBounds(0, oo)
            elif self.max.is_negative:
                if self.min > -1:
                    return S.Zero
                if self.max < -1:
                    return FiniteSet(-oo, oo)
                return AccumBounds(-oo, oo)
            else:
                if self.min > -1:
                    if self.max < 1:
                        return S.Zero
                    return AccumBounds(0, oo)
                return AccumBounds(-oo, oo)

        if other is S.NegativeInfinity:
            return (1 / self)**oo

        if other.is_real and other.is_number:
            if other.is_zero:
                return S.One

            if other.is_Integer:
                if self.min.is_positive:
                    return AccumBounds(
                        Min(self.min ** other, self.max ** other),
                        Max(self.min ** other, self.max ** other))
                elif self.max.is_negative:
                    return AccumBounds(
                        Min(self.max ** other, self.min ** other),
                        Max(self.max ** other, self.min ** other))

                if other % 2 == 0:
                    if other.is_negative:
                        if self.min.is_zero:
                            return AccumBounds(self.max**other, oo)
                        if self.max.is_zero:
                            return AccumBounds(self.min**other, oo)
                        return AccumBounds(0, oo)
                    return AccumBounds(
                        S.Zero, Max(self.min**other, self.max**other))
                else:
                    if other.is_negative:
                        if self.min.is_zero:
                            return AccumBounds(self.max**other, oo)
                        if self.max.is_zero:
                            return AccumBounds(-oo, self.min**other)
                        return AccumBounds(-oo, oo)
                    return AccumBounds(self.min**other, self.max**other)

            num, den = other.as_numer_denom()
            if num == S(1):
                if den % 2 == 0:
                    if S.Zero in self:
                        if self.min.is_negative:
                            return AccumBounds(0, real_root(self.max, den))
                return AccumBounds(real_root(self.min, den),
                                   real_root(self.max, den))
            num_pow = self**num
            return num_pow**(1 / den)
        return Pow(self, other, evaluate=False)

    return NotImplemented

def __str__(self):
    if self.curving:
        curving_str = "@/%s%d%s/" % (self.curving, self.curving_amount,
                                     self.unit)
    else:
        curving_str = ""

    if self.looping_start and self.looping_end:
        looping_str = "@(%s,%s)" % (self.looping_start, self.looping_end)
    else:
        looping_str = ""

    if self.arrow_style:

        style_str = "@" + self.arrow_style
    else:
        style_str = ""

    return "\\ar%s%s%s[%s%s]%s%s{%s}" % \
           (curving_str, looping_str, style_str, self.horizontal_direction,
            self.vertical_direction, self.label_position,
            self.label_displacement, self.label)

def _remove_multiple_delta(expr):
    """
    Evaluate products of KroneckerDelta's.
    """
    from sympy.solvers import solve
    if expr.is_Add:
        return expr.func(*list(map(_remove_multiple_delta, expr.args)))
    if not expr.is_Mul:
        return expr
    eqs = []
    newargs = []
    for arg in expr.args:
        if isinstance(arg, KroneckerDelta):
            eqs.append(arg.args[0] - arg.args[1])
        else:
            newargs.append(arg)
    if not eqs:
        return expr
    solns = solve(eqs, dict=True)
    if len(solns) == 0:
        return S.Zero
    elif len(solns) == 1:
        for key in solns[0].keys():
            newargs.append(KroneckerDelta(key, solns[0][key]))
        expr2 = expr.func(*newargs)
        if expr != expr2:
            return _remove_multiple_delta(expr2)
    return expr

def doit(self, **hints):
    if hints.get('deep', True):
        f = self.function.doit(**hints)
    else:
        f = self.function

    if self.function.is_Matrix:
        return self.expand().doit()

    for n, limit in enumerate(self.limits):
        i, a, b = limit
        dif = b - a
        if dif.is_integer and (dif < 0) == True:
            a, b = b + 1, a - 1
            f = -f

        newf = eval_sum(f, (i, a, b))
        if newf is None:
            if f == self.function:
                zeta_function = self.eval_zeta_function(f, (i, a, b))
                if zeta_function is not None:
                    return zeta_function
                return self
            else:
                return self.func(f, *self.limits[n:])
        f = newf

    if hints.get('deep', True):
        # eval_sum could return partially unevaluated
        # result with Piecewise.  In this case we won't
        # doit() recursively.
        if not isinstance(f, Piecewise):
            return f.doit(**hints)

    return f

def eval_sum(f, limits):
    from sympy.concrete.delta import deltasummation, _has_simple_delta
    from sympy.functions import KroneckerDelta

    (i, a, b) = limits
    if f is S.Zero:
        return S.Zero
    if i not in f.free_symbols:
        return f*(b - a + 1)
    if a == b:
        return f.subs(i, a)
    if isinstance(f, Piecewise):
        if not any(i in arg.args[1].free_symbols for arg in f.args):
            # Piecewise conditions do not depend on the dummy summation variable,
            # therefore we can fold:     Sum(Piecewise((e, c), ...), limits)
            #                        --> Piecewise((Sum(e, limits), c), ...)
            newargs = []
            for arg in f.args:
                newexpr = eval_sum(arg.expr, limits)
                if newexpr is None:
                    return None
                newargs.append((newexpr, arg.cond))
            return f.func(*newargs)

    if f.has(KroneckerDelta) and _has_simple_delta(f, limits[0]):
        return deltasummation(f, limits)

    dif = b - a
    definite = dif.is_Integer
    # Doing it directly may be faster if there are very few terms.
    if definite and (dif < 100):
        return eval_sum_direct(f, (i, a, b))
    if isinstance(f, Piecewise):
        return None
    # Try to do it symbolically. Even when the number of terms is known,
    # this can save time when b-a is big.
    # We should try to transform to partial fractions
    value = eval_sum_symbolic(f.expand(), (i, a, b))
    if value is not None:
        return value
    # Do it directly
    if definite:
        return eval_sum_direct(f, (i, a, b))

def _make_key(args, kwds, typed,
             kwd_mark = (object(),),
             fasttypes = set((int, str, frozenset, type(None))),
             sorted=sorted, tuple=tuple, type=type, len=len):
    'Make a cache key from optionally typed positional and keyword arguments'
    key = args
    if kwds:
        sorted_items = sorted(kwds.items())
        key += kwd_mark
        for item in sorted_items:
            key += item
    if typed:
        key += tuple(type(v) for v in args)
        if kwds:
            key += tuple(type(v) for k, v in sorted_items)
    elif len(key) == 1 and type(key[0]) in fasttypes:
        return key[0]
    return _HashedSeq(key)

def apply_beta_to_alpha_route(alpha_implications, beta_rules):
    """apply additional beta-rules (And conditions) to already-built
    alpha implication tables

       TODO: write about

       - static extension of alpha-chains
       - attaching refs to beta-nodes to alpha chains


       e.g.

       alpha_implications:

       a  ->  [b, !c, d]
       b  ->  [d]
       ...


       beta_rules:

       &(b,d) -> e


       then we'll extend a's rule to the following

       a  ->  [b, !c, d, e]
    """
    x_impl = {}
    for x in alpha_implications.keys():
        x_impl[x] = (set(alpha_implications[x]), [])
    for bcond, bimpl in beta_rules:
        for bk in bcond.args:
            if bk in x_impl:
                continue
            x_impl[bk] = (set(), [])

    # static extensions to alpha rules:
    # A: x -> a,b   B: &(a,b) -> c  ==>  A: x -> a,b,c
    seen_static_extension = True
    while seen_static_extension:
        seen_static_extension = False

        for bcond, bimpl in beta_rules:
            if not isinstance(bcond, And):
                raise TypeError("Cond is not And")
            bargs = set(bcond.args)
            for x, (ximpls, bb) in x_impl.items():
                x_all = ximpls | {x}
                # A: ... -> a   B: &(...) -> a  is non-informative
                if bimpl not in x_all and bargs.issubset(x_all):
                    ximpls.add(bimpl)

                    # we introduced new implication - now we have to restore
                    # completeness of the whole set.
                    bimpl_impl = x_impl.get(bimpl)
                    if bimpl_impl is not None:
                        ximpls |= bimpl_impl[0]
                    seen_static_extension = True

    # attach beta-nodes which can be possibly triggered by an alpha-chain
    for bidx, (bcond, bimpl) in enumerate(beta_rules):
        bargs = set(bcond.args)
        for x, (ximpls, bb) in x_impl.items():
            x_all = ximpls | {x}
            # A: ... -> a   B: &(...) -> a      (non-informative)
            if bimpl in x_all:
                continue
            # A: x -> a...  B: &(!a,...) -> ... (will never trigger)
            # A: x -> a...  B: &(...) -> !a     (will never trigger)
            if any(Not(xi) in bargs or Not(xi) == bimpl for xi in x_all):
                continue

            if bargs & x_all:
                bb.append(bidx)

    return x_impl

def fdiff(self, argindex=1):
    """
    Returns the first derivative of the function.
    """
    if not (1 <= argindex <= len(self.args)):
        raise ArgumentIndexError(self, argindex)

    if self.args[argindex - 1].is_Symbol:
        for i in range(len(self.args)):
            if i == argindex - 1:
                continue
            # See issue 8510
            if self.args[argindex - 1] in self.args[i].free_symbols:
                break
        else:
            return Derivative(self, self.args[argindex - 1], evaluate=False)
    # See issue 4624 and issue 4719 and issue 5600
    arg_dummy = Dummy('xi_%i' % argindex, dummy_index=hash(self.args[argindex - 1]))
    new_args = [arg for arg in self.args]
    new_args[argindex-1] = arg_dummy
    return Subs(Derivative(self.func(*new_args), arg_dummy),
        arg_dummy, self.args[argindex - 1])

def as_real_imag(self, deep=True, **hints):
    from sympy import Abs, expand_mul, im, re
    other = []
    coeffr = []
    coeffi = []
    addterms = S.One
    for a in self.args:
        r, i = a.as_real_imag()
        if i.is_zero:
            coeffr.append(r)
        elif r.is_zero:
            coeffi.append(i*S.ImaginaryUnit)
        elif a.is_commutative:
            # search for complex conjugate pairs:
            for i, x in enumerate(other):
                if x == a.conjugate():
                    coeffr.append(Abs(x)**2)
                    del other[i]
                    break
            else:
                if a.is_Add:
                    addterms *= a
                else:
                    other.append(a)
        else:
            other.append(a)
    m = self.func(*other)
    if hints.get('ignore') == m:
        return
    if len(coeffi) % 2:
        imco = im(coeffi.pop(0))
        # all other pairs make a real factor; they will be
        # put into reco below
    else:
        imco = S.Zero
    reco = self.func(*(coeffr + coeffi))
    r, i = (reco*re(m), reco*im(m))
    if addterms == 1:
        if m == 1:
            if imco is S.Zero:
                return (reco, S.Zero)
            else:
                return (S.Zero, reco*imco)
        if imco is S.Zero:
            return (r, i)
        return (-imco*i, imco*r)
    addre, addim = expand_mul(addterms, deep=False).as_real_imag()
    if imco is S.Zero:
        return (r*addre - i*addim, i*addre + r*addim)
    else:
        r, i = -imco*i, imco*r
        return (r*addre - i*addim, r*addim + i*addre)

def _eval_real_imag(self, real):
    zero = False
    t_not_re_im = None

    for t in self.args:
        if not t.is_complex:
            return t.is_complex
        elif t.is_imaginary:  # I
            real = not real
        elif t.is_real:  # 2
            if not zero:
                z = t.is_zero
                if not z and zero is False:
                    zero = z
                elif z:
                    if all(a.is_finite for a in self.args):
                        return True
                    return
        elif t.is_real is False:
            # symbolic or literal like `2 + I` or symbolic imaginary
            if t_not_re_im:
                return  # complex terms might cancel
            t_not_re_im = t
        elif t.is_imaginary is False:  # symbolic like `2` or `2 + I`
            if t_not_re_im:
                return  # complex terms might cancel
            t_not_re_im = t
        else:
            return

    if t_not_re_im:
        if t_not_re_im.is_real is False:
            if real:  # like 3
                return zero  # 3*(smthng like 2 + I or i) is not real
        if t_not_re_im.is_imaginary is False:  # symbolic 2 or 2 + I
            if not real:  # like I
                return zero  # I*(smthng like 2 or 2 + I) is not real
    elif zero is False:
        return real  # can't be trumped by 0
    elif real:
        return real  # doesn't matter what zero is

def __new__(cls, p, q=None, gcd=None):
    if q is None:
        if isinstance(p, Rational):
            return p

        if isinstance(p, string_types):
            if p.count('/') > 1:
                raise TypeError('invalid input: %s' % p)
            pq = p.rsplit('/', 1)
            if len(pq) == 2:
                p, q = pq
                fp = fractions.Fraction(p)
                fq = fractions.Fraction(q)
                f = fp/fq
                return Rational(f.numerator, f.denominator, 1)
            p = p.replace(' ', '')
            try:
                p = fractions.Fraction(p)
            except ValueError:
                pass  # error will raise below

        if not isinstance(p, string_types):
            try:
                if isinstance(p, fractions.Fraction):
                    return Rational(p.numerator, p.denominator, 1)
            except NameError:
                pass  # error will raise below

            if isinstance(p, (float, Float)):
                return Rational(*_as_integer_ratio(p))

        if not isinstance(p, SYMPY_INTS + (Rational,)):
            raise TypeError('invalid input: %s' % p)
        q = q or S.One
        gcd = 1
    else:
        p = Rational(p)
        q = Rational(q)

    if isinstance(q, Rational):
        p *= q.q
        q = q.p
    if isinstance(p, Rational):
        q *= p.q
        p = p.p

    # p and q are now integers
    if q == 0:
        if p == 0:
            if _errdict["divide"]:
                raise ValueError("Indeterminate 0/0")
            else:
                return S.NaN
        return S.ComplexInfinity
    if q < 0:
        q = -q
        p = -p
    if not gcd:
        gcd = igcd(abs(p), q)
    if gcd > 1:
        p //= gcd
        q //= gcd
    if q == 1:
        return Integer(p)
    if p == 1 and q == 2:
        return S.Half
    obj = Expr.__new__(cls)
    obj.p = p
    obj.q = q
    return obj

def _eval_is_integer(self):
    b, e = self.args
    if b.is_rational:
        if b.is_integer is False and e.is_positive:
            return False  # rat**nonneg
    if b.is_integer and e.is_integer:
        if b is S.NegativeOne:
            return True
        if e.is_nonnegative or e.is_positive:
            return True
    if b.is_integer and e.is_negative and (e.is_finite or e.is_integer):
        if fuzzy_not((b - 1).is_zero) and fuzzy_not((b + 1).is_zero):
            return False
    if b.is_Number and e.is_Number:
        check = self.func(*self.args)
        return check.is_Integer

def _eval_is_real(self):
    from sympy import arg, exp, log, Mul
    real_b = self.base.is_real
    if real_b is None:
        if self.base.func == exp and self.base.args[0].is_imaginary:
            return self.exp.is_imaginary
        return
    real_e = self.exp.is_real
    if real_e is None:
        return
    if real_b and real_e:
        if self.base.is_positive:
            return True
        elif self.base.is_nonnegative:
            if self.exp.is_nonnegative:
                return True
        else:
            if self.exp.is_integer:
                return True
            elif self.base.is_negative:
                if self.exp.is_Rational:
                    return False
    if real_e and self.exp.is_negative:
        return Pow(self.base, -self.exp).is_real
    im_b = self.base.is_imaginary
    im_e = self.exp.is_imaginary
    if im_b:
        if self.exp.is_integer:
            if self.exp.is_even:
                return True
            elif self.exp.is_odd:
                return False
        elif im_e and log(self.base).is_imaginary:
            return True
        elif self.exp.is_Add:
            c, a = self.exp.as_coeff_Add()
            if c and c.is_Integer:
                return Mul(
                    self.base**c, self.base**a, evaluate=False).is_real
        elif self.base in (-S.ImaginaryUnit, S.ImaginaryUnit):
            if (self.exp/2).is_integer is False:
                return False
    if real_b and im_e:
        if self.base is S.NegativeOne:
            return True
        c = self.exp.coeff(S.ImaginaryUnit)
        if c:
            ok = (c*log(self.base)/S.Pi).is_Integer
            if ok is not None:
                return ok

    if real_b is False:  # we already know it's not imag
        i = arg(self.base)*self.exp/S.Pi
        return i.is_integer

def _eval_is_finite(self):
    if self.exp.is_negative:
        if self.base.is_zero:
            return False
        if self.base.is_infinite:
            return True
    c1 = self.base.is_finite
    if c1 is None:
        return
    c2 = self.exp.is_finite
    if c2 is None:
        return
    if c1 and c2:
        if self.exp.is_nonnegative or fuzzy_not(self.base.is_zero):
            return True

def _eval_is_algebraic(self):
    def _is_one(expr):
        try:
            return (expr - 1).is_zero
        except ValueError:
            # when the operation is not allowed
            return False

    if self.base.is_zero or _is_one(self.base):
        return True
    elif self.exp.is_rational:
        if self.base.is_algebraic is False:
            return self.exp.is_zero
        return self.base.is_algebraic
    elif self.base.is_algebraic and self.exp.is_algebraic:
        if ((fuzzy_not(self.base.is_zero)
            and fuzzy_not(_is_one(self.base)))
            or self.base.is_integer is False
            or self.base.is_irrational):
            return self.exp.is_rational

def _swing(cls, n):
    if n < 33:
        return cls._small_swing[n]
    else:
        N, primes = int(_sqrt(n)), []

        for prime in sieve.primerange(3, N + 1):
            p, q = 1, n

            while True:
                q //= prime

                if q > 0:
                    if q & 1 == 1:
                        p *= prime
                else:
                    break

            if p > 1:
                primes.append(p)

        for prime in sieve.primerange(N + 1, n//3 + 1):
            if (n // prime) & 1 == 1:
                primes.append(prime)

        L_product = R_product = 1

        for prime in sieve.primerange(n//2 + 1, n + 1):
            L_product *= prime

        for prime in primes:
            R_product *= prime

        return L_product*R_product

def eval(cls, n, sym=None):
    if n.is_Number:
        if n.is_Integer and n.is_nonnegative:
            if n is S.Zero:
                return S.One
            elif n is S.One:
                if sym is None:
                    return -S.Half
                else:
                    return sym - S.Half
            # Bernoulli numbers
            elif sym is None:
                if n.is_odd:
                    return S.Zero
                n = int(n)
                # Use mpmath for enormous Bernoulli numbers
                if n > 500:
                    p, q = bernfrac(n)
                    return Rational(int(p), int(q))
                case = n % 6
                highest_cached = cls._highest[case]
                if n <= highest_cached:
                    return cls._cache[n]
                # To avoid excessive recursion when, say, bernoulli(1000) is
                # requested, calculate and cache the entire sequence ... B_988,
                # B_994, B_1000 in increasing order
                for i in range(highest_cached + 6, n + 6, 6):
                    b = cls._calc_bernoulli(i)
                    cls._cache[i] = b
                    cls._highest[case] = i
                return b
            # Bernoulli polynomials
            else:
                n, result = int(n), []
                for k in range(n + 1):
                    result.append(binomial(n, k)*cls(k)*sym**(n - k))
                return Add(*result)
        else:
            raise ValueError("Bernoulli numbers are defined only"
                             " for nonnegative integer indices.")

    if sym is None:
        if n.is_odd and (n - 1).is_positive:
            return S.Zero

def eval(cls, m, sym=None):
    if m.is_Number:
        if m.is_Integer and m.is_nonnegative:
            # Euler numbers
            if sym is None:
                if m.is_odd:
                    return S.Zero
                from mpmath import mp
                m = m._to_mpmath(mp.prec)
                res = mp.eulernum(m, exact=True)
                return Integer(res)
            # Euler polynomial
            else:
                from sympy.core.evalf import pure_complex
                reim = pure_complex(sym, or_real=True)
                # Evaluate polynomial numerically using mpmath
                if reim and all(a.is_Float or a.is_Integer for a in reim) \
                        and any(a.is_Float for a in reim):
                    from mpmath import mp
                    from sympy import Expr
                    m = int(m)
                    # XXX ComplexFloat (#12192) would be nice here, above
                    prec = min([a._prec for a in reim if a.is_Float])
                    with workprec(prec):
                        res = mp.eulerpoly(m, sym)
                    return Expr._from_mpmath(res, prec)
                # Construct polynomial symbolically from definition
                m, result = int(m), []
                for k in range(m + 1):
                    result.append(binomial(m, k)*cls(k)/(2**k)*(sym - S.Half)**(m - k))
                return Add(*result).expand()
        else:
            raise ValueError("Euler numbers are defined only"
                             " for nonnegative integer indices.")
    if sym is None:
        if m.is_odd and m.is_positive:
            return S.Zero

def eval(cls, arg):
    from sympy.simplify.simplify import signsimp
    from sympy.core.function import expand_mul

    if hasattr(arg, '_eval_Abs'):
        obj = arg._eval_Abs()
        if obj is not None:
            return obj
    if not isinstance(arg, Expr):
        raise TypeError("Bad argument type for Abs(): %s" % type(arg))
    # handle what we can
    arg = signsimp(arg, evaluate=False)
    if arg.is_Mul:
        known = []
        unk = []
        for t in arg.args:
            tnew = cls(t)
            if isinstance(tnew, cls):
                unk.append(tnew.args[0])
            else:
                known.append(tnew)
        known = Mul(*known)
        unk = cls(Mul(*unk), evaluate=False) if unk else S.One
        return known*unk
    if arg is S.NaN:
        return S.NaN
    if arg is S.ComplexInfinity:
        return S.Infinity
    if arg.is_Pow:
        base, exponent = arg.as_base_exp()
        if base.is_real:
            if exponent.is_integer:
                if exponent.is_even:
                    return arg
                if base is S.NegativeOne:
                    return S.One
                if isinstance(base, cls) and exponent is S.NegativeOne:
                    return arg
                return Abs(base)**exponent
            if base.is_nonnegative:
                return base**re(exponent)
            if base.is_negative:
                return (-base)**re(exponent)*exp(-S.Pi*im(exponent))
            return
    if isinstance(arg, exp):
        return exp(re(arg.args[0]))
    if isinstance(arg, AppliedUndef):
        return
    if arg.is_Add and arg.has(S.Infinity, S.NegativeInfinity):
        if any(a.is_infinite for a in arg.as_real_imag()):
            return S.Infinity
    if arg.is_zero:
        return S.Zero
    if arg.is_nonnegative:
        return arg
    if arg.is_nonpositive:
        return -arg
    if arg.is_imaginary:
        arg2 = -S.ImaginaryUnit * arg
        if arg2.is_nonnegative:
            return arg2
    # reject result if all new conjugates are just wrappers around
    # an expression that was already in the arg
    conj = arg.conjugate()
    new_conj = conj.atoms(conjugate) - arg.atoms(conjugate)
    if new_conj and all(arg.has(i.args[0]) for i in new_conj):
        return
    if arg != conj and arg != -conj:
        ignore = arg.atoms(Abs)
        abs_free_arg = arg.xreplace({i: Dummy(real=True) for i in ignore})
        unk = [a for a in abs_free_arg.free_symbols if a.is_real is None]
        if not unk or not all(conj.has(conjugate(u)) for u in unk):
            return sqrt(expand_mul(arg*conj))

def _eval_is_algebraic(self):
    s = self.func(*self.args)
    if s.func == self.func:
        if (self.args[0] - 1).is_zero:
            return True
        elif fuzzy_not((self.args[0] - 1).is_zero):
            if self.args[0].is_algebraic:
                return False
    else:
        return s.is_algebraic

def _eval_rewrite_as_ITE(self, *args):
    byfree = {}
    args = list(args)
    default = any(c == True for b, c in args)
    for i, (b, c) in enumerate(args):
        if not isinstance(b, Boolean) and b != True:
            raise TypeError(filldedent('''
                Expecting Boolean or bool but got `%s`
                ''' % func_name(b)))
        if c == True:
            break
        # loop over independent conditions for this b
        for c in c.args if isinstance(c, Or) else [c]:
            free = c.free_symbols
            x = free.pop()
            try:
                byfree[x] = byfree.setdefault(
                    x, S.EmptySet).union(c.as_set())
            except NotImplementedError:
                if not default:
                    raise NotImplementedError(filldedent('''
                        A method to determine whether a multivariate
                        conditional is consistent with a complete coverage
                        of all variables has not been implemented so the
                        rewrite is being stopped after encountering `%s`.
                        This error would not occur if a default expression
                        like `(foo, True)` were given.
                        ''' % c))
            if byfree[x] in (S.UniversalSet, S.Reals):
                # collapse the ith condition to True and break
                args[i] = list(args[i])
                c = args[i][1] = True
                break
        if c == True:
            break
    if c != True:
        raise ValueError(filldedent('''
            Conditions must cover all reals or a final default
            condition `(foo, True)` must be given.
            '''))
    last, _ = args[i]  # ignore all past ith arg
    for a, c in reversed(args[:i]):
        last = ITE(c, a, last)
    return _canonical(last)

def eval(cls, nu, z):
    if z.is_zero:
        if nu.is_zero:
            return S.One
        elif (nu.is_integer and nu.is_zero is False) or re(nu).is_positive:
            return S.Zero
        elif re(nu).is_negative and not (nu.is_integer is True):
            return S.ComplexInfinity
        elif nu.is_imaginary:
            return S.NaN
    if z.is_imaginary:
        if im(z) is S.Infinity or im(z) is S.NegativeInfinity:
            return S.Zero

    if z.could_extract_minus_sign():
        return (z)**nu*(-z)**(-nu)*besseli(nu, -z)
    if nu.is_integer:
        if nu.could_extract_minus_sign():
            return besseli(-nu, z)
        newz = z.extract_multiplicatively(I)
        if newz:  # NOTE we don't want to change the function if z==0
            return I**(-nu)*besselj(nu, -newz)

    # branch handling:
    from sympy import unpolarify, exp
    if nu.is_integer:
        newz = unpolarify(z)
        if newz != z:
            return besseli(nu, newz)
    else:
        newz, n = z.extract_branch_factor()
        if n != 0:
            return exp(2*n*pi*nu*I)*besseli(nu, newz)
    nnu = unpolarify(nu)
    if nu != nnu:
        return besseli(nnu, z)

def eval(cls, nu, z):
    if z.is_zero:
        if nu.is_zero:
            return S.Infinity
        elif re(nu).is_zero is False:
            return S.ComplexInfinity
        elif re(nu).is_zero:
            return S.NaN
    if z.is_imaginary:
        if im(z) is S.Infinity or im(z) is S.NegativeInfinity:
            return S.Zero

    if nu.is_integer:
        if nu.could_extract_minus_sign():
            return besselk(-nu, z)

def are_coplanar(*e):
    """ Returns True if the given entities are coplanar otherwise False

    Parameters
    ==========

    e: entities to be checked for being coplanar

    Returns
    =======

    Boolean

    Examples
    ========

    >>> from sympy import Point3D, Line3D
    >>> from sympy.geometry.util import are_coplanar
    >>> a = Line3D(Point3D(5, 0, 0), Point3D(1, -1, 1))
    >>> b = Line3D(Point3D(0, -2, 0), Point3D(3, 1, 1))
    >>> c = Line3D(Point3D(0, -1, 0), Point3D(5, -1, 9))
    >>> are_coplanar(a, b, c)
    False

    """
    from sympy.geometry.line import LinearEntity3D
    from sympy.geometry.point import Point3D
    from sympy.geometry.plane import Plane
    # XXX update tests for coverage

    e = set(e)
    # first work with a Plane if present
    for i in list(e):
        if isinstance(i, Plane):
            e.remove(i)
            return all(p.is_coplanar(i) for p in e)

    if all(isinstance(i, Point3D) for i in e):
        if len(e) < 3:
            return False

        # remove pts that are collinear with 2 pts
        a, b = e.pop(), e.pop()
        for i in list(e):
            if Point3D.are_collinear(a, b, i):
                e.remove(i)

        if not e:
            return False
        else:
            # define a plane
            p = Plane(a, b, e.pop())
            for i in e:
                if i not in p:
                    return False
            return True
    else:
        pt3d = []
        for i in e:
            if isinstance(i, Point3D):
                pt3d.append(i)
            elif isinstance(i, LinearEntity3D):
                pt3d.extend(i.args)
            elif isinstance(i, GeometryEntity):  # XXX we should have a GeometryEntity3D class so we can tell the difference between 2D and 3D -- here we just want to deal with 2D objects; if new 3D objects are encountered that we didn't hanlde above, an error should be raised
                # all 2D objects have some Point that defines them; so convert those points to 3D pts by making z=0
                for p in i.args:
                    if isinstance(p, Point):
                        pt3d.append(Point3D(*(p.args + (0,))))
        return are_coplanar(*pt3d)

def __mul__(self, other):
    """
    Multiplies two DifferentialOperator and returns another
    DifferentialOperator instance using the commutation rule
    Dx*a = a*Dx + a'
    """

    listofself = self.listofpoly

    if not isinstance(other, DifferentialOperator):
        if not isinstance(other, self.parent.base.dtype):
            listofother = [self.parent.base.from_sympy(sympify(other))]

        else:
            listofother = [other]
    else:
        listofother = other.listofpoly

    # multiplies a polynomial `b` with a list of polynomials
    def _mul_dmp_diffop(b, listofother):
        if isinstance(listofother, list):
            sol = []
            for i in listofother:
                sol.append(i * b)
            return sol
        else:
            return [b * listofother]

    sol = _mul_dmp_diffop(listofself[0], listofother)

    # compute Dx^i * b
    def _mul_Dxi_b(b):
        sol1 = [self.parent.base.zero]
        sol2 = []

        if isinstance(b, list):
            for i in b:
                sol1.append(i)
                sol2.append(i.diff())
        else:
            sol1.append(self.parent.base.from_sympy(b))
            sol2.append(self.parent.base.from_sympy(b).diff())

        return _add_lists(sol1, sol2)

    for i in range(1, len(listofself)):
        # find Dx^i * b in ith iteration
        listofother = _mul_Dxi_b(listofother)
        # solution = solution + listofself[i] * (Dx^i * b)
        sol = _add_lists(sol, _mul_dmp_diffop(listofself[i], listofother))

    return DifferentialOperator(sol, self.parent)

def __rmul__(self, other):
    if not isinstance(other, DifferentialOperator):

        if not isinstance(other, self.parent.base.dtype):
            other = (self.parent.base).from_sympy(sympify(other))

        sol = []
        for j in self.listofpoly:
            sol.append(other * j)

        return DifferentialOperator(sol, self.parent)

def __pow__(self, n):
    if n == 1:
        return self
    if n == 0:
        return DifferentialOperator([self.parent.base.one], self.parent)

    # if self is `Dx`
    if self.listofpoly == self.parent.derivative_operator.listofpoly:
        sol = []
        for i in range(0, n):
            sol.append(self.parent.base.zero)
        sol.append(self.parent.base.one)
        return DifferentialOperator(sol, self.parent)

    # the general case
    else:
        if n % 2 == 1:
            powreduce = self**(n - 1)
            return powreduce * self
        elif n % 2 == 0:
            powreduce = self**(n / 2)
            return powreduce * powreduce

def _singularics_to_ord(self):
    """
    Converts a singular initial condition to ordinary if possible.
    """
    a = list(self.y0)[0]
    b = self.y0[a]

    if len(self.y0) == 1 and a == int(a) and a > 0:
        y0 = []
        a = int(a)
        for i in range(a):
            y0.append(S(0))
        y0 += [j * factorial(a + i) for i, j in enumerate(b)]

        return HolonomicFunction(self.annihilator, self.x, self.x0, y0)

def _evalf(func, points, derivatives=False, method='RK4'):
    """
    Numerical methods for numerical integration along a given set of
    points in the complex plane.
    """

    ann = func.annihilator
    a = ann.order
    R = ann.parent.base
    K = R.get_field()

    if method == 'Euler':
        meth = _euler
    else:
        meth = _rk4

    dmf = []
    for j in ann.listofpoly:
        dmf.append(K.new(j.rep))

    red = [-dmf[i] / dmf[a] for i in range(a)]

    y0 = func.y0
    if len(y0) < a:
        raise TypeError("Not Enough Initial Conditions")
    x0 = func.x0
    sol = [meth(red, x0, points[0], y0, a)]

    for i, j in enumerate(points[1:]):
        sol.append(meth(red, points[i], j, sol[-1], a))

    if not derivatives:
        return [sympify(i[0]) for i in sol]
    else:
        return sympify(sol)

def __mul__(self, other):
    """
    Multiplies two Operators and returns another
    RecurrenceOperator instance using the commutation rule
    Sn * a(n) = a(n + 1) * Sn
    """

    listofself = self.listofpoly
    base = self.parent.base

    if not isinstance(other, RecurrenceOperator):
        if not isinstance(other, self.parent.base.dtype):
            listofother = [self.parent.base.from_sympy(sympify(other))]

        else:
            listofother = [other]
    else:
        listofother = other.listofpoly
    # multiply a polynomial `b` with a list of polynomials

    def _mul_dmp_diffop(b, listofother):
        if isinstance(listofother, list):
            sol = []
            for i in listofother:
                sol.append(i * b)
            return sol
        else:
            return [b * listofother]

    sol = _mul_dmp_diffop(listofself[0], listofother)

    # compute Sn^i * b
    def _mul_Sni_b(b):
        sol = [base.zero]

        if isinstance(b, list):
            for i in b:
                j = base.to_sympy(i).subs(base.gens[0], base.gens[0] + S(1))
                sol.append(base.from_sympy(j))

        else:
            j = b.subs(base.gens[0], base.gens[0] + S(1))
            sol.append(base.from_sympy(j))

        return sol

    for i in range(1, len(listofself)):
        # find Sn^i * b in ith iteration
        listofother = _mul_Sni_b(listofother)
        # solution = solution + listofself[i] * (Sn^i * b)
        sol = _add_lists(sol, _mul_dmp_diffop(listofself[i], listofother))

    return RecurrenceOperator(sol, self.parent)

def __rmul__(self, other):
    if not isinstance(other, RecurrenceOperator):

        if isinstance(other, int):
            other = S(other)

        if not isinstance(other, self.parent.base.dtype):
            other = (self.parent.base).from_sympy(other)

        sol = []
        for j in self.listofpoly:
            sol.append(other * j)

        return RecurrenceOperator(sol, self.parent)

def __pow__(self, n):
    if n == 1:
        return self
    if n == 0:
        return RecurrenceOperator([self.parent.base.one], self.parent)
    # if self is `Sn`
    if self.listofpoly == self.parent.shift_operator.listofpoly:
        sol = []
        for i in range(0, n):
            sol.append(self.parent.base.zero)
        sol.append(self.parent.base.one)

        return RecurrenceOperator(sol, self.parent)

    else:
        if n % 2 == 1:
            powreduce = self**(n - 1)
            return powreduce * self
        elif n % 2 == 0:
            powreduce = self**(n / 2)
            return powreduce * powreduce

def __repr__(self):
    str_sol = 'HolonomicSequence(%s, %s)' % ((self.recurrence).__repr__(), sstr(self.n))
    if not self._have_init_cond:
        return str_sol
    else:
        cond_str = ''
        seq_str = 0
        for i in self.u0:
            cond_str += ', u(%s) = %s' % (sstr(seq_str), sstr(i))
            seq_str += 1

        sol = str_sol + cond_str
        return sol

def contains_dont_know(rule):
    if isinstance(rule, DontKnowRule):
        return True
    else:
        for val in rule:
            if isinstance(val, tuple):
                if contains_dont_know(val):
                    return True
            elif isinstance(val, list):
                if any(contains_dont_know(i) for i in val):
                    return True
    return False

def manual_diff(f, symbol):
    """Derivative of f in form expected by find_substitutions

    SymPy's derivatives for some trig functions (like cot) aren't in a form
    that works well with finding substitutions; this replaces the
    derivatives for those particular forms with something that works better.

    """
    if f.args:
        arg = f.args[0]
        if isinstance(f, sympy.tan):
            return arg.diff(symbol) * sympy.sec(arg)**2
        elif isinstance(f, sympy.cot):
            return -arg.diff(symbol) * sympy.csc(arg)**2
        elif isinstance(f, sympy.sec):
            return arg.diff(symbol) * sympy.sec(arg) * sympy.tan(arg)
        elif isinstance(f, sympy.csc):
            return -arg.diff(symbol) * sympy.csc(arg) * sympy.cot(arg)
        elif isinstance(f, sympy.Add):
            return sum([manual_diff(arg, symbol) for arg in f.args])
        elif isinstance(f, sympy.Mul):
            if len(f.args) == 2 and isinstance(f.args[0], sympy.Number):
                return f.args[0] * manual_diff(f.args[1], symbol)
    return f.diff(symbol)

def FunctionOfTanhQ(u, v, x):
    #(* If u is a function of the form f[Tanh[v],Coth[v]] where f is independent of x,
    # FunctionOfTanhQ[u,v,x] returns True; else it returns False. *)
    if AtomQ(u):
        return u != x
    elif CalculusQ(u):
        return False
    elif HyperbolicQ(u) and IntegerQuotientQ(u.args[0], v):
        return TanhQ(u) or CothQ(u) or EvenQuotientQ(u.args[0], v)
    elif PowerQ(u):
        if EvenQ(u.args[1]) and HyperbolicQ(u.args[0]) and IntegerQuotientQ(u.args[0].args[0], v):
            return True
        elif EvenQ(u.args[1]) and SumQ(u.args[0]):
            return FunctionOfTanhQ(Expand(u.args[0]**2, v, x))
    if ProductQ(u):
        lst = []
        for i in u.args:
            if Not(FunctionOfTanhQ(i, v, x)):
                lst.append(i)
        if lst == []:
            return True
        return Length(lst)==2 and OddHyperbolicPowerQ(lst[0], v, x) and OddHyperbolicPowerQ(lst[1], v, x)
    return all(FunctionOfTanhQ(i, v, x) for i in u.args)

def FunctionOfTanhWeight(u, v, x):
    """
    u is a function of the form f(tanh(v), coth(v)) where f is independent of x.
    FunctionOfTanhWeight(u, v, x) returns a nonnegative number if u is best considered a function of tanh(v), else it returns a negative number.

    Examples
    ========

    >>> from sympy import sinh, log, tanh
    >>> from sympy.abc import x
    >>> from sympy.integrals.rubi.utility_function import FunctionOfTanhWeight
    >>> FunctionOfTanhWeight(x, log(x), x)
    0
    >>> FunctionOfTanhWeight(sinh(log(x)), log(x), x)
    0
    >>> FunctionOfTanhWeight(tanh(log(x)), log(x), x)
    1

    """
    if AtomQ(u):
        return S(0)
    elif CalculusQ(u):
        return S(0)
    elif HyperbolicQ(u) and IntegerQuotientQ(u.args[0], v):
        if TanhQ(u) and ZeroQ(u.args[0] - v):
            return S(1)
        elif CothQ(u) and ZeroQ(u.args[0] - v):
            return S(-1)
        return S(0)
    elif PowerQ(u):
        if EvenQ(u.exp) and HyperbolicQ(u.base) and IntegerQuotientQ(u.base.args[0], v):
            if TanhQ(u.base) or CoshQ(u.base) or SechQ(u.base):
                return S(1)
            return S(-1)
    if ProductQ(u):
        if all(FunctionOfTanhQ(i, v, x) for i in u.args):
            return Add(*[FunctionOfTanhWeight(i, v, x) for i in u.args])
        return S(0)
    return Add(*[FunctionOfTanhWeight(i, v, x) for i in u.args])

def TryTanhSubst(u, x):
    if u.func == log:
        return False
    elif not FalseQ(FunctionOfLinear(u, x)):
        return False

    a_ = Wild('a', exclude=[x])
    m_ = Wild('m', exclude=[x])
    p_ = Wild('p', exclude=[x])
    r_, s_, t_, n_, b_, f_, g_ = map(Wild, 'rstnbfg')

    match = u.match(r_*(s_ + t_)**n_)
    if match:
        if len(match) == 4:
            r, s, t, n = [match[i] for i in [r_, s_, t_, n_]]
            if IntegerQ(n) and PositiveQ(n):
                return False

    match = u.match(1/(a_ + b_*f_**n_))
    if match:
        if len(match) == 4:
            a, b, f, n = [match[i] for i in [a_, b_, f_, n_]]
            if SinhCoshQ(f) and IntegerQ(n) and n > 2:
                return False

    match = u.match(f_*g_)
    if match:
        if len(match) == 2:
            f, g = match[f_], match[g_]
            if SinhCoshQ(f) and SinhCoshQ(g):
                if IntegersQ(f.args[0]/x, g.args[0]/x):
                    return False

    match = u.match(r_*(a_*s_**m_)**p_)
    if match:
        if len(match) == 5:
            r, a, s, m, p = [match[i] for i in [r_, a_, s_, m_, p_]]
            if Not(m==2 and (s == Sech(x) or s == Csch(x))):
                return False

    if u != ExpandIntegrand(u, x):
        return False

    return True

def OddTrigPowerQ(u, v, x):
    if SinQ(u) or CosQ(u) or SecQ(u) or CscQ(u):
        return OddQuotientQ(u.args[0], v)
    if PowerQ(u):
        return OddQ(u.args[1]) and OddTrigPowerQ(u.base, v, x)
    if ProductQ(u):
        if not FreeFactors(u, x) == 1:
            return OddTrigPowerQ(NonfreeFactors(u, x), v, x)
        lst = []
        for i in u.args:
            if Not(FunctionOfTanQ(i, v, x)):
                lst.append(i)
        if lst == []:
            return True
        return Length(lst)==1 and OddTrigPowerQ(lst[0], v, x)
    if SumQ(u):
        return all(OddTrigPowerQ(i, v, x) for i in u.args)
    return False

def FunctionOfTanQ(u, v, x):
    # If u is a function of the form f[Tan[v],Cot[v]] where f is independent of x,
    # FunctionOfTanQ[u,v,x] returns True; else it returns False.
    if AtomQ(u):
