    elif CalculusQ(u):
        return False
    elif TrigQ(u) and IntegerQuotientQ(u.args[0], v):
        return TanQ(u) or CotQ(u) or EvenQuotientQ(u.args[0], v)
    elif PowerQ(u):
        if EvenQ(u.args[1]) and TrigQ(u.args[0]) and IntegerQuotientQ(u.args[0].args[0], v):
            return True
        elif EvenQ(u.args[1]) and SumQ(u.args[0]):
            return FunctionOfTanQ(Expand(u.args[0]**2, v, x))
    if ProductQ(u):
        lst = []
        for i in u.args:
            if Not(FunctionOfTanQ(i, v, x)):
                lst.append(i)
        if lst == []:
            return True
        return Length(lst)==2 and OddTrigPowerQ(lst[0], v, x) and OddTrigPowerQ(lst[1], v, x)
    return all(FunctionOfTanQ(i, v, x) for i in u.args)

def FunctionOfTanWeight(u, v, x):
    # (* u is a function of the form f[Tan[v],Cot[v]] where f is independent of x.
    # FunctionOfTanWeight[u,v,x] returns a nonnegative number if u is best considered a function
    # of Tan[v]; else it returns a negative number. *)
    if AtomQ(u):
        return S(0)
    elif CalculusQ(u):
        return S(0)
    elif TrigQ(u) and IntegerQuotientQ(u.args[0], v):
        if TanQ(u) and ZeroQ(u.args[0] - v):
            return S(1)
        elif CotQ(u) and ZeroQ(u.args[0] - v):
            return S(-1)
        return S(0)
    elif PowerQ(u):
        if EvenQ(u.exp) and TrigQ(u.base) and IntegerQuotientQ(u.base.args[0], v):
            if TanQ(u.base) or CosQ(u.base) or SecQ(u.base):
                return S(1)
            return S(-1)
    if ProductQ(u):
        if all(FunctionOfTanQ(i, v, x) for i in u.args):
            return Add(*[FunctionOfTanWeight(i, v, x) for i in u.args])
        return S(0)
    return Add(*[FunctionOfTanWeight(i, v, x) for i in u.args])

def Map2(f, lst1, lst2):
    result = []
    for i in range(0, len(lst1)):
        result.append(f(lst1[i], lst2[i]))
    return result

def rubi_test(expr, x, optimal_output, expand=False, _hyper_check=False, _diff=False, _numerical=False):
    #Returns True if (expr - optimal_output) is equal to 0 or a constant
    #expr: integrated expression
    #x: integration variable
    #expand=True equates `expr` with `optimal_output` in expanded form
    #_hyper_check=True evaluates numerically
    #_diff=True differentiates the expressions before equating
    #_numerical=True equates the expressions at random `x`. Normally used for large expressions.

    if expr == optimal_output:
        return True

    res = expr - optimal_output

    if res.has(hyper):
        if _hyper_check:
            dres = res.diff(x)
            args = dres.free_symbols
            for i in range(1, 6):
                sub = dict((s, i) for s in args)
                if not abs(dres.subs(sub).n()) < S(10)**(-100):
                    return False
            return True
        else:
            return True
        return False

    if _numerical:
        args = res.free_symbols
        rand_val = []
        for i in range(0, 5): # check at 5 random points
            rand_x = randint(1, 40)
            substitutions = dict((s, rand_x) for s in args)
            rand_val.append(float(abs(res.subs(substitutions).n())))
        try:
            if stdev(rand_val) < Pow(10, -3):
                return True
            return False
        except:
            return False

    r = simplify(res)
    if r == 0 or (not r.has(x)):
        return True

    if _diff:
        dres = res.diff(x)
        if dres == 0:
            return True
        elif simplify(dres) == 0:
            return True

    if expand: # expands the expression and equates
        e = res.expand()
        if simplify(e) == 0 or (not e.has(x)):
            return True

    return False

def Inequality(*args):
    f = args[1::2]
    e = args[0::2]
    r = []
    for i in range(0, len(f)):
        r.append(f[i](e[i], e[i + 1]))
    return all(r)

def _make_message(ipython=True, quiet=False, source=None):
    """Create a banner for an interactive session. """
    from sympy import __version__ as sympy_version
    from sympy.polys.domains import GROUND_TYPES
    from sympy.utilities.misc import ARCH
    from sympy import SYMPY_DEBUG

    import sys
    import os

    if quiet:
        return ""

    python_version = "%d.%d.%d" % sys.version_info[:3]

    if ipython:
        shell_name = "IPython"
    else:
        shell_name = "Python"

    info = ['ground types: %s' % GROUND_TYPES]

    cache = os.getenv('SYMPY_USE_CACHE')

    if cache is not None and cache.lower() == 'no':
        info.append('cache: off')

    if SYMPY_DEBUG:
        info.append('debugging: on')

    args = shell_name, sympy_version, python_version, ARCH, ', '.join(info)
    message = "%s console for SymPy %s (Python %s-%s) (%s)\n" % args

    if source is None:
        source = preexec_source

    _source = ""

    for line in source.split('\n')[:-1]:
        if not line:
            _source += '\n'
        else:
            _source += '>>> ' + line + '\n'

    doc_version = sympy_version
    if 'dev' in doc_version:
        doc_version = "dev"
    else:
        doc_version = "%s/" % doc_version

    message += '\n' + verbose_message % {'source': _source,
                                         'version': doc_version}

    return message

def eval(cls, *args):
    try:
        newargs = []
        for x in args:
            if isinstance(x, Number) or x in (0, 1):
                newargs.append(True if x else False)
            else:
                newargs.append(x)
        A, B = newargs
    except ValueError:
        raise ValueError(
            "%d operand(s) used for an Implies "
            "(pairs are required): %s" % (len(args), str(args)))
    if A == True or A == False or B == True or B == False:
        return Or(Not(A), B)
    elif A == B:
        return S.true
    elif A.is_Relational and B.is_Relational:
        if A.canonical == B.canonical:
            return S.true
        if (~A).canonical == B.canonical:
            return B
    else:
        return Basic.__new__(cls, *args)

def __new__(cls, *args, **options):
    from sympy.core.relational import Relational
    args = [_sympify(arg) for arg in args]

    argset = set(args)
    for x in args:
        if isinstance(x, Number) or x in [True, False]: # Includes 0, 1
            argset.discard(x)
            argset.add(True if x else False)
    rel = []
    for r in argset:
        if isinstance(r, Relational):
            rel.append((r, r.canonical, (~r).canonical))
    remove = []
    for i, (r, c, nc) in enumerate(rel):
        for j in range(i + 1, len(rel)):
            rj, cj = rel[j][:2]
            if cj == nc:
                return false
            elif cj == c:
                remove.append((r, rj))
                break
    for a, b in remove:
        argset.remove(a)
        argset.remove(b)
        argset.add(True)
    if len(argset) <= 1:
        return true
    if True in argset:
        argset.discard(True)
        return And(*argset)
    if False in argset:
        argset.discard(False)
        return And(*[~arg for arg in argset])
    _args = frozenset(argset)
    obj = super(Equivalent, cls).__new__(cls, _args)
    obj._argset = _args
    return obj

def _rem_redundancy(l1, terms):
    """
    After the truth table has been sufficiently simplified, use the prime
    implicant table method to recognize and eliminate redundant pairs,
    and return the essential arguments.
    """
    essential = []
    for x in terms:
        temporary = []
        for y in l1:
            if _compare_term(x, y):
                temporary.append(y)
        if len(temporary) == 1:
            if temporary[0] not in essential:
                essential.append(temporary[0])
    for x in terms:
        for y in essential:
            if _compare_term(x, y):
                break
        else:
            for z in l1:
                if _compare_term(x, z):
                    if z not in essential:
                        essential.append(z)
                    break

    return essential

def __rmul__(self, other):
    other = _matrixify(other)
    # matrix-like objects can have shapes.  This is
    # our first sanity check.
    if hasattr(other, 'shape') and len(other.shape) == 2:
        if self.shape[0] != other.shape[1]:
            raise ShapeError("Matrix size mismatch.")

    # honest sympy matrices defer to their class's routine
    if getattr(other, 'is_Matrix', False):
        return other._new(other.as_mutable() * self)
    # Matrix-like objects can be passed to CommonMatrix routines directly.
    if getattr(other, 'is_MatrixLike', False):
        return MatrixArithmetic._eval_matrix_rmul(self, other)

    try:
        return self._eval_scalar_rmul(other)
    except TypeError:
        pass

    raise TypeError('Cannot multiply %s and %s' % (type(self), type(other)))

def __new__(cls, *args, **old_assumptions):
    from sympy.physics.quantum.state import KetBase, BraBase

    if len(args) != 2:
        raise ValueError('2 parameters expected, got %d' % len(args))

    ket_expr = expand(args[0])
    bra_expr = expand(args[1])

    if (isinstance(ket_expr, (KetBase, Mul)) and
            isinstance(bra_expr, (BraBase, Mul))):
        ket_c, kets = ket_expr.args_cnc()
        bra_c, bras = bra_expr.args_cnc()

        if len(kets) != 1 or not isinstance(kets[0], KetBase):
            raise TypeError('KetBase subclass expected'
                            ', got: %r' % Mul(*kets))

        if len(bras) != 1 or not isinstance(bras[0], BraBase):
            raise TypeError('BraBase subclass expected'
                            ', got: %r' % Mul(*bras))

        if not kets[0].dual_class() == bras[0].__class__:
            raise TypeError(
                'ket and bra are not dual classes: %r, %r' %
                (kets[0].__class__, bras[0].__class__)
                )

        # TODO: make sure the hilbert spaces of the bra and ket are
        # compatible
        obj = Expr.__new__(cls, *(kets[0], bras[0]), **old_assumptions)
        obj.hilbert_space = kets[0].hilbert_space
        return Mul(*(ket_c + bra_c)) * obj

    op_terms = []
    if isinstance(ket_expr, Add) and isinstance(bra_expr, Add):
        for ket_term in ket_expr.args:
            for bra_term in bra_expr.args:
                op_terms.append(OuterProduct(ket_term, bra_term,
                                             **old_assumptions))
    elif isinstance(ket_expr, Add):
        for ket_term in ket_expr.args:
            op_terms.append(OuterProduct(ket_term, bra_expr,
                                         **old_assumptions))
    elif isinstance(bra_expr, Add):
        for bra_term in bra_expr.args:
            op_terms.append(OuterProduct(ket_expr, bra_term,
                                         **old_assumptions))
    else:
        raise TypeError(
            'Expected ket and bra expression, got: %r, %r' %
            (ket_expr, bra_expr)
            )

    return Add(*op_terms)

def _expand_powers(factors):
    """
    Helper function for normal_ordered_form and normal_order: Expand a
    power expression to a multiplication expression so that that the
    expression can be handled by the normal ordering functions.
    """

    new_factors = []
    for factor in factors.args:
        if (isinstance(factor, Pow)
                and isinstance(factor.args[1], Integer)
                and factor.args[1] > 0):
            for n in range(factor.args[1]):
                new_factors.append(factor.args[0])
        else:
            new_factors.append(factor)

    return new_factors

def _rewrite_basis(self, basis, evect, **options):
    from sympy.physics.quantum.represent import represent
    j = self.j
    args = self.args[2:]
    if j.is_number:
        if isinstance(self, CoupledSpinState):
            if j == int(j):
                start = j**2
            else:
                start = (2*j - 1)*(2*j + 1)/4
        else:
            start = 0
        vect = represent(self, basis=basis, **options)
        result = Add(
            *[vect[start + i] * evect(j, j - i, *args) for i in range(2*j + 1)])
        if isinstance(self, CoupledSpinState) and options.get('coupled') is False:
            return uncouple(result)
        return result
    else:
        i = 0
        mi = symbols('mi')
        # make sure not to introduce a symbol already in the state
        while self.subs(mi, 0) != self:
            i += 1
            mi = symbols('mi%d' % i)
            break
        # TODO: better way to get angles of rotation
        if isinstance(self, CoupledSpinState):
            test_args = (0, mi, (0, 0))
        else:
            test_args = (0, mi)
        if isinstance(self, Ket):
            angles = represent(
                self.__class__(*test_args), basis=basis)[0].args[3:6]
        else:
            angles = represent(self.__class__(
                *test_args), basis=basis)[0].args[0].args[3:6]
        if angles == (0, 0, 0):
            return self
        else:
            state = evect(j, mi, *args)
            lt = Rotation.D(j, mi, self.m, *angles)
            return Sum(lt * state, (mi, -j, j))

def __new__(cls, j, m, jn, *jcoupling):
    # Check j and m values using SpinState
    SpinState(j, m)
    # Build and check coupling scheme from arguments
    if len(jcoupling) == 0:
        # Use default coupling scheme
        jcoupling = []
        for n in range(2, len(jn)):
            jcoupling.append( (1, n, Add(*[jn[i] for i in range(n)])) )
        jcoupling.append( (1, len(jn), j) )
    elif len(jcoupling) == 1:
        # Use specified coupling scheme
        jcoupling = jcoupling[0]
    else:
        raise TypeError("CoupledSpinState only takes 3 or 4 arguments, got: %s" % (len(jcoupling) + 3) )
    # Check arguments have correct form
    if not (isinstance(jn, list) or isinstance(jn, tuple) or isinstance(jn, Tuple)):
        raise TypeError('jn must be Tuple, list or tuple, got %s' %
                        jn.__class__.__name__)
    if not (isinstance(jcoupling, list) or isinstance(jcoupling, tuple) or isinstance(jcoupling, Tuple)):
        raise TypeError('jcoupling must be Tuple, list or tuple, got %s' %
                        jcoupling.__class__.__name__)
    if not all(isinstance(term, list) or isinstance(term, tuple) or isinstance(term, Tuple) for term in jcoupling):
        raise TypeError(
            'All elements of jcoupling must be list, tuple or Tuple')
    if not len(jn) - 1 == len(jcoupling):
        raise ValueError('jcoupling must have length of %d, got %d' %
                         (len(jn) - 1, len(jcoupling)))
    if not all(len(x) == 3 for x in jcoupling):
        raise ValueError('All elements of jcoupling must have length 3')
    # Build sympified args
    j = sympify(j)
    m = sympify(m)
    jn = Tuple( *[sympify(ji) for ji in jn] )
    jcoupling = Tuple( *[Tuple(sympify(
        n1), sympify(n2), sympify(ji)) for (n1, n2, ji) in jcoupling] )
    # Check values in coupling scheme give physical state
    if any(2*ji != int(2*ji) for ji in jn if ji.is_number):
        raise ValueError('All elements of jn must be integer or half-integer, got: %s' % jn)
    if any(n1 != int(n1) or n2 != int(n2) for (n1, n2, _) in jcoupling):
        raise ValueError('Indicies in jcoupling must be integers')
    if any(n1 < 1 or n2 < 1 or n1 > len(jn) or n2 > len(jn) for (n1, n2, _) in jcoupling):
        raise ValueError('Indicies must be between 1 and the number of coupled spin spaces')
    if any(2*ji != int(2*ji) for (_, _, ji) in jcoupling if ji.is_number):
        raise ValueError('All coupled j values in coupling scheme must be integer or half-integer')
    coupled_n, coupled_jn = _build_coupled(jcoupling, len(jn))
    jvals = list(jn)
    for n, (n1, n2) in enumerate(coupled_n):
        j1 = jvals[min(n1) - 1]
        j2 = jvals[min(n2) - 1]
        j3 = coupled_jn[n]
        if sympify(j1).is_number and sympify(j2).is_number and sympify(j3).is_number:
            if j1 + j2 < j3:
                raise ValueError('All couplings must have j1+j2 >= j3, '
                    'in coupling number %d got j1,j2,j3: %d,%d,%d' % (n + 1, j1, j2, j3))
            if abs(j1 - j2) > j3:
                raise ValueError("All couplings must have |j1+j2| <= j3, "
                    "in coupling number %d got j1,j2,j3: %d,%d,%d" % (n + 1, j1, j2, j3))
            if int(j1 + j2) == j1 + j2:
                pass
        jvals[min(n1 + n2) - 1] = j3
    if len(jcoupling) > 0 and jcoupling[-1][2] != j:
        raise ValueError('Last j value coupled together must be the final j of the state')
    # Return state
    return State.__new__(cls, j, m, jn, jcoupling)

def __new__(cls, name, dimension, scale_factor=S.One, abbrev=None, dim_sys=dimsys_default, **assumptions):

    if not isinstance(name, Symbol):
        name = Symbol(name)

    if not isinstance(dim_sys, DimensionSystem):
        raise TypeError("%s is not a DimensionSystem" % dim_sys)

    if not isinstance(dimension, dimensions.Dimension):
        if dimension == 1:
            dimension = Dimension(1)
        else:
            raise ValueError("expected dimension or 1")
    else:
        for dim_sym in dimension.name.atoms(Dimension):
            if dim_sym not in [i.name for i in dim_sys._dimensional_dependencies]:
                raise ValueError("Dimension %s is not registered in the "
                                 "dimensional dependency tree." % dim_sym)

    scale_factor = sympify(scale_factor)

    dimex = Quantity.get_dimensional_expr(scale_factor)
    if dimex != 1:
        if not dim_sys.equivalent_dims(dimension, Dimension(dimex)):
            raise ValueError("quantity value and dimension mismatch")

    # replace all prefixes by their ratio to canonical units:
    scale_factor = scale_factor.replace(lambda x: isinstance(x, Prefix), lambda x: x.scale_factor)
    # replace all quantities by their ratio to canonical units:
    scale_factor = scale_factor.replace(lambda x: isinstance(x, Quantity), lambda x: x.scale_factor)

    if abbrev is None:
        abbrev = name
    elif isinstance(abbrev, string_types):
        abbrev = Symbol(abbrev)

    obj = AtomicExpr.__new__(cls, name, dimension, scale_factor, abbrev)
    obj._name = name
    obj._dimension = dimension
    obj._scale_factor = scale_factor
    obj._dim_sys = dim_sys
    obj._abbrev = abbrev
    return obj

def _pretty(self, printer=None):
    """Pretty Printing method. """
    from sympy.physics.vector.printing import VectorPrettyPrinter
    from sympy.printing.pretty.stringpict import prettyForm
    e = self

    class Fake(object):

        def render(self, *args, **kwargs):
            ar = e.args  # just to shorten things
            if len(ar) == 0:
                return unicode(0)
            settings = printer._settings if printer else {}
            vp = printer if printer else VectorPrettyPrinter(settings)
            pforms = []  # output list, to be concatenated to a string
            for i, v in enumerate(ar):
                for j in 0, 1, 2:
                    # if the coef of the basis vector is 1, we skip the 1
                    if ar[i][0][j] == 1:
                        pform = vp._print(ar[i][1].pretty_vecs[j])
                    # if the coef of the basis vector is -1, we skip the 1
                    elif ar[i][0][j] == -1:
                        pform = vp._print(ar[i][1].pretty_vecs[j])
                        pform= prettyForm(*pform.left(" - "))
                        bin = prettyForm.NEG
                        pform = prettyForm(binding=bin, *pform)
                    elif ar[i][0][j] != 0:
                        # If the basis vector coeff is not 1 or -1,
                        # we might wrap it in parentheses, for readability.
                        if isinstance(ar[i][0][j], Add):
                            pform = vp._print(
                                ar[i][0][j]).parens()
                        else:
                            pform = vp._print(
                                ar[i][0][j])
                        pform = prettyForm(*pform.right(" ",
                                            ar[i][1].pretty_vecs[j]))
                    else:
                        continue
                    pforms.append(pform)

            pform = prettyForm.__add__(*pforms)
            kwargs["wrap_line"] = kwargs.get("wrap_line")
            kwargs["num_columns"] = kwargs.get("num_columns")
            out_str = pform.render(*args, **kwargs)
            mlines = [line.rstrip() for line in out_str.split("\n")]
            return "\n".join(mlines)

    return Fake()

def textplot(expr, a, b, W=55, H=18):
    """
    Print a crude ASCII art plot of the SymPy expression 'expr' (which
    should contain a single symbol, e.g. x or something else) over the
    interval [a, b].

    Examples
    ========

    textplot(sin(t)*t, 0, 15)
    """

    free = expr.free_symbols
    if len(free) > 1:
        raise ValueError("length can not be greater than 1")
    x = free.pop() if free else Dummy()
    f = lambdify([x], expr)
    a = float(a)
    b = float(b)

    # Calculate function values
    y = [0] * W
    for x in range(W):
        try:
            y[x] = f(a + (b - a)/float(W)*x)
        except (TypeError, ValueError):
            y[x] = 0

    # Normalize height to screen space
    ma = max(y)
    mi = min(y)
    if ma == mi:
        if ma:
            mi, ma = sorted([0, 2*ma])
        else:
            mi, ma = -1, 1
    for x in range(W):
        y[x] = int(float(H)*(y[x] - mi)/(ma - mi))
    margin = 7
    print

    for h in range(H - 1, -1, -1):
        s = [' '] * W
        for x in range(W):
            if y[x] == h:
                if (x == 0 or y[x - 1] == h - 1) and (x == W - 1 or y[x + 1] == h + 1):
                    s[x] = '/'
                elif (x == 0 or y[x - 1] == h + 1) and (x == W - 1 or y[x + 1] == h - 1):
                    s[x] = '\\'
                else:
                    s[x] = '.'

        # Print y values
        if h == H - 1:
            prefix = ("%g" % ma).rjust(margin)[:margin]
        elif h == H//2:
            prefix = ("%g" % ((mi + ma)/2)).rjust(margin)[:margin]
        elif h == 0:
            prefix = ("%g" % mi).rjust(margin)[:margin]
        else:
            prefix = " "*margin
        s = "".join(s)
        if h == H//2:
            s = s.replace(" ", "-")
        print(prefix + " | " + s)

    # Print x values
    bottom = " " * (margin + 3)
    bottom += ("%g" % a).ljust(W//2 - 4)
    bottom += ("%g" % ((a + b)/2)).ljust(W//2)
    bottom += "%g" % b
    print(bottom)

def _rec_inflate(g, M, v, i, K):
    """Recursive helper for :func:`dmp_inflate`."""
    if not v:
        return dup_inflate(g, M[i], K)
    if M[i] <= 0:
        raise IndexError("all M[i] must be positive, got %s" % M[i])

    w, j = v - 1, i + 1

    g = [ _rec_inflate(c, M, w, j, K) for c in g ]

    result = [g[0]]

    for coeff in g[1:]:
        for _ in range(1, M[i]):
            result.append(dmp_zero(w))

        result.append(coeff)

    return result

def _choose_factor(factors, x, v, dom=QQ, prec=200, bound=5):
    """
    Return a factor having root ``v``
    It is assumed that one of the factors has root ``v``.
    """
    if isinstance(factors[0], tuple):
        factors = [f[0] for f in factors]
    if len(factors) == 1:
        return factors[0]

    points = {x:v}
    symbols = dom.symbols if hasattr(dom, 'symbols') else []
    t = QQ(1, 10)

    for n in range(bound**len(symbols)):
        prec1 = 10
        n_temp = n
        for s in symbols:
            points[s] = n_temp % bound
            n_temp = n_temp // bound

        while True:
            candidates = []
            eps = t**(prec1 // 2)
            for f in factors:
                if abs(f.as_expr().evalf(prec1, points)) < eps:
                    candidates.append(f)
            if candidates:
                factors = candidates
            if len(factors) == 1:
                return factors[0]
            if prec1 > prec:
                break
            prec1 *= 2

    raise NotImplementedError("multiple candidates for the minimal polynomial of %s" % v)

def __init__(self, gens, args, flags=None, strict=False):
    dict.__init__(self)

    if gens and args.get('gens', ()):
        raise OptionError(
            "both '*gens' and keyword argument 'gens' supplied")
    elif gens:
        args = dict(args)
        args['gens'] = gens

    defaults = args.pop('defaults', {})

    def preprocess_options(args):
        for option, value in args.items():
            try:
                cls = self.__options__[option]
            except KeyError:
                raise OptionError("'%s' is not a valid option" % option)

            if issubclass(cls, Flag):
                if flags is None or option not in flags:
                    if strict:
                        raise OptionError("'%s' flag is not allowed in this context" % option)

            if value is not None:
                self[option] = cls.preprocess(value)

    preprocess_options(args)

    for key, value in dict(defaults).items():
        if key in self:
            del defaults[key]
        else:
            for option in self.keys():
                cls = self.__options__[option]

                if key in cls.excludes:
                    del defaults[key]
                    break

    preprocess_options(defaults)

    for option in self.keys():
        cls = self.__options__[option]

        for require_option in cls.requires:
            if self.get(require_option) is None:
                raise OptionError("'%s' option is only allowed together with '%s'" % (option, require_option))

        for exclude_option in cls.excludes:
            if self.get(exclude_option) is not None:
                raise OptionError("'%s' option is not allowed together with '%s'" % (option, exclude_option))

    for option in self.__order__:
        self.__options__[option].postprocess(self)

def _parallel_dict_from_expr_if_gens(exprs, opt):
    """Transform expressions into a multinomial form given generators. """
    k, indices = len(opt.gens), {}

    for i, g in enumerate(opt.gens):
        indices[g] = i

    polys = []

    for expr in exprs:
        poly = {}

        if expr.is_Equality:
            expr = expr.lhs - expr.rhs

        for term in Add.make_args(expr):
            coeff, monom = [], [0]*k

            for factor in Mul.make_args(term):
                if not _not_a_coeff(factor) and factor.is_Number:
                    coeff.append(factor)
                else:
                    try:
                        if opt.series is False:
                            base, exp = decompose_power(factor)

                            if exp < 0:
                                exp, base = -exp, Pow(base, -S.One)
                        else:
                            base, exp = decompose_power_rat(factor)

                        monom[indices[base]] = exp
                    except KeyError:
                        if not factor.free_symbols.intersection(opt.gens):
                            coeff.append(factor)
                        else:
                            raise PolynomialError("%s contains an element of the generators set" % factor)

            monom = tuple(monom)

            if monom in poly:
                poly[monom] += Mul(*coeff)
            else:
                poly[monom] = Mul(*coeff)

        polys.append(poly)

    return polys, opt.gens

def index(self, gen):
    """Compute index of ``gen`` in ``self.gens``. """
    if gen is None:
        if self.ngens:
            i = 0
        else:
            i = -1  # indicate impossible choice
    elif isinstance(gen, int):
        i = gen

        if 0 <= i and i < self.ngens:
            pass
        elif -self.ngens <= i and i <= -1:
            i = -i - 1
        else:
            raise ValueError("invalid generator index: %s" % gen)
    elif isinstance(gen, self.dtype):
        try:
            i = self.gens.index(gen)
        except ValueError:
            raise ValueError("invalid generator: %s" % gen)
    elif isinstance(gen, string_types):
        try:
            i = self.symbols.index(gen)
        except ValueError:
            raise ValueError("invalid generator: %s" % gen)
    else:
        raise ValueError("expected a polynomial generator, an integer, a string or None, got %s" % gen)

    return i

def _term_div(self):
    zm = self.ring.zero_monom
    domain = self.ring.domain
    domain_quo = domain.quo
    monomial_div = self.ring.monomial_div

    if domain.is_Field:
        def term_div(a_lm_a_lc, b_lm_b_lc):
            a_lm, a_lc = a_lm_a_lc
            b_lm, b_lc = b_lm_b_lc
            if b_lm == zm: # apparently this is a very common case
                monom = a_lm
            else:
                monom = monomial_div(a_lm, b_lm)
            if monom is not None:
                return monom, domain_quo(a_lc, b_lc)
            else:
                return None
    else:
        def term_div(a_lm_a_lc, b_lm_b_lc):
            a_lm, a_lc = a_lm_a_lc
            b_lm, b_lc = b_lm_b_lc
            if b_lm == zm: # apparently this is a very common case
                monom = a_lm
            else:
                monom = monomial_div(a_lm, b_lm)
            if not (monom is None or a_lc % b_lc):
                return monom, domain_quo(a_lc, b_lc)
            else:
                return None

    return term_div

def __new__(cls, f, x, index=None, radicals=False, expand=True):
    """ Construct an indexed complex root of a polynomial.

    See ``rootof`` for the parameters.

    The default value of ``radicals`` is ``False`` to satisfy
    ``eval(srepr(expr) == expr``.
    """
    x = sympify(x)

    if index is None and x.is_Integer:
        x, index = None, x
    else:
        index = sympify(index)

    if index is not None and index.is_Integer:
        index = int(index)
    else:
        raise ValueError("expected an integer root index, got %s" % index)

    poly = PurePoly(f, x, greedy=False, expand=expand)

    if not poly.is_univariate:
        raise PolynomialError("only univariate polynomials are allowed")

    degree = poly.degree()

    if degree <= 0:
        raise PolynomialError("can't construct CRootOf object for %s" % f)

    if index < -degree or index >= degree:
        raise IndexError("root index out of [%d, %d] range, got %d" %
                         (-degree, degree - 1, index))
    elif index < 0:
        index += degree

    dom = poly.get_domain()

    if not dom.is_Exact:
        poly = poly.to_exact()

    roots = cls._roots_trivial(poly, radicals)

    if roots is not None:
        return roots[index]

    coeff, poly = preprocess_roots(poly)
    dom = poly.get_domain()

    if not dom.is_ZZ:
        raise NotImplementedError("CRootOf is not supported over %s" % dom)

    root = cls._indexed_root(poly, index)
    return coeff * cls._postprocess_root(root, radicals)

def _print_Dummy(self, expr):
    if expr.name.startswith('Dummy_'):
        return '_' + expr.name
    else:
        return '%s_%d' % (expr.name, expr.dummy_index)

def _print_Function(self, expr):
    if expr.func.__name__ in self.known_functions:
        cond_func = self.known_functions[expr.func.__name__]
        func = None
        if isinstance(cond_func, str):
            func = cond_func
        else:
            for cond, func in cond_func:
                if cond(*expr.args):
                    break
        if func is not None:
            try:
                return func(*[self.parenthesize(item, 0) for item in expr.args])
            except TypeError:
                return "%s(%s)" % (func, self.stringify(expr.args, ", "))
    elif hasattr(expr, '_imp_') and isinstance(expr._imp_, Lambda):
        # inlined function
        return self._print(expr._imp_(*expr.args))
    else:
        return self._print_not_supported(expr)

def _print_Function_with_args(self, func, *args):
    if func in self.known_functions:
        cond_func = self.known_functions[func]
        func = None
        if isinstance(cond_func, str):
            func = cond_func
        else:
            for cond, func in cond_func:
                if cond(args):
                    break
        if func is not None:
            try:
                return func(*[self.parenthesize(item, 0) for item in args])
            except TypeError:
                return "%s(%s)" % (func, self.stringify(args, ", "))
    elif isinstance(func, Lambda):
        # inlined function
        return self._print(func(*args))
    else:
        return self._print_not_supported(func)

def _print_Pow(self, expr):
    # Treat x**Rational(1,n) as special case
    if expr.exp.is_Rational and abs(expr.exp.p) == 1 and expr.exp.q != 1:
        base = self._print(expr.base)
        expq = expr.exp.q

        if expq == 2:
            tex = r"\sqrt{%s}" % base
        elif self._settings['itex']:
            tex = r"\root{%d}{%s}" % (expq, base)
        else:
            tex = r"\sqrt[%d]{%s}" % (expq, base)

        if expr.exp.is_negative:
            return r"\frac{1}{%s}" % tex
        else:
            return tex
    elif self._settings['fold_frac_powers'] \
        and expr.exp.is_Rational \
            and expr.exp.q != 1:
        base, p, q = self.parenthesize(expr.base, PRECEDENCE['Pow']), expr.exp.p, expr.exp.q
        #fixes issue #12886, adds parentheses before superscripts raised to powers
        if '^' in base and expr.base.is_Symbol:
            base = r"\left(%s\right)" % base
        if expr.base.is_Function:
            return self._print(expr.base, "%s/%s" % (p, q))
        return r"%s^{%s/%s}" % (base, p, q)
    elif expr.exp.is_Rational and expr.exp.is_negative and expr.base.is_commutative:
        # Things like 1/x
        return self._print_Mul(expr)
    else:
        if expr.base.is_Function:
            return self._print(expr.base, self._print(expr.exp))
        else:
            if expr.is_commutative and expr.exp == -1:
                #solves issue 4129
                #As Mul always simplify 1/x to x**-1
                #The objective is achieved with this hack
                #first we get the latex for -1 * expr,
                #which is a Mul expression
                tex = self._print(S.NegativeOne * expr).strip()
                #the result comes with a minus and a space, so we remove
                if tex[:1] == "-":
                    return tex[1:].strip()
            tex = r"%s^{%s}"
            #fixes issue #12886, adds parentheses before superscripts raised to powers
            base = self.parenthesize(expr.base, PRECEDENCE['Pow'])
            if '^' in base and expr.base.is_Symbol:
                base = r"\left(%s\right)" % base
            exp = self._print(expr.exp)

            return tex % (base, exp)

def _print_Rational(self, expr):
    if expr.q != 1:
        sign = ""
        p = expr.p
        if expr.p < 0:
            sign = "- "
            p = -p
        if self._settings['fold_short_frac']:
            return r"%s%d / %d" % (sign, p, expr.q)
        return r"%s\frac{%d}{%d}" % (sign, p, expr.q)
    else:
        return self._print(expr.p)

def _print_MatrixBase(self, expr):
    lines = []

    for line in range(expr.rows):  # horrible, should be 'rows'
        lines.append(" & ".join([ self._print(i) for i in expr[line, :] ]))

    mat_str = self._settings['mat_str']
    if mat_str is None:
        if self._settings['mode'] == 'inline':
            mat_str = 'smallmatrix'
        else:
            if (expr.cols <= 10) is True:
                mat_str = 'matrix'
            else:
                mat_str = 'array'

    out_str = r'\begin{%MATSTR%}%s\end{%MATSTR%}'
    out_str = out_str.replace('%MATSTR%', mat_str)
    if mat_str == 'array':
        out_str = out_str.replace('%s', '{' + 'c'*expr.cols + '}%s')
    if self._settings['mat_delim']:
        left_delim = self._settings['mat_delim']
        right_delim = self._delim_dict[left_delim]
        out_str = r'\left' + left_delim + out_str + \
                  r'\right' + right_delim
    return out_str % r"\\".join(lines)

def _print_ProductSet(self, p):
    if len(p.sets) > 1 and not has_variety(p.sets):
        return self._print(p.sets[0]) + "^%d" % len(p.sets)
    else:
        return r" \times ".join(self._print(set) for set in p.sets)

def _print_ComplexRootOf(self, root):
    cls = root.__class__.__name__
    if cls == "ComplexRootOf":
        cls = "CRootOf"
    expr = self._print(root.expr)
    index = root.index
    if cls in accepted_latex_functions:
        return r"\%s {\left(%s, %d\right)}" % (cls, expr, index)
    else:
        return r"\operatorname{%s} {\left(%s, %d\right)}" % (cls, expr, index)

def _print_Add(self, expr, order=None):
    if self.order == 'none':
        terms = list(expr.args)
    else:
        terms = self._as_ordered_terms(expr, order=order)
    pforms, indices = [], []

    def pretty_negative(pform, index):
        """Prepend a minus sign to a pretty form. """
        #TODO: Move this code to prettyForm
        if index == 0:
            if pform.height() > 1:
                pform_neg = '- '
            else:
                pform_neg = '-'
        else:
            pform_neg = ' - '

        if pform.binding > prettyForm.NEG:
            p = stringPict(*pform.parens())
        else:
            p = pform
        p = stringPict.next(pform_neg, p)
        # Lower the binding to NEG, even if it was higher. Otherwise, it
        # will print as a + ( - (b)), instead of a - (b).
        return prettyForm(binding=prettyForm.NEG, *p)

    for i, term in enumerate(terms):
        if term.is_Mul and _coeff_isneg(term):
            coeff, other = term.as_coeff_mul(rational=False)
            pform = self._print(Mul(-coeff, *other, evaluate=False))
            pforms.append(pretty_negative(pform, i))
        elif term.is_Rational and term.q > 1:
            pforms.append(None)
            indices.append(i)
        elif term.is_Number and term < 0:
            pform = self._print(-term)
            pforms.append(pretty_negative(pform, i))
        elif term.is_Relational:
            pforms.append(prettyForm(*self._print(term).parens()))
        else:
            pforms.append(self._print(term))

    if indices:
        large = True

        for pform in pforms:
            if pform is not None and pform.height() > 1:
                break
        else:
            large = False

        for i in indices:
            term, negative = terms[i], False

            if term < 0:
                term, negative = -term, True

            if large:
                pform = prettyForm(str(term.p))/prettyForm(str(term.q))
            else:
                pform = self._print(term)

            if negative:
                pform = pretty_negative(pform, i)

            pforms[i] = pform

    return prettyForm.__add__(*pforms)

def _print_KroneckerDelta(self, e):
    pform = self._print(e.args[0])
    pform = prettyForm(*pform.right((prettyForm(','))))
    pform = prettyForm(*pform.right((self._print(e.args[1]))))
    if self._use_unicode:
        a = stringPict(pretty_symbol('delta'))
    else:
        a = stringPict('d')
    b = pform
    top = stringPict(*b.left(' '*a.width()))
    bot = stringPict(*a.right(' '*b.width()))
    return prettyForm(binding=prettyForm.POW, *bot.below(top))

def __pow__(self, b):
    """Make a pretty power.
    """
    a = self
    use_inline_func_form = False
    if b.binding == prettyForm.POW:
        b = stringPict(*b.parens())
    if a.binding > prettyForm.FUNC:
        a = stringPict(*a.parens())
    elif a.binding == prettyForm.FUNC:
        # heuristic for when to use inline power
        if b.height() > 1:
            a = stringPict(*a.parens())
        else:
            use_inline_func_form = True

    if use_inline_func_form:
        #         2
        #  sin  +   + (x)
        b.baseline = a.prettyFunc.baseline + b.height()
        func = stringPict(*a.prettyFunc.right(b))
        return prettyForm(*func.right(a.prettyArgs))
    else:
        #      2    <-- top
        # (x+y)     <-- bot
        top = stringPict(*b.left(' '*a.width()))
        bot = stringPict(*a.right(' '*b.width()))

    return prettyForm(binding=prettyForm.POW, *bot.above(top))

def apply(function, *args):
    """Functions of one or more variables.
    """
    if function in prettyForm.simpleFunctions:
        #simple function: use only space if possible
        assert len(
            args) == 1, "Simple function %s must have 1 argument" % function
        arg = args[0].__pretty__()
        if arg.binding <= prettyForm.DIV:
            #optimization: no parentheses necessary
            return prettyForm(binding=prettyForm.FUNC, *arg.left(function + ' '))
    argumentList = []
    for arg in args:
        argumentList.append(',')
        argumentList.append(arg.__pretty__())
    argumentList = stringPict(*stringPict.next(*argumentList[1:]))
    argumentList = stringPict(*argumentList.parens())
    return prettyForm(binding=prettyForm.ATOM, *argumentList.left(function))

def emptyPrinter(self, expr):
    """
    The fallback printer.
    """
    if isinstance(expr, str):
        return expr
    elif hasattr(expr, "__srepr__"):
        return expr.__srepr__()
    elif hasattr(expr, "args") and hasattr(expr.args, "__iter__"):
        l = []
        for o in expr.args:
            l.append(self._print(o))
        return expr.__class__.__name__ + '(%s)' % ', '.join(l)
    elif hasattr(expr, "__module__") and hasattr(expr, "__name__"):
        return "<'%s.%s'>" % (expr.__module__, expr.__name__)
    else:
        return str(expr)

def _print_Function(self, expr):
    """
    basic function for printing `Function`

    Function Style :

    1. args[0].func(args[1:]), method with arguments
    2. args[0].func(), method without arguments
    3. args[1].func(), method without arguments (e.g. (e, x) => x.exp())
    4. func(args), function with arguments
    """

    if expr.func.__name__ in self.known_functions:
        cond_func = self.known_functions[expr.func.__name__]
        func = None
        style = 1
        if isinstance(cond_func, str):
            func = cond_func
        else:
            for cond, func, style in cond_func:
                if cond(*expr.args):
                    break
        if func is not None:
            if style == 1:
                ret = "%(var)s.%(method)s(%(args)s)" % {
                    'var': self._print_caller_var(expr.args[0]),
                    'method': func,
                    'args': self.stringify(expr.args[1:], ", ") if len(expr.args) > 1 else ''
                }
            elif style == 2:
                ret = "%(var)s.%(method)s()" % {
                    'var': self._print_caller_var(expr.args[0]),
                    'method': func,
                }
            elif style == 3:
                ret = "%(var)s.%(method)s()" % {
                    'var': self._print_caller_var(expr.args[1]),
                    'method': func,
                }
            else:
                ret = "%(func)s(%(args)s)" % {
                    'func': func,
                    'args': self.stringify(expr.args, ", "),
                }
            return ret
    elif hasattr(expr, '_imp_') and isinstance(expr._imp_, Lambda):
        # inlined function
        return self._print(expr._imp_(*expr.args))
    else:
        return self._print_not_supported(expr)

def _print_Poly(self, expr):
    ATOM_PREC = PRECEDENCE["Atom"] - 1
    terms, gens = [], [ self.parenthesize(s, ATOM_PREC) for s in expr.gens ]

    for monom, coeff in expr.terms():
        s_monom = []

        for i, exp in enumerate(monom):
            if exp > 0:
                if exp == 1:
                    s_monom.append(gens[i])
                else:
                    s_monom.append(gens[i] + "**%d" % exp)

        s_monom = "*".join(s_monom)

        if coeff.is_Add:
            if s_monom:
                s_coeff = "(" + self._print(coeff) + ")"
            else:
                s_coeff = self._print(coeff)
        else:
            if s_monom:
                if coeff is S.One:
                    terms.extend(['+', s_monom])
                    continue

                if coeff is S.NegativeOne:
                    terms.extend(['-', s_monom])
                    continue

            s_coeff = self._print(coeff)

        if not s_monom:
            s_term = s_coeff
        else:
            s_term = s_coeff + "*" + s_monom

        if s_term.startswith('-'):
            terms.extend(['-', s_term[1:]])
        else:
            terms.extend(['+', s_term])

    if terms[0] in ['-', '+']:
        modifier = terms.pop(0)

        if modifier == '-':
            terms[0] = '-' + terms[0]

    format = expr.__class__.__name__ + "(%s, %s"

    from sympy.polys.polyerrors import PolynomialError

    try:
        format += ", modulus=%s" % expr.get_modulus()
    except PolynomialError:
        format += ", domain='%s'" % expr.get_domain()

    format += ")"

    for index, item in enumerate(gens):
        if len(item) > 2 and (item[:1] == "(" and item[len(item) - 1:] == ")"):
            gens[index] = item[1:len(item) - 1]

    return format % (' '.join(terms), ', '.join(gens))

def _print_Pow(self, expr, rational=False):
    PREC = precedence(expr)

    if expr.exp is S.Half and not rational:
        return "sqrt(%s)" % self._print(expr.base)

    if expr.is_commutative:
        if -expr.exp is S.Half and not rational:
            # Note: Don't test "expr.exp == -S.Half" here, because that will
            # match -0.5, which we don't want.
            return "%s/sqrt(%s)" % tuple(map(self._print, (S.One, expr.base)))
        if expr.exp is -S.One:
            # Similarly to the S.Half case, don't test with "==" here.
            return '%s/%s' % (self._print(S.One),
                              self.parenthesize(expr.base, PREC, strict=False))

    e = self.parenthesize(expr.exp, PREC, strict=False)
    if self.printmethod == '_sympyrepr' and expr.exp.is_Rational and expr.exp.q != 1:
        # the parenthesized exp should be '(Rational(a, b))' so strip parens,
        # but just check to be sure.
        if e.startswith('(Rational'):
            return '%s**%s' % (self.parenthesize(expr.base, PREC, strict=False), e[1:-1])
    return '%s**%s' % (self.parenthesize(expr.base, PREC, strict=False), e)

def _print_PythonRational(self, expr):
    if expr.q == 1:
        return str(expr.p)
    else:
        return "%d/%d" % (expr.p, expr.q)

def _latex(self, printer):
    """
    Returns the string representation of 'self'.
    """
    # Check heading:
    if self._headings[1]:
        new_line = []
        for i in range(self._w):
            # Format the item somehow if needed:
            new_line.append(str(self._headings[1][i]))
        self._headings[1] = new_line

    alignments = []
    if self._headings[0]:
        self._headings[0] = [str(x) for x in self._headings[0]]
        alignments = [self._head_align]
    alignments.extend(self._alignments)

    s = r"\begin{tabular}{" + " ".join(alignments) + "}\n"

    if self._headings[1]:
        d = self._headings[1]
        if self._headings[0]:
            d = [""] + d
        first_line = " & ".join(d) + r" \\" + "\n"
        s += first_line
        s += r"\hline" + "\n"
    for i, line in enumerate(self._lines):
        d = []
        for j, x in enumerate(line):
            if self._wipe_zeros and (x in (0, "0")):
                d.append(" ")
                continue
            f = self._column_formats[j]
            if f:
                if isinstance(f, FunctionType):
                    v = f(x, i, j)
                    if v is None:
                        v = printer._print(x)
                else:
                    v = f % x
                d.append(v)
            else:
                v = printer._print(x)
                d.append("$%s$" % v)
        if self._headings[0]:
            d = [self._headings[0][i]] + d
        s += " & ".join(d) + r" \\" + "\n"
    s += r"\end{tabular}"
    return s

def _transform_explike_DE(DE, g, x, order, syms):
    """Converts DE with free parameters into DE with constant coefficients."""
    from sympy.solvers.solveset import linsolve

    eq = []
    highest_coeff = DE.coeff(Derivative(g(x), x, order))
    for i in range(order):
        coeff = DE.coeff(Derivative(g(x), x, i))
        coeff = (coeff / highest_coeff).expand().collect(x)
        for t in Add.make_args(coeff):
            eq.append(t)
    temp = []
    for e in eq:
        if e.has(x):
            break
        elif e.has(Symbol):
            temp.append(e)
    else:
        eq = temp
    if eq:
        sol = dict(zip(syms, (i for s in linsolve(eq, list(syms)) for i in s)))
        if sol:
            DE = DE.subs(sol)
            DE = DE.factor().as_coeff_mul(Derivative)[1][0]
            DE = DE.collect(Derivative(g(x)))
    return DE

def _intersect(self, other):

    if other.is_ComplexRegion:
        # self in rectangular form
        if (not self.polar) and (not other.polar):
            return ComplexRegion(Intersection(self.sets, other.sets))

        # self in polar form
        elif self.polar and other.polar:
            r1, theta1 = self.a_interval, self.b_interval
            r2, theta2 = other.a_interval, other.b_interval
            new_r_interval = Intersection(r1, r2)
            new_theta_interval = Intersection(theta1, theta2)

            # 0 and 2*Pi means the same
            if ((2*S.Pi in theta1 and S.Zero in theta2) or
               (2*S.Pi in theta2 and S.Zero in theta1)):
                new_theta_interval = Union(new_theta_interval,
                                           FiniteSet(0))
            return ComplexRegion(new_r_interval*new_theta_interval,
                                polar=True)


    if other.is_subset(S.Reals):
        new_interval = []
        x = symbols("x", cls=Dummy, real=True)

        # self in rectangular form
        if not self.polar:
            for element in self.psets:
                if S.Zero in element.args[1]:
                    new_interval.append(element.args[0])
            new_interval = Union(*new_interval)
            return Intersection(new_interval, other)

        # self in polar form
        elif self.polar:
            for element in self.psets:
                if S.Zero in element.args[1]:
                    new_interval.append(element.args[0])
                if S.Pi in element.args[1]:
                    new_interval.append(ImageSet(Lambda(x, -x), element.args[0]))
                if S.Zero in element.args[0]:
                    new_interval.append(FiniteSet(0))
            new_interval = Union(*new_interval)
            return Intersection(new_interval, other)

def sum_add(self, other, method=0):
    """Helper function for Sum simplification"""
    from sympy.concrete.summations import Sum
    from sympy import Mul

    #we know this is something in terms of a constant * a sum
    #so we temporarily put the constants inside for simplification
    #then simplify the result
    def __refactor(val):
        args = Mul.make_args(val)
        sumv = next(x for x in args if isinstance(x, Sum))
        constant = Mul(*[x for x in args if x != sumv])
        return Sum(constant * sumv.function, *sumv.limits)

    if isinstance(self, Mul):
        rself = __refactor(self)
    else:
        rself = self

    if isinstance(other, Mul):
        rother = __refactor(other)
    else:
        rother = other

    if type(rself) == type(rother):
        if method == 0:
            if rself.limits == rother.limits:
                return factor_sum(Sum(rself.function + rother.function, *rself.limits))
        elif method == 1:
            if simplify(rself.function - rother.function) == 0:
                if len(rself.limits) == len(rother.limits) == 1:
                    i = rself.limits[0][0]
                    x1 = rself.limits[0][1]
                    y1 = rself.limits[0][2]
                    j = rother.limits[0][0]
                    x2 = rother.limits[0][1]
                    y2 = rother.limits[0][2]

                    if i == j:
                        if x2 == y1 + 1:
                            return factor_sum(Sum(rself.function, (i, x1, y2)))
                        elif x1 == y2 + 1:
                            return factor_sum(Sum(rself.function, (i, x2, y1)))

    return Add(self, other)

def product_mul(self, other, method=0):
    """Helper function for Product simplification"""
    from sympy.concrete.products import Product

    if type(self) == type(other):
        if method == 0:
            if self.limits == other.limits:
                return Product(self.function * other.function, *self.limits)
        elif method == 1:
            if simplify(self.function - other.function) == 0:
                if len(self.limits) == len(other.limits) == 1:
                    i = self.limits[0][0]
                    x1 = self.limits[0][1]
                    y1 = self.limits[0][2]
                    j = other.limits[0][0]
                    x2 = other.limits[0][1]
                    y2 = other.limits[0][2]

                    if i == j:
                        if x2 == y1 + 1:
                            return Product(self.function, (i, x1, y2))
                        elif x1 == y2 + 1:
                            return Product(self.function, (i, x2, y1))

    return Mul(self, other)

def use(expr, func, level=0, args=(), kwargs={}):
    """
    Use ``func`` to transform ``expr`` at the given level.

    Examples
    ========

    >>> from sympy import use, expand
    >>> from sympy.abc import x, y

    >>> f = (x + y)**2*x + 1

    >>> use(f, expand, level=2)
    x*(x**2 + 2*x*y + y**2) + 1
    >>> expand(f)
    x**3 + 2*x**2*y + x*y**2 + 1

    """
    def _use(expr, level):
        if not level:
            return func(expr, *args, **kwargs)
        else:
            if expr.is_Atom:
                return expr
            else:
                level -= 1
                _args = []

                for arg in expr.args:
                    _args.append(_use(arg, level))

                return expr.__class__(*_args)

    return _use(sympify(expr), level)

def _diop_general_pythagorean(var, coeff, t):

    if sign(coeff[var[0]**2]) + sign(coeff[var[1]**2]) + sign(coeff[var[2]**2]) < 0:
        for key in coeff.keys():
            coeff[key] = -coeff[key]

    n = len(var)
    index = 0

    for i, v in enumerate(var):
        if sign(coeff[v**2]) == -1:
            index = i

    m = symbols('%s1:%i' % (t, n), integer=True)
    ith = sum(m_i**2 for m_i in m)
    L = [ith - 2*m[n - 2]**2]
    L.extend([2*m[i]*m[n-2] for i in range(n - 2)])
    sol = L[:index] + [ith] + L[index:]

    lcm = 1
    for i, v in enumerate(var):
        if i == index or (index > 0 and i == 0) or (index == 0 and i == 1):
            lcm = ilcm(lcm, sqrt(abs(coeff[v**2])))
        else:
            s = sqrt(coeff[v**2])
            lcm = ilcm(lcm, s if _odd(s) else s//2)

    for i, v in enumerate(var):
        sol[i] = (lcm*sol[i]) / sqrt(abs(coeff[v**2]))

    return tuple(sol)

def check_linear_2eq_order1(eq, func, func_coef):
    x = func[0].func
    y = func[1].func
    fc = func_coef
    t = list(list(eq[0].atoms(Derivative))[0].atoms(Symbol))[0]
    r = dict()
    # for equations Eq(a1*diff(x(t),t), b1*x(t) + c1*y(t) + d1)
    # and Eq(a2*diff(y(t),t), b2*x(t) + c2*y(t) + d2)
    r['a1'] = fc[0,x(t),1] ; r['a2'] = fc[1,y(t),1]
    r['b1'] = -fc[0,x(t),0]/fc[0,x(t),1] ; r['b2'] = -fc[1,x(t),0]/fc[1,y(t),1]
    r['c1'] = -fc[0,y(t),0]/fc[0,x(t),1] ; r['c2'] = -fc[1,y(t),0]/fc[1,y(t),1]
    forcing = [S(0),S(0)]
    for i in range(2):
        for j in Add.make_args(eq[i]):
            if not j.has(x(t), y(t)):
                forcing[i] += j
    if not (forcing[0].has(t) or forcing[1].has(t)):
        # We can handle homogeneous case and simple constant forcings
        r['d1'] = forcing[0]
        r['d2'] = forcing[1]
    else:
        # Issue #9244: nonhomogeneous linear systems are not supported
        return None

    # Conditions to check for type 6 whose equations are Eq(diff(x(t),t), f(t)*x(t) + g(t)*y(t)) and
    # Eq(diff(y(t),t), a*[f(t) + a*h(t)]x(t) + a*[g(t) - h(t)]*y(t))
    p = 0
    q = 0
    p1 = cancel(r['b2']/(cancel(r['b2']/r['c2']).as_numer_denom()[0]))
    p2 = cancel(r['b1']/(cancel(r['b1']/r['c1']).as_numer_denom()[0]))
    for n, i in enumerate([p1, p2]):
        for j in Mul.make_args(collect_const(i)):
            if not j.has(t):
                q = j
            if q and n==0:
                if ((r['b2']/j - r['b1'])/(r['c1'] - r['c2']/j)) == j:
                    p = 1
            elif q and n==1:
                if ((r['b1']/j - r['b2'])/(r['c2'] - r['c1']/j)) == j:
                    p = 2
    # End of condition for type 6

    if r['d1']!=0 or r['d2']!=0:
        if not r['d1'].has(t) and not r['d2'].has(t):
            if all(not r[k].has(t) for k in 'a1 a2 b1 b2 c1 c2'.split()):
                # Equations for type 2 are Eq(a1*diff(x(t),t),b1*x(t)+c1*y(t)+d1) and Eq(a2*diff(y(t),t),b2*x(t)+c2*y(t)+d2)
                return "type2"
        else:
            return None
    else:
        if all(not r[k].has(t) for k in 'a1 a2 b1 b2 c1 c2'.split()):
             # Equations for type 1 are Eq(a1*diff(x(t),t),b1*x(t)+c1*y(t)) and Eq(a2*diff(y(t),t),b2*x(t)+c2*y(t))
            return "type1"
        else:
            r['b1'] = r['b1']/r['a1'] ; r['b2'] = r['b2']/r['a2']
            r['c1'] = r['c1']/r['a1'] ; r['c2'] = r['c2']/r['a2']
            if (r['b1'] == r['c2']) and (r['c1'] == r['b2']):
                # Equation for type 3 are Eq(diff(x(t),t), f(t)*x(t) + g(t)*y(t)) and Eq(diff(y(t),t), g(t)*x(t) + f(t)*y(t))
                return "type3"
            elif (r['b1'] == r['c2']) and (r['c1'] == -r['b2']) or (r['b1'] == -r['c2']) and (r['c1'] == r['b2']):
                # Equation for type 4 are Eq(diff(x(t),t), f(t)*x(t) + g(t)*y(t)) and Eq(diff(y(t),t), -g(t)*x(t) + f(t)*y(t))
                return "type4"
            elif (not cancel(r['b2']/r['c1']).has(t) and not cancel((r['c2']-r['b1'])/r['c1']).has(t)) \
            or (not cancel(r['b1']/r['c2']).has(t) and not cancel((r['c1']-r['b2'])/r['c2']).has(t)):
                # Equations for type 5 are Eq(diff(x(t),t), f(t)*x(t) + g(t)*y(t)) and Eq(diff(y(t),t), a*g(t)*x(t) + [f(t) + b*g(t)]*y(t)
                return "type5"
            elif p:
                return "type6"
            else:
                # Equations for type 7 are Eq(diff(x(t),t), f(t)*x(t) + g(t)*y(t)) and Eq(diff(y(t),t), h(t)*x(t) + p(t)*y(t))
                return "type7"

def _solve_as_poly(f, symbol, domain=S.Complexes):
    """
    Solve the equation using polynomial techniques if it already is a
    polynomial equation or, with a change of variables, can be made so.
    """
    result = None
    if f.is_polynomial(symbol):
        solns = roots(f, symbol, cubics=True, quartics=True,
                      quintics=True, domain='EX')
        num_roots = sum(solns.values())
        if degree(f, symbol) <= num_roots:
            result = FiniteSet(*solns.keys())
        else:
            poly = Poly(f, symbol)
            solns = poly.all_roots()
            if poly.degree() <= len(solns):
                result = FiniteSet(*solns)
            else:
                result = ConditionSet(symbol, Eq(f, 0), domain)
    else:
        poly = Poly(f)
        if poly is None:
            result = ConditionSet(symbol, Eq(f, 0), domain)
        gens = [g for g in poly.gens if g.has(symbol)]

        if len(gens) == 1:
            poly = Poly(poly, gens[0])
            gen = poly.gen
            deg = poly.degree()
            poly = Poly(poly.as_expr(), poly.gen, composite=True)
            poly_solns = FiniteSet(*roots(poly, cubics=True, quartics=True,
                                          quintics=True).keys())

            if len(poly_solns) < deg:
                result = ConditionSet(symbol, Eq(f, 0), domain)

            if gen != symbol:
                y = Dummy('y')
                inverter = invert_real if domain.is_subset(S.Reals) else invert_complex
                lhs, rhs_s = inverter(gen, y, symbol)
                if lhs == symbol:
                    result = Union(*[rhs_s.subs(y, s) for s in poly_solns])
                else:
                    result = ConditionSet(symbol, Eq(f, 0), domain)
        else:
            result = ConditionSet(symbol, Eq(f, 0), domain)

    if result is not None:
        if isinstance(result, FiniteSet):
            # this is to simplify solutions like -sqrt(-I) to sqrt(2)/2
            # - sqrt(2)*I/2. We are not expanding for solution with free
            # variables because that makes the solution more complicated. For
            # example expand_complex(a) returns re(a) + I*im(a)
            if all([s.free_symbols == set() and not isinstance(s, RootOf)
                    for s in result]):
                s = Dummy('s')
                result = imageset(Lambda(s, expand_complex(s)), result)
        if isinstance(result, FiniteSet):
            result = result.intersection(domain)
        return result
    else:
        return ConditionSet(symbol, Eq(f, 0), domain)

def doit(self, **hints):
    arg = self.args[0]
    condition = self._condition

    if not arg.has(RandomSymbol):
        return S.Zero

    if isinstance(arg, RandomSymbol):
        return self
    elif isinstance(arg, Add):
        rv = []
        for a in arg.args:
            if a.has(RandomSymbol):
                rv.append(a)
        variances = Add(*map(lambda xv: Variance(xv, condition).doit(), rv))
        map_to_covar = lambda x: 2*Covariance(*x, condition=condition).doit()
        covariances = Add(*map(map_to_covar, itertools.combinations(rv, 2)))
        return variances + covariances
    elif isinstance(arg, Mul):
        nonrv = []
        rv = []
        for a in arg.args:
            if a.has(RandomSymbol):
                rv.append(a)
            else:
                nonrv.append(a**2)
        if len(rv) == 0:
            return S.Zero
        return Mul(*nonrv)*Variance(Mul(*rv), condition)

    # this expression contains a RandomSymbol somehow:
    return self

def wrap_code(self, routine, helpers=[]):
    if self.filepath:
        workdir = os.path.abspath(self.filepath)
    else:
        workdir = tempfile.mkdtemp("_sympy_compile")
    if not os.access(workdir, os.F_OK):
        os.mkdir(workdir)
    oldwork = os.getcwd()
    os.chdir(workdir)
    try:
        sys.path.append(workdir)
        self._generate_code(routine, helpers)
        self._prepare_files(routine)
        self._process_files(routine)
        mod = __import__(self.module_name)
    finally:
        sys.path.remove(workdir)
        CodeWrapper._module_counter += 1
        os.chdir(oldwork)
        if not self.filepath:
            try:
                shutil.rmtree(workdir)
            except OSError:
                # Could be some issues on Windows
                pass

    return self._get_wrapped_function(mod, routine.name)

def _get_header(self):
    """Writes a common header for the generated files."""
    code_lines = []
    code_lines.append("/" + "*"*78 + '\n')
    tmp = header_comment % {"version": sympy_version,
                            "project": self.project}
    for line in tmp.splitlines():
        code_lines.append(" *%s*\n" % line.center(76))
    code_lines.append(" " + "*"*78 + "/\n")
    return code_lines

def _declare_locals(self, routine):

    # Compose a list of symbols to be dereferenced in the function
    # body. These are the arguments that were passed by a reference
    # pointer, excluding arrays.
    dereference = []
    for arg in routine.arguments:
        if isinstance(arg, ResultBase) and not arg.dimensions:
            dereference.append(arg.name)

    code_lines = []
    for result in routine.local_vars:

        # local variables that are simple symbols such as those used as indices into
        # for loops are defined declared elsewhere.
        if not isinstance(result, Result):
            continue

        if result.name != result.result_var:
            raise CodeGen("Result variable and name should match: {}".format(result))
        assign_to = result.name
        t = result.get_datatype('c')
        if isinstance(result.expr, (MatrixBase, MatrixExpr)):
            dims = result.expr.shape
            if dims[1] != 1:
                raise CodeGenError("Only column vectors are supported in local variabels. Local result {} has dimensions {}".format(result, dims))
            code_lines.append("{0} {1}[{2}];\n".format(t, str(assign_to), dims[0]))
            prefix = ""
        else:
            prefix = "const {0} ".format(t)

        constants, not_c, c_expr = self._printer_method_with_settings(
            'doprint', dict(human=False, dereference=dereference),
            result.expr, assign_to=assign_to)

        for name, value in sorted(constants, key=str):
            code_lines.append("double const %s = %s;\n" % (name, value))

        code_lines.append("{}{}\n".format(prefix, c_expr))

    return code_lines

